function blockedPulseState(state) {
  if (!state._umlBlockedPulse) {
    state._umlBlockedPulse = { nextAt: 0 }
  }
  return state._umlBlockedPulse
}

function v3x(v) {
  return Array.isArray(v) ? v[0] : v.x
}
function v3z(v) {
  return Array.isArray(v) ? v[2] : v.z
}

function isParkourCylinderL(entityId) {
  if (!entityId) return false
  return String(entityId).indexOf('parkour_cylinder_l') >= 0
}

/** Parkour cylinder wedge at z≈−36: close contact, not approach at z≈−31. */
function tightCylinderUmlSite(input, blockHit, speed) {
  if (!blockHit.hit) return false
  var carZ = v3z(input.position)
  if (carZ >= -34.8 || carZ <= -38.2) return false
  if (blockHit.distance >= 2.8) return false
  if (!isParkourCylinderL(blockHit.entityId)) return false
  if (speed > 1.35) return false
  return true
}

var maneuver = {
  isOn: function () { return this.expires > Date.now(); },
  trigger: function (vector, timeMs) {
    this.expires = Date.now() + timeMs
    this.vector = vector
  },
  reset: function () {
    this.expires = 0
    this.vector = undefined
  },
  expires: 0,
  vector: undefined,
}

function obstacleUrgency(closest) {
  var CRITICAL = 6
  var CALM = 12
  if (closest >= CALM) return 0
  if (closest <= CRITICAL) return 1
  return 1 - (closest - CRITICAL) / (CALM - CRITICAL)
}

function maneuverLockMs(deviation, urgency) {
  var base = 400 - Math.min(340, deviation * 300)
  return Math.max(120, Math.floor(base + urgency * 70))
}

function sanitizeObstacleHit(input, hit) {
  if (!hit || !hit.hit) return hit
  if (hit.entityId && hit.entityId === input.entityId) {
    return { hit: false, distance: 0, entityId: '' }
  }
  if (hit.distance < 0.35) {
    return { hit: false, distance: 0, entityId: '' }
  }
  return hit
}

function raycastObstacle(api, input, origin, direction, distance, options) {
  var hit = api.raycastSpread(origin, direction, distance, 2, 10, options || { visualize: false })
  return sanitizeObstacleHit(input, hit)
}

function transform(input, dt, params, state, api) {
  if (
    api.getAction(input, 'steer_left') ||
    api.getAction(input, 'steer_right') ||
    api.getAction(input, 'throttle') ||
    api.getAction(input, 'brake')
  ) {
    return
  }

  if (!input.target || !input.target.pose || !input.target.pose.position) return {}

  // Upstream (e.g. wanderer) owns input.target.pose; use it for path scoring only.
  var goalPos = input.target.pose.position
  var truePos = goalPos
  if (typeof params.id === 'string' && params.id.length > 0) {
    var liveFollow = api.getWorldPosition(params.id)
    if (liveFollow) truePos = liveFollow
  }
  // Never snap input.target to a follow entity here — that pins the red debug line (and direction) on "car".
  var toTrue = api.vec.subtract(truePos, input.position)
  var distTrue = api.vec.length(toTrue)
  input.target.distance = distTrue

  if (distTrue < 5) {
    maneuver.reset()
    delete input.actions._uml_maneuver
    return
  }

  var up = api.getUpVector(input.rotation)
  var forward = api.getForwardVector(input.rotation)
  forward = api.vec.normalize(api.vec.projectOntoPlane(forward, up))
  var flatToTrue = api.vec.normalize(api.vec.projectOntoPlane(toTrue, up))
  var speedNow = api.vec.length(input.velocity)
  var frontOffset = distTrue < 28 ? 2.2 : 4.5
  var frontPosition = api.vec.offsetAlong(input.position, forward, frontOffset)
  var goalRayDist = Math.min(distTrue, 24)
  var goalHitEarly = raycastObstacle(api, input, input.position, flatToTrue, goalRayDist, {
    visualize: false,
  })
  var earlyGoalBlocked = goalHitEarly.hit && goalHitEarly.distance < distTrue - 0.8
  var pathGoal = truePos
  if (goalHitEarly.hit && goalHitEarly.distance < distTrue - 0.5) {
    // Past the blocker (thick obstacles need more than hit.distance + small slack).
    var pastBlock = goalHitEarly.distance + 10
    if (pastBlock > distTrue - 2) pastBlock = distTrue - 2
    pathGoal = api.vec.add(input.position, api.vec.scale(flatToTrue, pastBlock))
  }

  if (maneuver.isOn() && maneuver.vector) {
    if (api.vec.length(api.vec.subtract(maneuver.vector, input.position)) < 4) {
      maneuver.reset()
    } else if (api.vec.length(api.vec.subtract(truePos, maneuver.vector)) > distTrue + 10) {
      maneuver.reset()
    }
  }

  if (maneuver.isOn() && maneuver.vector) {
    var checkDist = Math.min(16, Math.max(8, distTrue))
    var frontClear = raycastObstacle(api, input, frontPosition, forward, checkDist, { visualize: false })
    var bumperHit = raycastObstacle(api, input, input.position, forward, 4, { visualize: false })
    var closeObDist = 999
    if (bumperHit.hit) closeObDist = bumperHit.distance
    if (goalHitEarly.hit && goalHitEarly.distance < closeObDist) closeObDist = goalHitEarly.distance
    if (frontClear.hit && frontClear.distance < closeObDist) closeObDist = frontClear.distance
    if (
      tightCylinderUmlSite(input, bumperHit, speedNow) &&
      Math.abs(v3x(maneuver.vector) - v3x(input.position)) > 4
    ) {
      maneuver.reset()
    } else if (!frontClear.hit && api.vec.angleBetween(forward, flatToTrue) < 0.45) {
      maneuver.reset()
    } else if (
      pathClear(api, input, input.position, maneuver.vector, up) &&
      (earlyGoalBlocked || pathClear(api, input, maneuver.vector, pathGoal, up))
    ) {
      var toLocked = api.vec.projectOntoPlane(api.vec.subtract(maneuver.vector, input.position), up)
      var stallSpeed = api.vec.length(input.velocity)
      if (
        earlyGoalBlocked &&
        closeObDist < 2.05 &&
        stallSpeed < 2.5 &&
        api.vec.dot(toLocked, forward) < 1.15
      ) {
        maneuver.reset()
      } else {
        input.target.pose.position = maneuver.vector
        input.actions._uml_maneuver = 1
        if (earlyGoalBlocked && closeObDist < 2.05) {
          input.actions._uml_goal_block = 1
          input.actions._uml_closest = closeObDist
        } else {
          delete input.actions._uml_goal_block
          delete input.actions._uml_closest
        }
        api.watch('uml.aimX', v3x(maneuver.vector))
        api.watch('uml.aimZ', v3z(maneuver.vector))
        return
      }
    }
    maneuver.reset()
  }

  var lookahead = distTrue - 6
  if (lookahead < 10) lookahead = 10
  if (lookahead > 22) lookahead = 22

  var frontHit = raycastObstacle(api, input, frontPosition, forward, lookahead, {
    visualize: true,
    hitColor: 'orange',
    missColor: 'cyan',
  })
  var goalHit = goalHitEarly
  var goalBlocked = goalHit.hit && goalHit.distance < distTrue - 0.8
  var blockHit = frontHit
  if (goalBlocked && (!frontHit.hit || goalHit.distance < frontHit.distance + 3)) {
    blockHit = goalHit
    api.watch('uml.goalBlock', 1)
  } else {
    api.watch('uml.goalBlock', 0)
    goalBlocked = false
  }
  api.watch('uml.lookahead', lookahead)
  api.watch('uml.frontHit', blockHit.hit ? 1 : 0)
  api.watch('uml.frontDist', blockHit.hit ? blockHit.distance : -1)
  api.watch('uml.frontEnt', blockHit.hit ? blockHit.entityId : '')
  if (!blockHit.hit) {
    api.watch('uml.maneuver', 0)
    delete input.actions._uml_maneuver
    delete input.actions._uml_blocked
    delete input.actions._uml_goal_block
    delete input.actions._uml_closest
    return {}
  }

  var bumperClose = raycastObstacle(api, input, input.position, forward, 4, { visualize: false })
  var pickCloseDist = blockHit.distance
  if (bumperClose.hit && bumperClose.distance < pickCloseDist) pickCloseDist = bumperClose.distance
  if (goalBlocked && pickCloseDist < 2.05) {
    input.actions._uml_goal_block = 1
    input.actions._uml_closest = pickCloseDist
  } else {
    delete input.actions._uml_goal_block
    delete input.actions._uml_closest
  }

  // Goal-blocked rays are straight at the obstacle; lateral fan needs the bumper forward axis.
  var scanFromGoalRay = blockHit === goalHit && !frontHit.hit
  var scanOrigin = scanFromGoalRay ? input.position : frontPosition
  var scanForward = scanFromGoalRay ? flatToTrue : forward
  var scanDist = scanFromGoalRay ? Math.min(goalHit.distance + 2, 18) : lookahead
  var blockForTight = blockHit
  if (bumperClose.hit && isParkourCylinderL(bumperClose.entityId)) {
    if (!blockForTight.hit || bumperClose.distance < blockForTight.distance) {
      blockForTight = bumperClose
    }
  }
  var tightUmlSite = tightCylinderUmlSite(input, blockForTight, speedNow)
  var picked = undefined
  if (tightUmlSite) {
    picked = tightCylinderFlankFallback(
      api,
      input,
      input.position,
      scanForward,
      up,
      truePos,
      distTrue,
      pathGoal,
    )
  } else if (goalBlocked) {
    picked = flankFallback(
      api,
      input,
      input.position,
      scanForward,
      up,
      truePos,
      distTrue,
      blockHit.distance,
      pathGoal,
      goalBlocked,
    )
  }
  if (!picked && !tightUmlSite) {
    picked = findCorrectionVector(
      api,
      input,
      input.position,
      scanOrigin,
      scanForward,
      scanDist,
      input.rotation,
      truePos,
      distTrue,
      flatToTrue,
      blockHit.distance,
      pathGoal,
      goalBlocked,
    )
  }
  if (!picked && tightUmlSite) {
    picked = tightCylinderForcedFlank(api, input, input.position, scanForward, up, distTrue)
  }
  if (!picked && goalBlocked && !tightUmlSite) {
    picked = flankFallback(
      api,
      input,
      input.position,
      scanForward,
      up,
      truePos,
      distTrue,
      blockHit.distance,
      pathGoal,
      goalBlocked,
    )
  }
  if (!picked) {
    api.watch('uml.maneuver', 0)
    delete input.actions._uml_maneuver
    var bp = blockedPulseState(state)
    var now = Date.now()
    if (blockHit.distance < 2.05 && now < bp.nextAt) {
      delete input.actions._uml_blocked
    } else {
      input.actions._uml_blocked = 1
      if (blockHit.distance < 2.05) bp.nextAt = now + 880
    }
    if (tightUmlSite) return
    return {}
  }

  input.target.pose.position = picked.candidate
  api.watch('uml.maneuver', 1)
  api.watch('uml.aimX', v3x(picked.candidate))
  api.watch('uml.aimZ', v3z(picked.candidate))
  input.actions._uml_maneuver = 1
  delete input.actions._uml_blocked
  maneuver.trigger(picked.candidate, maneuverLockMs(picked.deviation, obstacleUrgency(blockHit.distance)))
  return {}
}

function pathClear(api, input, from, to, up) {
  return pathClearSlack(api, input, from, to, up, 1.2)
}

function pathClearSlack(api, input, from, to, up, slack) {
  var delta = api.vec.subtract(to, from)
  var len = api.vec.length(delta)
  if (len < 0.5) return true
  var dir = api.vec.normalize(api.vec.projectOntoPlane(delta, up))
  var hit = raycastObstacle(api, input, from, dir, len, { visualize: false })
  return !hit.hit || hit.distance > len - slack
}

function tightCylinderFlankFallback(api, input, carPos, forward, up, truePos, distTrue, pathGoal) {
  var lateral = api.vec.normalize(api.vec.cross(up, forward))
  var offsets = [3.2, -3.2, 4, -4, 5, -5]
  var i
  for (i = 0; i < offsets.length; i++) {
    var candidate = api.vec.add(carPos, api.vec.scale(lateral, offsets[i]))
    if (!pathClearSlack(api, input, carPos, candidate, up, 0.55)) continue
    if (!pathClearSlack(api, input, candidate, pathGoal, up, 0.85)) continue
    var toTrue = api.vec.length(api.vec.subtract(truePos, candidate))
    if (toTrue > distTrue + 14) continue
    return { candidate: candidate, deviation: 0.65, candidateDist: toTrue }
  }
  return undefined
}

function tightCylinderForcedFlank(api, input, carPos, forward, up, distTrue) {
  var lateral = api.vec.normalize(api.vec.cross(up, forward))
  var carX = v3x(carPos)
  var prefer = carX >= 0 ? 1 : -1
  var offsets = [3.4 * prefer, -3.4 * prefer, 4.2 * prefer, -4.2 * prefer]
  var i
  for (i = 0; i < offsets.length; i++) {
    var candidate = api.vec.add(carPos, api.vec.scale(lateral, offsets[i]))
    if (!pathClearSlack(api, input, carPos, candidate, up, 0.42)) continue
    if (Math.abs(v3x(candidate) - carX) < 2.2) continue
    return { candidate: candidate, deviation: 0.72, candidateDist: distTrue }
  }
  return undefined
}

function flankFallback(api, input, carPos, forward, up, truePos, distTrue, closestObstacle, pathGoal, goalBlocked) {
  var urgency = obstacleUrgency(closestObstacle)
  var lateral = api.vec.normalize(api.vec.cross(up, forward))
  var offset = goalBlocked ? 14 + urgency * 10 : 8 + urgency * 10
  if (goalBlocked && closestObstacle < 2.8) offset += 4
  var options = [
    api.vec.add(carPos, api.vec.scale(lateral, offset)),
    api.vec.add(carPos, api.vec.scale(lateral, -offset)),
  ]
  if (goalBlocked) {
    var ahead = closestObstacle < 3 ? 10 + urgency * 6 : 7 + urgency * 5
    var midLat = 5.5 + urgency * 2
    var midAhead = 5 + urgency * 3
    options = [
      api.vec.add(carPos, api.vec.add(api.vec.scale(lateral, midLat), api.vec.scale(forward, midAhead))),
      api.vec.add(carPos, api.vec.add(api.vec.scale(lateral, -midLat), api.vec.scale(forward, midAhead))),
      api.vec.add(carPos, api.vec.add(api.vec.scale(lateral, offset), api.vec.scale(forward, ahead))),
      api.vec.add(carPos, api.vec.add(api.vec.scale(lateral, -offset), api.vec.scale(forward, ahead))),
      api.vec.add(carPos, api.vec.scale(lateral, offset)),
      api.vec.add(carPos, api.vec.scale(lateral, -offset)),
    ]
  }
  var i
  for (i = 0; i < options.length; i++) {
    var candidate = options[i]
    if (!pathClear(api, input, carPos, candidate, up)) continue
    if (!goalBlocked && !pathClear(api, input, candidate, pathGoal, up)) continue
    if (goalBlocked && Math.abs(v3x(candidate) - v3x(carPos)) < 4) continue
    if (goalBlocked && closestObstacle < 2.05) {
      var toCandClose = api.vec.projectOntoPlane(api.vec.subtract(candidate, carPos), up)
      if (api.vec.dot(toCandClose, forward) < 1.15) continue
    } else if (goalBlocked && closestObstacle < 4) {
      var toCand = api.vec.projectOntoPlane(api.vec.subtract(candidate, carPos), up)
      var ahead = api.vec.dot(toCand, forward)
      if (ahead < 2.5 && Math.abs(v3x(toCand)) > 6) continue
    }
    var toTrue = api.vec.length(api.vec.subtract(truePos, candidate))
    if (toTrue > distTrue + 14) continue
    return { candidate: candidate, deviation: 0.8, candidateDist: toTrue }
  }
  return undefined
}

function findCorrectionVector(
  api,
  input,
  carPos,
  origin,
  forward,
  distance,
  entityRotation,
  truePos,
  distTrue,
  flatToTrue,
  closestObstacle,
  pathGoal,
  goalBlocked,
) {
  var up = api.getUpVector(entityRotation)
  var urgency = obstacleUrgency(closestObstacle)
  var spread = 0.95 + urgency * 1.35
  var steps = 44
  var results = []
  var i

  var ALIGN_WEIGHT = 3.2 - urgency * 1.1
  var DEVIATION_SQ_WEIGHT = 3.4 + (1 - urgency) * 1.8
  var CLEAR_WEIGHT = 0.22 + urgency * 0.62

  for (i = 0; i <= steps; i++) {
    var angle = -spread + (2 * spread * i) / steps
    var result = evaluateVector(api, input, origin, forward, up, distance, angle)
    var flatDir = api.vec.normalize(api.vec.projectOntoPlane(result.rotation, up))
    var deviation = api.vec.angleBetween(flatDir, flatToTrue)
    var alignment = 1 - deviation / Math.PI
    var clearance = result.raycast.hit ? result.raycast.distance / distance : 1.25

    if (clearance < 0.32 && urgency < 0.95) continue

    var pushDist = distance * (0.42 + 0.28 * (1 - urgency)) + urgency * 6
    if (deviation > 0.35) pushDist += deviation * 4
    var candidate = api.vec.add(origin, api.vec.scale(api.vec.normalize(result.rotation), pushDist))
    if (!pathClear(api, input, carPos, candidate, up)) continue
    if (goalBlocked && Math.abs(v3x(candidate) - v3x(carPos)) < 4.5) continue
    if (!goalBlocked && !pathClear(api, input, candidate, pathGoal, up)) continue
    var candidateDist = api.vec.length(api.vec.subtract(truePos, candidate))

    var score =
      alignment * ALIGN_WEIGHT +
      clearance * CLEAR_WEIGHT -
      deviation * deviation * DEVIATION_SQ_WEIGHT

    if (!result.raycast.hit) score += 0.2
    if (deviation > 0.25 && urgency > 0.4) score += deviation * 0.35
    if (candidateDist > distTrue + 4) score -= 1.2
    if (candidateDist < distTrue) score += 0.25

    results.push({ score: score, candidate: candidate, deviation: deviation, candidateDist: candidateDist })
  }

  if (results.length === 0) return undefined

  results.sort(function (a, b) {
    if (Math.abs(a.score - b.score) > 0.03) return b.score - a.score
    if (Math.abs(a.deviation - b.deviation) > 0.02) return a.deviation - b.deviation
    return a.candidateDist - b.candidateDist
  })

  return results[0]
}

function evaluateVector(api, input, origin, forward, up, distance, angle) {
  var direction = api.vec.rotateAroundAxis(forward, up, angle)
  return {
    rotation: direction,
    raycast: raycastObstacle(api, input, origin, direction, distance, { visualize: false }),
  }
}

function transform(input, dt, params, state, api) {
  if (!input.target || !input.target.pose || !input.target.pose.position) return {}
  api.visualizeLine(input.position, input.target.pose.position, '#ffcc00')
  return {}
}

function hugBackoffState(state) {
  if (!state._dirHugBackoff) {
    state._dirHugBackoff = { nextPulseAt: 0 }
  }
  return state._dirHugBackoff
}

function wedgeEscapeState(state) {
  if (!state._dirWedgeEscape) {
    state._dirWedgeEscape = { active: false }
  }
  return state._dirWedgeEscape
}

function backOffState(state) {
  if (!state._dirBackOff) {
    state._dirBackOff = { until: 0, steerForward: 0, phase: 'forward' }
  }
  var b = state._dirBackOff
  if (!b.isOn) {
    b.isOn = function () { return this.until > Date.now() }
    b.trigger = function (steerForward, holdMs) {
      this.until = Date.now() + (holdMs || 480)
      this.steerForward = steerForward
      this.phase = 'forward'
    }
  }
  return b
}

function clampSteer(v) {
  if (v > 1) return 1
  if (v < -1) return -1
  return v
}

function resolveTrueFollowPosition(input, params, api) {
  if (typeof params.id === 'string' && params.id.length > 0) {
    var live = api.getWorldPosition(params.id)
    if (live) return live
  }
  if (input.target && input.target.pose && input.target.pose.position) {
    return input.target.pose.position
  }
  return null
}

function transform(input, dt, params, state, api) {
  if (
    api.getAction(input, 'steer_left') ||
    api.getAction(input, 'steer_right') ||
    api.getAction(input, 'throttle') ||
    api.getAction(input, 'brake')
  ) {
    return
  }

  delete input.actions._obstacle_escape

  var truePos = resolveTrueFollowPosition(input, params, api)
  if (!truePos) return {}

  if (!input.target || !input.target.pose || !input.target.pose.position) {
    input.target = { pose: { position: truePos }, id: params.id }
  }

  var backOff = backOffState(state)
  var wedgeEscape = wedgeEscapeState(state)
  var carZWedge = input.position[2] != null ? input.position[2] : input.position.z
  var posXWedge = input.position[0] != null ? input.position[0] : input.position.x
  var tightSiteNow = carZWedge < -34.8 && carZWedge > -38.2
  if (wedgeEscape.active && Math.abs(posXWedge) > 2.5 && carZWedge < -38.5) {
    wedgeEscape.active = false
    delete input.actions._dir_hug_degen
    backOff.until = 0
  }
  var toTrue = api.vec.subtract(truePos, input.position)
  var distTrue = api.vec.length(toTrue)

  var up = api.getUpVector(input.rotation)
  var forward = api.getForwardVector(input.rotation)
  forward = api.vec.normalize(api.vec.projectOntoPlane(forward, up))
  var flatToTrue = api.vec.normalize(api.vec.projectOntoPlane(toTrue, up))

  var aimPos = input.target.pose.position
  var toAim = api.vec.subtract(aimPos, input.position)
  toAim = api.vec.normalize(api.vec.projectOntoPlane(toAim, up))

  var signedSteer = api.vec.signedAngleAroundAxis(forward, toAim, up)
  var forwardSpeed = api.vec.getForwardSpeed(input.velocity, forward)
  var aimAwayFromTrue = api.vec.angleBetween(toAim, flatToTrue)

  if (forwardSpeed < -0.2) signedSteer = -signedSteer
  var steerGain = 1 + Math.min(2.2, aimAwayFromTrue * 1.8)
  if (input.actions._uml_maneuver) steerGain += 1.8
  if (Math.abs(signedSteer) >= 0.001) {
    input.actions.steering_angle = clampSteer(signedSteer * steerGain)
  }

  if (backOff.isOn()) {
    api.watch('dir.backoff', 1)
    input.actions._obstacle_escape = 1
    var esc = clampSteer(backOff.steerForward * 2.5)
    var probeOrigin = api.vec.offsetAlong(input.position, forward, 2.5)
    var probe = api.raycastSpread(probeOrigin, forward, 2.2, 1.4, 8, { visualize: false })
    var wedgeHold = wedgeEscape.active
    if (wedgeHold) {
      var aimXEsc = aimPos[0] != null ? aimPos[0] : aimPos.x
      var posXEsc = input.position[0] != null ? input.position[0] : input.position.x
      var peelSign = aimXEsc >= posXEsc ? 0.92 : -0.92
      if (tightSiteNow) {
        var wedgeBump = api.raycastSpread(input.position, forward, 2.5, 1.4, 8, { visualize: false })
        if (wedgeBump.hit && wedgeBump.entityId) {
          var obPosEsc = api.getWorldPosition(wedgeBump.entityId)
          if (obPosEsc) {
            var obXEsc = obPosEsc[0] != null ? obPosEsc[0] : obPosEsc.x
            peelSign = posXEsc >= obXEsc ? 0.92 : -0.92
          }
        }
      }
      esc = clampSteer(peelSign * 2.5)
      input.actions._dir_hug_degen = 1
    }
    if (!probe.hit && !wedgeHold) {
      backOff.until = 0
      wedgeEscape.active = false
      api.watch('dir.backoff', 0)
      return
    }
    if (forwardSpeed < -0.95 && !wedgeHold) {
      backOff.until = 0
      wedgeEscape.active = false
      api.watch('dir.backoff', 0)
      return
    }
    if (forwardSpeed > 0.35) {
      backOff.phase = 'forward'
      input.actions.throttle = 0
      input.actions.brake = 0.62
      input.actions.steering_angle = esc
    } else if (forwardSpeed < -0.25) {
      backOff.phase = 'reverse'
      input.actions.throttle = 0
      input.actions.brake = wedgeHold ? 0.52 : 0.38
      input.actions.steering_angle = -esc
    } else if (backOff.phase === 'forward') {
      input.actions.throttle = 0
      input.actions.brake = 0.58
      input.actions.steering_angle = esc
      if (forwardSpeed < 0.06) backOff.phase = 'reverse'
    } else {
      input.actions.throttle = 0
      input.actions.brake = 0.36
      input.actions.steering_angle = -esc
    }
    return
  }

  var front = api.vec.offsetAlong(input.position, forward, 3)
  var frontBlock = api.raycastSpread(front, forward, 2.5, 1.6, 10, { visualize: false })
  var carZFront = input.position[2] != null ? input.position[2] : input.position.z
  var tightFrontSite = carZFront < -34.8 && carZFront > -38.2
  if (tightFrontSite) {
    var bumperBlock = api.raycastSpread(input.position, forward, 2.5, 1.4, 8, { visualize: false })
    if (
      bumperBlock.hit &&
      bumperBlock.entityId &&
      String(bumperBlock.entityId).indexOf('cylinder') >= 0 &&
      (!frontBlock.hit || bumperBlock.distance < frontBlock.distance)
    ) {
      frontBlock = bumperBlock
    }
  }
  var speed = api.vec.length(input.velocity)

  if (frontBlock.hit === true) {
    api.watch('dir.frontDist', frontBlock.distance)
    var steerNow = input.actions.steering_angle
    if (steerNow == null || Math.abs(steerNow) < 0.02) steerNow = signedSteer
    var close = frontBlock.distance < 1.55
    var holdMs = close ? 520 : 420
    var needBackOff =
      frontBlock.distance < 2.35 &&
      (close || speed < 3.5 || frontBlock.distance < 2.05)
    var carZNeed = input.position[2] != null ? input.position[2] : input.position.z
    var tightNeedSite = carZNeed < -34.8 && carZNeed > -38.2
    var needDegenerateCylinder =
      tightNeedSite &&
      frontBlock.entityId &&
      String(frontBlock.entityId).indexOf('cylinder') >= 0 &&
      frontBlock.distance < (speed < 1.25 ? 2.05 : 0.35) &&
      speed < 1.25
    // Umlenker owns lateral detours while a flank maneuver is active (except tight-cylinder wedge peel).
    if (input.actions._uml_maneuver && !input.actions._uml_blocked && !needDegenerateCylinder) {
      needBackOff = false
    }
    if (input.actions._uml_blocked) {
      needBackOff = true
    }
    if (needBackOff) {
      api.watch('dir.backoff', 1)
      var triggerSteer = clampSteer(steerNow)
      if (needDegenerateCylinder) {
        var aimXNeed = aimPos[0] != null ? aimPos[0] : aimPos.x
        var posXNeed = input.position[0] != null ? input.position[0] : input.position.x
        triggerSteer = aimXNeed >= posXNeed ? 0.85 : -0.85
        input.actions._dir_hug_degen = 1
        wedgeEscape.active = true
        holdMs = 920
      }
      backOff.trigger(triggerSteer, holdMs)
      return
    }
    api.watch('dir.backoff', 0)
    if (!input.actions._uml_maneuver) {
      input.actions.throttle = 0
    }
  } else {
    api.watch('dir.backoff', 0)
  }

  var hug = hugBackoffState(state)
  var umlClosest = input.actions._uml_closest
  var carZ = input.position[2] != null ? input.position[2] : input.position.z
  var tightCylinderSite = carZ < -34.8 && carZ > -38.2
  var dirDegenerateBumper =
    frontBlock.hit === true &&
    (frontBlock.distance < 0.35 || (tightCylinderSite && frontBlock.distance < 2.05))
  var frontHitCylinder =
    frontBlock.hit === true &&
    frontBlock.entityId &&
    String(frontBlock.entityId).indexOf('cylinder') >= 0
  var tightDegenerateHug =
    tightCylinderSite && frontHitCylinder && dirDegenerateBumper
  var hugGoalBlocked =
    input.actions._uml_goal_block &&
    umlClosest != null &&
    umlClosest < 2.85 &&
    (frontBlock.hit !== true || tightDegenerateHug)
  var tightBlockedHug =
    tightDegenerateHug && input.actions._uml_blocked && !input.actions._uml_maneuver
  if (
    !backOff.isOn() &&
    (input.actions._uml_maneuver || tightBlockedHug) &&
    (!input.actions._uml_blocked || tightBlockedHug) &&
    Date.now() >= hug.nextPulseAt &&
    ((tightDegenerateHug && speed < 1.25) || (hugGoalBlocked && speed < 2.4))
  ) {
    var hugHold = umlClosest < 1.85 ? 460 : 380
    if (tightDegenerateHug) hugHold = 620
    hug.nextPulseAt = Date.now() + (tightDegenerateHug ? 520 : 860)
    api.watch('dir.backoff', 1)
    var hugSteer = clampSteer(signedSteer)
    if (tightDegenerateHug) {
      var aimX = aimPos[0] != null ? aimPos[0] : aimPos.x
      var posX = input.position[0] != null ? input.position[0] : input.position.x
      hugSteer = aimX >= posX ? 0.85 : -0.85
    }
    if (tightDegenerateHug) {
      input.actions._dir_hug_degen = 1
      wedgeEscape.active = true
    }
    backOff.trigger(hugSteer, hugHold)
    return
  }

  var targetSpeed = distTrue < 30 ? 9 : 42
  if (aimAwayFromTrue > 0.45) targetSpeed = Math.min(targetSpeed, 18 + 12 * (1 - aimAwayFromTrue))
  if (frontBlock.hit && frontBlock.distance < 4 && !input.actions._uml_maneuver) {
    targetSpeed = Math.min(targetSpeed, 6)
  }
  if (input.actions._uml_maneuver && frontBlock.hit && frontBlock.distance < 3.5) {
    targetSpeed = Math.min(targetSpeed, 9)
  }
  var posXThrottle = input.position[0] != null ? input.position[0] : input.position.x
  var cylinderPeelPending =
    frontHitCylinder &&
    frontBlock.hit &&
    frontBlock.distance < 4.2 &&
    Math.abs(posXThrottle) <= 2.5 &&
    carZ > -44.5
  var approachRunaway =
    Math.abs(posXThrottle) > 2.5 &&
    carZ > -38.5 &&
    forwardSpeed > 0.85 &&
    api.vec.dot(forward, flatToTrue) < 0.35
  if (
    (tightDegenerateHug ||
      (wedgeEscape.active && tightSiteNow) ||
      cylinderPeelPending ||
      approachRunaway) &&
    speed < 4.2 &&
    !backOff.isOn()
  ) {
    input.actions.throttle = 0
    if (approachRunaway) {
      input.actions.brake = Math.min(0.72, 0.38 + forwardSpeed * 0.22)
    }
  } else if (targetSpeed > speed) input.actions.throttle = 1
  if (!backOff.isOn() && !tightDegenerateHug) {
    delete input.actions._dir_hug_degen
    if (!wedgeEscape.active) wedgeEscape.active = false
  }
  if (
    !backOff.isOn() &&
    wedgeEscape.active &&
    speed > 2.8 &&
    !frontBlock.hit &&
    (!tightSiteNow || carZ < -38.5)
  ) {
    wedgeEscape.active = false
    delete input.actions._dir_hug_degen
  }
}

function transform(input, dt, params, state, api) {
  if (params && params.id) return {}
  if (input.actions && input.actions._obstacle_escape) return {}
  if (input.actions && input.actions._uml_maneuver) return {}
  if (input.target && input.target.distance && input.target.distance < 10) return {}
  var forward = api.getForwardVector(input.rotation)
  var backward = api.vec.scale(forward, -1)
  var speed = api.vec.getForwardSpeed(input.velocity, forward)
  var frontPosition = api.vec.offsetAlong(input.position, forward, 5)
  var backdPosition = api.vec.offsetAlong(input.position, backward, 5)
  if (speed > 0) {
    var castResult = api.raycastSpread(frontPosition, forward, speed * speed / 300, 2, 8, { visualize: false })
    if (castResult.hit === true && speed > 0.1) {
      var breakSpeed = 1 / (castResult.distance + 1) * ((speed * speed) / 200)
      if (breakSpeed > 1) breakSpeed = 1
      input.actions.brake = breakSpeed
      input.actions.throttle = 0
    }
  } else {
    var castResult = api.raycastSpread(backdPosition, backward, speed * speed / 300, 2, 8, { visualize: false })
    if (castResult.hit === true && speed < -0.1) {
      var breakSpeed = 1 / (castResult.distance + 1) * ((speed * speed) / 200)
      if (breakSpeed > 1) breakSpeed = 1
      input.actions.brake = 0
      input.actions.throttle = breakSpeed
    }
  }
  return {}
}

function blockedPulseState(state) {
  if (!state._umlBlockedPulse) {
    state._umlBlockedPulse = { nextAt: 0 }
  }
  return state._umlBlockedPulse
}

function v3x(v) {
  return Array.isArray(v) ? v[0] : v.x
}
function v3z(v) {
  return Array.isArray(v) ? v[2] : v.z
}

function isParkourCylinderL(entityId) {
  if (!entityId) return false
  return String(entityId).indexOf('parkour_cylinder_l') >= 0
}

/** Parkour cylinder wedge at z≈−36: close contact, not approach at z≈−31. */
function tightCylinderUmlSite(input, blockHit, speed) {
  if (!blockHit.hit) return false
  var carZ = v3z(input.position)
  if (carZ >= -34.8 || carZ <= -38.2) return false
  if (blockHit.distance >= 2.8) return false
  if (!isParkourCylinderL(blockHit.entityId)) return false
  if (speed > 1.35) return false
  return true
}

var maneuver = {
  isOn: function () { return this.expires > Date.now(); },
  trigger: function (vector, timeMs) {
    this.expires = Date.now() + timeMs
    this.vector = vector
  },
  reset: function () {
    this.expires = 0
    this.vector = undefined
  },
  expires: 0,
  vector: undefined,
}

function obstacleUrgency(closest) {
  var CRITICAL = 6
  var CALM = 12
  if (closest >= CALM) return 0
  if (closest <= CRITICAL) return 1
  return 1 - (closest - CRITICAL) / (CALM - CRITICAL)
}

function maneuverLockMs(deviation, urgency) {
  var base = 400 - Math.min(340, deviation * 300)
  return Math.max(120, Math.floor(base + urgency * 70))
}

function sanitizeObstacleHit(input, hit) {
  if (!hit || !hit.hit) return hit
  if (hit.entityId && hit.entityId === input.entityId) {
    return { hit: false, distance: 0, entityId: '' }
  }
  if (hit.distance < 0.35) {
    return { hit: false, distance: 0, entityId: '' }
  }
  return hit
}

function raycastObstacle(api, input, origin, direction, distance, options) {
  var hit = api.raycastSpread(origin, direction, distance, 2, 10, options || { visualize: false })
  return sanitizeObstacleHit(input, hit)
}

function transform(input, dt, params, state, api) {
  if (
    api.getAction(input, 'steer_left') ||
    api.getAction(input, 'steer_right') ||
    api.getAction(input, 'throttle') ||
    api.getAction(input, 'brake')
  ) {
    return
  }

  if (!input.target || !input.target.pose || !input.target.pose.position) return {}

  // Upstream (e.g. wanderer) owns input.target.pose; use it for path scoring only.
  var goalPos = input.target.pose.position
  var truePos = goalPos
  if (typeof params.id === 'string' && params.id.length > 0) {
    var liveFollow = api.getWorldPosition(params.id)
    if (liveFollow) truePos = liveFollow
  }
  // Never snap input.target to a follow entity here — that pins the red debug line (and direction) on "car".
  var toTrue = api.vec.subtract(truePos, input.position)
  var distTrue = api.vec.length(toTrue)
  input.target.distance = distTrue

  if (distTrue < 5) {
    maneuver.reset()
    delete input.actions._uml_maneuver
    return
  }

  var up = api.getUpVector(input.rotation)
  var forward = api.getForwardVector(input.rotation)
  forward = api.vec.normalize(api.vec.projectOntoPlane(forward, up))
  var flatToTrue = api.vec.normalize(api.vec.projectOntoPlane(toTrue, up))
  var speedNow = api.vec.length(input.velocity)
  var frontOffset = distTrue < 28 ? 2.2 : 4.5
  var frontPosition = api.vec.offsetAlong(input.position, forward, frontOffset)
  var goalRayDist = Math.min(distTrue, 24)
  var goalHitEarly = raycastObstacle(api, input, input.position, flatToTrue, goalRayDist, {
    visualize: false,
  })
  var earlyGoalBlocked = goalHitEarly.hit && goalHitEarly.distance < distTrue - 0.8
  var pathGoal = truePos
  if (goalHitEarly.hit && goalHitEarly.distance < distTrue - 0.5) {
    // Past the blocker (thick obstacles need more than hit.distance + small slack).
    var pastBlock = goalHitEarly.distance + 10
    if (pastBlock > distTrue - 2) pastBlock = distTrue - 2
    pathGoal = api.vec.add(input.position, api.vec.scale(flatToTrue, pastBlock))
  }

  if (maneuver.isOn() && maneuver.vector) {
    if (api.vec.length(api.vec.subtract(maneuver.vector, input.position)) < 4) {
      maneuver.reset()
    } else if (api.vec.length(api.vec.subtract(truePos, maneuver.vector)) > distTrue + 10) {
      maneuver.reset()
    }
  }

  if (maneuver.isOn() && maneuver.vector) {
    var checkDist = Math.min(16, Math.max(8, distTrue))
    var frontClear = raycastObstacle(api, input, frontPosition, forward, checkDist, { visualize: false })
    var bumperHit = raycastObstacle(api, input, input.position, forward, 4, { visualize: false })
    var closeObDist = 999
    if (bumperHit.hit) closeObDist = bumperHit.distance
    if (goalHitEarly.hit && goalHitEarly.distance < closeObDist) closeObDist = goalHitEarly.distance
    if (frontClear.hit && frontClear.distance < closeObDist) closeObDist = frontClear.distance
    if (
      tightCylinderUmlSite(input, bumperHit, speedNow) &&
      Math.abs(v3x(maneuver.vector) - v3x(input.position)) > 4
    ) {
      maneuver.reset()
    } else if (!frontClear.hit && api.vec.angleBetween(forward, flatToTrue) < 0.45) {
      maneuver.reset()
    } else if (
      pathClear(api, input, input.position, maneuver.vector, up) &&
      (earlyGoalBlocked || pathClear(api, input, maneuver.vector, pathGoal, up))
    ) {
      var toLocked = api.vec.projectOntoPlane(api.vec.subtract(maneuver.vector, input.position), up)
      var stallSpeed = api.vec.length(input.velocity)
      if (
        earlyGoalBlocked &&
        closeObDist < 2.05 &&
        stallSpeed < 2.5 &&
        api.vec.dot(toLocked, forward) < 1.15
      ) {
        maneuver.reset()
      } else {
        input.target.pose.position = maneuver.vector
        input.actions._uml_maneuver = 1
        if (earlyGoalBlocked && closeObDist < 2.05) {
          input.actions._uml_goal_block = 1
          input.actions._uml_closest = closeObDist
        } else {
          delete input.actions._uml_goal_block
          delete input.actions._uml_closest
        }
        api.watch('uml.aimX', v3x(maneuver.vector))
        api.watch('uml.aimZ', v3z(maneuver.vector))
        return
      }
    }
    maneuver.reset()
  }

  var lookahead = distTrue - 6
  if (lookahead < 10) lookahead = 10
  if (lookahead > 22) lookahead = 22

  var frontHit = raycastObstacle(api, input, frontPosition, forward, lookahead, {
    visualize: true,
    hitColor: 'orange',
    missColor: 'cyan',
  })
  var goalHit = goalHitEarly
  var goalBlocked = goalHit.hit && goalHit.distance < distTrue - 0.8
  var blockHit = frontHit
  if (goalBlocked && (!frontHit.hit || goalHit.distance < frontHit.distance + 3)) {
    blockHit = goalHit
    api.watch('uml.goalBlock', 1)
  } else {
    api.watch('uml.goalBlock', 0)
    goalBlocked = false
  }
  api.watch('uml.lookahead', lookahead)
  api.watch('uml.frontHit', blockHit.hit ? 1 : 0)
  api.watch('uml.frontDist', blockHit.hit ? blockHit.distance : -1)
  api.watch('uml.frontEnt', blockHit.hit ? blockHit.entityId : '')
  if (!blockHit.hit) {
    api.watch('uml.maneuver', 0)
    delete input.actions._uml_maneuver
    delete input.actions._uml_blocked
    delete input.actions._uml_goal_block
    delete input.actions._uml_closest
    return {}
  }

  var bumperClose = raycastObstacle(api, input, input.position, forward, 4, { visualize: false })
  var pickCloseDist = blockHit.distance
  if (bumperClose.hit && bumperClose.distance < pickCloseDist) pickCloseDist = bumperClose.distance
  if (goalBlocked && pickCloseDist < 2.05) {
    input.actions._uml_goal_block = 1
    input.actions._uml_closest = pickCloseDist
  } else {
    delete input.actions._uml_goal_block
    delete input.actions._uml_closest
  }

  // Goal-blocked rays are straight at the obstacle; lateral fan needs the bumper forward axis.
  var scanFromGoalRay = blockHit === goalHit && !frontHit.hit
  var scanOrigin = scanFromGoalRay ? input.position : frontPosition
  var scanForward = scanFromGoalRay ? flatToTrue : forward
  var scanDist = scanFromGoalRay ? Math.min(goalHit.distance + 2, 18) : lookahead
  var blockForTight = blockHit
  if (bumperClose.hit && isParkourCylinderL(bumperClose.entityId)) {
    if (!blockForTight.hit || bumperClose.distance < blockForTight.distance) {
      blockForTight = bumperClose
    }
  }
  var tightUmlSite = tightCylinderUmlSite(input, blockForTight, speedNow)
  var picked = undefined
  if (tightUmlSite) {
    picked = tightCylinderFlankFallback(
      api,
      input,
      input.position,
      scanForward,
      up,
      truePos,
      distTrue,
      pathGoal,
    )
  } else if (goalBlocked) {
    picked = flankFallback(
      api,
      input,
      input.position,
      scanForward,
      up,
      truePos,
      distTrue,
      blockHit.distance,
      pathGoal,
      goalBlocked,
    )
  }
  if (!picked && !tightUmlSite) {
    picked = findCorrectionVector(
      api,
      input,
      input.position,
      scanOrigin,
      scanForward,
      scanDist,
      input.rotation,
      truePos,
      distTrue,
      flatToTrue,
      blockHit.distance,
      pathGoal,
      goalBlocked,
    )
  }
  if (!picked && tightUmlSite) {
    picked = tightCylinderForcedFlank(api, input, input.position, scanForward, up, distTrue)
  }
  if (!picked && goalBlocked && !tightUmlSite) {
    picked = flankFallback(
      api,
      input,
      input.position,
      scanForward,
      up,
      truePos,
      distTrue,
      blockHit.distance,
      pathGoal,
      goalBlocked,
    )
  }
  if (!picked) {
    api.watch('uml.maneuver', 0)
    delete input.actions._uml_maneuver
    var bp = blockedPulseState(state)
    var now = Date.now()
    if (blockHit.distance < 2.05 && now < bp.nextAt) {
      delete input.actions._uml_blocked
    } else {
      input.actions._uml_blocked = 1
      if (blockHit.distance < 2.05) bp.nextAt = now + 880
    }
    if (tightUmlSite) return
    return {}
  }

  input.target.pose.position = picked.candidate
  api.watch('uml.maneuver', 1)
  api.watch('uml.aimX', v3x(picked.candidate))
  api.watch('uml.aimZ', v3z(picked.candidate))
  input.actions._uml_maneuver = 1
  delete input.actions._uml_blocked
  maneuver.trigger(picked.candidate, maneuverLockMs(picked.deviation, obstacleUrgency(blockHit.distance)))
  return {}
}

function pathClear(api, input, from, to, up) {
  return pathClearSlack(api, input, from, to, up, 1.2)
}

function pathClearSlack(api, input, from, to, up, slack) {
  var delta = api.vec.subtract(to, from)
  var len = api.vec.length(delta)
  if (len < 0.5) return true
  var dir = api.vec.normalize(api.vec.projectOntoPlane(delta, up))
  var hit = raycastObstacle(api, input, from, dir, len, { visualize: false })
  return !hit.hit || hit.distance > len - slack
}

function tightCylinderFlankFallback(api, input, carPos, forward, up, truePos, distTrue, pathGoal) {
  var lateral = api.vec.normalize(api.vec.cross(up, forward))
  var offsets = [3.2, -3.2, 4, -4, 5, -5]
  var i
  for (i = 0; i < offsets.length; i++) {
    var candidate = api.vec.add(carPos, api.vec.scale(lateral, offsets[i]))
    if (!pathClearSlack(api, input, carPos, candidate, up, 0.55)) continue
    if (!pathClearSlack(api, input, candidate, pathGoal, up, 0.85)) continue
    var toTrue = api.vec.length(api.vec.subtract(truePos, candidate))
    if (toTrue > distTrue + 14) continue
    return { candidate: candidate, deviation: 0.65, candidateDist: toTrue }
  }
  return undefined
}

function tightCylinderForcedFlank(api, input, carPos, forward, up, distTrue) {
  var lateral = api.vec.normalize(api.vec.cross(up, forward))
  var carX = v3x(carPos)
  var prefer = carX >= 0 ? 1 : -1
  var offsets = [3.4 * prefer, -3.4 * prefer, 4.2 * prefer, -4.2 * prefer]
  var i
  for (i = 0; i < offsets.length; i++) {
    var candidate = api.vec.add(carPos, api.vec.scale(lateral, offsets[i]))
    if (!pathClearSlack(api, input, carPos, candidate, up, 0.42)) continue
    if (Math.abs(v3x(candidate) - carX) < 2.2) continue
    return { candidate: candidate, deviation: 0.72, candidateDist: distTrue }
  }
  return undefined
}

function flankFallback(api, input, carPos, forward, up, truePos, distTrue, closestObstacle, pathGoal, goalBlocked) {
  var urgency = obstacleUrgency(closestObstacle)
  var lateral = api.vec.normalize(api.vec.cross(up, forward))
  var offset = goalBlocked ? 14 + urgency * 10 : 8 + urgency * 10
  if (goalBlocked && closestObstacle < 2.8) offset += 4
  var options = [
    api.vec.add(carPos, api.vec.scale(lateral, offset)),
    api.vec.add(carPos, api.vec.scale(lateral, -offset)),
  ]
  if (goalBlocked) {
    var ahead = closestObstacle < 3 ? 10 + urgency * 6 : 7 + urgency * 5
    var midLat = 5.5 + urgency * 2
    var midAhead = 5 + urgency * 3
    options = [
      api.vec.add(carPos, api.vec.add(api.vec.scale(lateral, midLat), api.vec.scale(forward, midAhead))),
      api.vec.add(carPos, api.vec.add(api.vec.scale(lateral, -midLat), api.vec.scale(forward, midAhead))),
      api.vec.add(carPos, api.vec.add(api.vec.scale(lateral, offset), api.vec.scale(forward, ahead))),
      api.vec.add(carPos, api.vec.add(api.vec.scale(lateral, -offset), api.vec.scale(forward, ahead))),
      api.vec.add(carPos, api.vec.scale(lateral, offset)),
      api.vec.add(carPos, api.vec.scale(lateral, -offset)),
    ]
  }
  var i
  for (i = 0; i < options.length; i++) {
    var candidate = options[i]
    if (!pathClear(api, input, carPos, candidate, up)) continue
    if (!goalBlocked && !pathClear(api, input, candidate, pathGoal, up)) continue
    if (goalBlocked && Math.abs(v3x(candidate) - v3x(carPos)) < 4) continue
    if (goalBlocked && closestObstacle < 2.05) {
      var toCandClose = api.vec.projectOntoPlane(api.vec.subtract(candidate, carPos), up)
      if (api.vec.dot(toCandClose, forward) < 1.15) continue
    } else if (goalBlocked && closestObstacle < 4) {
      var toCand = api.vec.projectOntoPlane(api.vec.subtract(candidate, carPos), up)
      var ahead = api.vec.dot(toCand, forward)
      if (ahead < 2.5 && Math.abs(v3x(toCand)) > 6) continue
    }
    var toTrue = api.vec.length(api.vec.subtract(truePos, candidate))
    if (toTrue > distTrue + 14) continue
    return { candidate: candidate, deviation: 0.8, candidateDist: toTrue }
  }
  return undefined
}

function findCorrectionVector(
  api,
  input,
  carPos,
  origin,
  forward,
  distance,
  entityRotation,
  truePos,
  distTrue,
  flatToTrue,
  closestObstacle,
  pathGoal,
  goalBlocked,
) {
  var up = api.getUpVector(entityRotation)
  var urgency = obstacleUrgency(closestObstacle)
  var spread = 0.95 + urgency * 1.35
  var steps = 44
  var results = []
  var i

  var ALIGN_WEIGHT = 3.2 - urgency * 1.1
  var DEVIATION_SQ_WEIGHT = 3.4 + (1 - urgency) * 1.8
  var CLEAR_WEIGHT = 0.22 + urgency * 0.62

  for (i = 0; i <= steps; i++) {
    var angle = -spread + (2 * spread * i) / steps
    var result = evaluateVector(api, input, origin, forward, up, distance, angle)
    var flatDir = api.vec.normalize(api.vec.projectOntoPlane(result.rotation, up))
    var deviation = api.vec.angleBetween(flatDir, flatToTrue)
    var alignment = 1 - deviation / Math.PI
    var clearance = result.raycast.hit ? result.raycast.distance / distance : 1.25

    if (clearance < 0.32 && urgency < 0.95) continue

    var pushDist = distance * (0.42 + 0.28 * (1 - urgency)) + urgency * 6
    if (deviation > 0.35) pushDist += deviation * 4
    var candidate = api.vec.add(origin, api.vec.scale(api.vec.normalize(result.rotation), pushDist))
    if (!pathClear(api, input, carPos, candidate, up)) continue
    if (goalBlocked && Math.abs(v3x(candidate) - v3x(carPos)) < 4.5) continue
    if (!goalBlocked && !pathClear(api, input, candidate, pathGoal, up)) continue
    var candidateDist = api.vec.length(api.vec.subtract(truePos, candidate))

    var score =
      alignment * ALIGN_WEIGHT +
      clearance * CLEAR_WEIGHT -
      deviation * deviation * DEVIATION_SQ_WEIGHT

    if (!result.raycast.hit) score += 0.2
    if (deviation > 0.25 && urgency > 0.4) score += deviation * 0.35
    if (candidateDist > distTrue + 4) score -= 1.2
    if (candidateDist < distTrue) score += 0.25

    results.push({ score: score, candidate: candidate, deviation: deviation, candidateDist: candidateDist })
  }

  if (results.length === 0) return undefined

  results.sort(function (a, b) {
    if (Math.abs(a.score - b.score) > 0.03) return b.score - a.score
    if (Math.abs(a.deviation - b.deviation) > 0.02) return a.deviation - b.deviation
    return a.candidateDist - b.candidateDist
  })

  return results[0]
}

function evaluateVector(api, input, origin, forward, up, distance, angle) {
  var direction = api.vec.rotateAroundAxis(forward, up, angle)
  return {
    rotation: direction,
    raycast: raycastObstacle(api, input, origin, direction, distance, { visualize: false }),
  }
}

function transform(input, dt, params, state, api) {
  if (!input.target || !input.target.pose || !input.target.pose.position) return {}
  api.visualizeLine(input.position, input.target.pose.position, '#ffcc00')
  return {}
}

function hugBackoffState(state) {
  if (!state._dirHugBackoff) {
    state._dirHugBackoff = { nextPulseAt: 0 }
  }
  return state._dirHugBackoff
}

function wedgeEscapeState(state) {
  if (!state._dirWedgeEscape) {
    state._dirWedgeEscape = { active: false }
  }
  return state._dirWedgeEscape
}

function backOffState(state) {
  if (!state._dirBackOff) {
    state._dirBackOff = { until: 0, steerForward: 0, phase: 'forward' }
  }
  var b = state._dirBackOff
  if (!b.isOn) {
    b.isOn = function () { return this.until > Date.now() }
    b.trigger = function (steerForward, holdMs) {
      this.until = Date.now() + (holdMs || 480)
      this.steerForward = steerForward
      this.phase = 'forward'
    }
  }
  return b
}

function clampSteer(v) {
  if (v > 1) return 1
  if (v < -1) return -1
  return v
}

function resolveTrueFollowPosition(input, params, api) {
  if (typeof params.id === 'string' && params.id.length > 0) {
    var live = api.getWorldPosition(params.id)
    if (live) return live
  }
  if (input.target && input.target.pose && input.target.pose.position) {
    return input.target.pose.position
  }
  return null
}

function transform(input, dt, params, state, api) {
  if (
    api.getAction(input, 'steer_left') ||
    api.getAction(input, 'steer_right') ||
    api.getAction(input, 'throttle') ||
    api.getAction(input, 'brake')
  ) {
    return
  }

  delete input.actions._obstacle_escape

  var truePos = resolveTrueFollowPosition(input, params, api)
  if (!truePos) return {}

  if (!input.target || !input.target.pose || !input.target.pose.position) {
    input.target = { pose: { position: truePos }, id: params.id }
  }

  var backOff = backOffState(state)
  var wedgeEscape = wedgeEscapeState(state)
  var carZWedge = input.position[2] != null ? input.position[2] : input.position.z
  var posXWedge = input.position[0] != null ? input.position[0] : input.position.x
  var tightSiteNow = carZWedge < -34.8 && carZWedge > -38.2
  if (wedgeEscape.active && Math.abs(posXWedge) > 2.5 && carZWedge < -38.5) {
    wedgeEscape.active = false
    delete input.actions._dir_hug_degen
    backOff.until = 0
  }
  var toTrue = api.vec.subtract(truePos, input.position)
  var distTrue = api.vec.length(toTrue)

  var up = api.getUpVector(input.rotation)
  var forward = api.getForwardVector(input.rotation)
  forward = api.vec.normalize(api.vec.projectOntoPlane(forward, up))
  var flatToTrue = api.vec.normalize(api.vec.projectOntoPlane(toTrue, up))

  var aimPos = input.target.pose.position
  var toAim = api.vec.subtract(aimPos, input.position)
  toAim = api.vec.normalize(api.vec.projectOntoPlane(toAim, up))

  var signedSteer = api.vec.signedAngleAroundAxis(forward, toAim, up)
  var forwardSpeed = api.vec.getForwardSpeed(input.velocity, forward)
  var aimAwayFromTrue = api.vec.angleBetween(toAim, flatToTrue)

  if (forwardSpeed < -0.2) signedSteer = -signedSteer
  var steerGain = 1 + Math.min(2.2, aimAwayFromTrue * 1.8)
  if (input.actions._uml_maneuver) steerGain += 1.8
  if (Math.abs(signedSteer) >= 0.001) {
    input.actions.steering_angle = clampSteer(signedSteer * steerGain)
  }

  if (backOff.isOn()) {
    api.watch('dir.backoff', 1)
    input.actions._obstacle_escape = 1
    var esc = clampSteer(backOff.steerForward * 2.5)
    var probeOrigin = api.vec.offsetAlong(input.position, forward, 2.5)
    var probe = api.raycastSpread(probeOrigin, forward, 2.2, 1.4, 8, { visualize: false })
    var wedgeHold = wedgeEscape.active
    if (wedgeHold) {
      var aimXEsc = aimPos[0] != null ? aimPos[0] : aimPos.x
      var posXEsc = input.position[0] != null ? input.position[0] : input.position.x
      var peelSign = aimXEsc >= posXEsc ? 0.92 : -0.92
      if (tightSiteNow) {
        var wedgeBump = api.raycastSpread(input.position, forward, 2.5, 1.4, 8, { visualize: false })
        if (wedgeBump.hit && wedgeBump.entityId) {
          var obPosEsc = api.getWorldPosition(wedgeBump.entityId)
          if (obPosEsc) {
            var obXEsc = obPosEsc[0] != null ? obPosEsc[0] : obPosEsc.x
            peelSign = posXEsc >= obXEsc ? 0.92 : -0.92
          }
        }
      }
      esc = clampSteer(peelSign * 2.5)
      input.actions._dir_hug_degen = 1
    }
    if (!probe.hit && !wedgeHold) {
      backOff.until = 0
      wedgeEscape.active = false
      api.watch('dir.backoff', 0)
      return
    }
    if (forwardSpeed < -0.95 && !wedgeHold) {
      backOff.until = 0
      wedgeEscape.active = false
      api.watch('dir.backoff', 0)
      return
    }
    if (forwardSpeed > 0.35) {
      backOff.phase = 'forward'
      input.actions.throttle = 0
      input.actions.brake = 0.62
      input.actions.steering_angle = esc
    } else if (forwardSpeed < -0.25) {
      backOff.phase = 'reverse'
      input.actions.throttle = 0
      input.actions.brake = wedgeHold ? 0.52 : 0.38
      input.actions.steering_angle = -esc
    } else if (backOff.phase === 'forward') {
      input.actions.throttle = 0
      input.actions.brake = 0.58
      input.actions.steering_angle = esc
      if (forwardSpeed < 0.06) backOff.phase = 'reverse'
    } else {
      input.actions.throttle = 0
      input.actions.brake = 0.36
      input.actions.steering_angle = -esc
    }
    return
  }

  var front = api.vec.offsetAlong(input.position, forward, 3)
  var frontBlock = api.raycastSpread(front, forward, 2.5, 1.6, 10, { visualize: false })
  var carZFront = input.position[2] != null ? input.position[2] : input.position.z
  var tightFrontSite = carZFront < -34.8 && carZFront > -38.2
  if (tightFrontSite) {
    var bumperBlock = api.raycastSpread(input.position, forward, 2.5, 1.4, 8, { visualize: false })
    if (
      bumperBlock.hit &&
      bumperBlock.entityId &&
      String(bumperBlock.entityId).indexOf('cylinder') >= 0 &&
      (!frontBlock.hit || bumperBlock.distance < frontBlock.distance)
    ) {
      frontBlock = bumperBlock
    }
  }
  var speed = api.vec.length(input.velocity)

  if (frontBlock.hit === true) {
    api.watch('dir.frontDist', frontBlock.distance)
    var steerNow = input.actions.steering_angle
    if (steerNow == null || Math.abs(steerNow) < 0.02) steerNow = signedSteer
    var close = frontBlock.distance < 1.55
    var holdMs = close ? 520 : 420
    var needBackOff =
      frontBlock.distance < 2.35 &&
      (close || speed < 3.5 || frontBlock.distance < 2.05)
    var carZNeed = input.position[2] != null ? input.position[2] : input.position.z
    var tightNeedSite = carZNeed < -34.8 && carZNeed > -38.2
    var needDegenerateCylinder =
      tightNeedSite &&
      frontBlock.entityId &&
      String(frontBlock.entityId).indexOf('cylinder') >= 0 &&
      frontBlock.distance < (speed < 1.25 ? 2.05 : 0.35) &&
      speed < 1.25
    // Umlenker owns lateral detours while a flank maneuver is active (except tight-cylinder wedge peel).
    if (input.actions._uml_maneuver && !input.actions._uml_blocked && !needDegenerateCylinder) {
      needBackOff = false
    }
    if (input.actions._uml_blocked) {
      needBackOff = true
    }
    if (needBackOff) {
      api.watch('dir.backoff', 1)
      var triggerSteer = clampSteer(steerNow)
      if (needDegenerateCylinder) {
        var aimXNeed = aimPos[0] != null ? aimPos[0] : aimPos.x
        var posXNeed = input.position[0] != null ? input.position[0] : input.position.x
        triggerSteer = aimXNeed >= posXNeed ? 0.85 : -0.85
        input.actions._dir_hug_degen = 1
        wedgeEscape.active = true
        holdMs = 920
      }
      backOff.trigger(triggerSteer, holdMs)
      return
    }
    api.watch('dir.backoff', 0)
    if (!input.actions._uml_maneuver) {
      input.actions.throttle = 0
    }
  } else {
    api.watch('dir.backoff', 0)
  }

  var hug = hugBackoffState(state)
  var umlClosest = input.actions._uml_closest
  var carZ = input.position[2] != null ? input.position[2] : input.position.z
  var tightCylinderSite = carZ < -34.8 && carZ > -38.2
  var dirDegenerateBumper =
    frontBlock.hit === true &&
    (frontBlock.distance < 0.35 || (tightCylinderSite && frontBlock.distance < 2.05))
  var frontHitCylinder =
    frontBlock.hit === true &&
    frontBlock.entityId &&
    String(frontBlock.entityId).indexOf('cylinder') >= 0
  var tightDegenerateHug =
    tightCylinderSite && frontHitCylinder && dirDegenerateBumper
  var hugGoalBlocked =
    input.actions._uml_goal_block &&
    umlClosest != null &&
    umlClosest < 2.85 &&
    (frontBlock.hit !== true || tightDegenerateHug)
  var tightBlockedHug =
    tightDegenerateHug && input.actions._uml_blocked && !input.actions._uml_maneuver
  if (
    !backOff.isOn() &&
    (input.actions._uml_maneuver || tightBlockedHug) &&
    (!input.actions._uml_blocked || tightBlockedHug) &&
    Date.now() >= hug.nextPulseAt &&
    ((tightDegenerateHug && speed < 1.25) || (hugGoalBlocked && speed < 2.4))
  ) {
    var hugHold = umlClosest < 1.85 ? 460 : 380
    if (tightDegenerateHug) hugHold = 620
    hug.nextPulseAt = Date.now() + (tightDegenerateHug ? 520 : 860)
    api.watch('dir.backoff', 1)
    var hugSteer = clampSteer(signedSteer)
    if (tightDegenerateHug) {
      var aimX = aimPos[0] != null ? aimPos[0] : aimPos.x
      var posX = input.position[0] != null ? input.position[0] : input.position.x
      hugSteer = aimX >= posX ? 0.85 : -0.85
    }
    if (tightDegenerateHug) {
      input.actions._dir_hug_degen = 1
      wedgeEscape.active = true
    }
    backOff.trigger(hugSteer, hugHold)
    return
  }

  var targetSpeed = distTrue < 30 ? 9 : 42
  if (aimAwayFromTrue > 0.45) targetSpeed = Math.min(targetSpeed, 18 + 12 * (1 - aimAwayFromTrue))
  if (frontBlock.hit && frontBlock.distance < 4 && !input.actions._uml_maneuver) {
    targetSpeed = Math.min(targetSpeed, 6)
  }
  if (input.actions._uml_maneuver && frontBlock.hit && frontBlock.distance < 3.5) {
    targetSpeed = Math.min(targetSpeed, 9)
  }
  var posXThrottle = input.position[0] != null ? input.position[0] : input.position.x
  var cylinderPeelPending =
    frontHitCylinder &&
    frontBlock.hit &&
    frontBlock.distance < 4.2 &&
    Math.abs(posXThrottle) <= 2.5 &&
    carZ > -44.5
  var approachRunaway =
    Math.abs(posXThrottle) > 2.5 &&
    carZ > -38.5 &&
    forwardSpeed > 0.85 &&
    api.vec.dot(forward, flatToTrue) < 0.35
  if (
    (tightDegenerateHug ||
      (wedgeEscape.active && tightSiteNow) ||
      cylinderPeelPending ||
      approachRunaway) &&
    speed < 4.2 &&
    !backOff.isOn()
  ) {
    input.actions.throttle = 0
    if (approachRunaway) {
      input.actions.brake = Math.min(0.72, 0.38 + forwardSpeed * 0.22)
    }
  } else if (targetSpeed > speed) input.actions.throttle = 1
  if (!backOff.isOn() && !tightDegenerateHug) {
    delete input.actions._dir_hug_degen
    if (!wedgeEscape.active) wedgeEscape.active = false
  }
  if (
    !backOff.isOn() &&
    wedgeEscape.active &&
    speed > 2.8 &&
    !frontBlock.hit &&
    (!tightSiteNow || carZ < -38.5)
  ) {
    wedgeEscape.active = false
    delete input.actions._dir_hug_degen
  }
}

function transform(input, dt, params, state, api) {
  if (params && params.id) return {}
  if (input.actions && input.actions._obstacle_escape) return {}
  if (input.actions && input.actions._uml_maneuver) return {}
  if (input.target && input.target.distance && input.target.distance < 10) return {}
  var forward = api.getForwardVector(input.rotation)
  var backward = api.vec.scale(forward, -1)
  var speed = api.vec.getForwardSpeed(input.velocity, forward)
  var frontPosition = api.vec.offsetAlong(input.position, forward, 5)
  var backdPosition = api.vec.offsetAlong(input.position, backward, 5)
  if (speed > 0) {
    var castResult = api.raycastSpread(frontPosition, forward, speed * speed / 300, 2, 8, { visualize: false })
    if (castResult.hit === true && speed > 0.1) {
      var breakSpeed = 1 / (castResult.distance + 1) * ((speed * speed) / 200)
      if (breakSpeed > 1) breakSpeed = 1
      input.actions.brake = breakSpeed
      input.actions.throttle = 0
    }
  } else {
    var castResult = api.raycastSpread(backdPosition, backward, speed * speed / 300, 2, 8, { visualize: false })
    if (castResult.hit === true && speed < -0.1) {
      var breakSpeed = 1 / (castResult.distance + 1) * ((speed * speed) / 200)
      if (breakSpeed > 1) breakSpeed = 1
      input.actions.brake = 0
      input.actions.throttle = breakSpeed
    }
  }
  return {}
}

// AV stack · SENSE / state estimation ("localization" layer).
// Publishes the ego state on the shared blackboard `input.av.ego` for all later stages.
// debug draw (params.debugDraw, default true): cyan = velocity vector.
// Owns the simulated clock (state.t) so no downstream stage needs a wall clock.
function transform(input, dt, params, state, api) {
  // fresh blackboard every frame (the input object is reused by the runtime)
  var av = (input.av = {})
  if (state.t === undefined) {
    state.t = 0
    state.speedF = 0
    state.prevSpeed = 0
    state.accelF = 0
  }
  state.t += dt
  var up = api.getUpVector(input.rotation)
  var fwd = api.vec.normalize(api.vec.projectOntoPlane(api.getForwardVector(input.rotation), up))
  var left = api.vec.normalize(api.vec.cross(up, fwd))
  var speed = api.vec.getForwardSpeed(input.velocity, fwd)
  var yawRate = api.vec.dot(input.angularVelocity, up)
  var a = dt > 1e-6 ? (speed - state.prevSpeed) / dt : 0
  state.prevSpeed = speed
  state.accelF += (a - state.accelF) * Math.min(1, dt * 8)
  state.speedF += (speed - state.speedF) * Math.min(1, dt * 20)
  av.ego = {
    t: state.t,
    dt: dt,
    pos: input.position,
    fwd: fwd,
    left: left,
    up: up,
    speed: speed,
    speedF: state.speedF,
    accel: state.accelF,
    yawRate: yawRate,
    kappa: Math.abs(speed) > 1.5 ? yawRate / speed : 0,
  }
  api.watch('av.speed', Math.round(speed * 10) / 10)
  if (params.debugDraw !== false) {
    // cyan: velocity vector
    api.visualizeLine(input.position, api.vec.add(input.position, api.vec.scale(input.velocity, 0.6)), '#00e5ff')
  }
  return {}
}

// AV stack · SENSE / perception.
// 360° range-scan ring (lidar-like, mounted at the vehicle centre, rays start on the hull)
// + obstacle memory ("local costmap") so the planners also know what is behind / beside.
// Publishes: av.scan {angles, ranges, range}, av.points [[x,z],...] (world), av.rearClear.
// debug draw (params.debugDraw, debugRayStride, debugMaxPoints): red = lidar hit rays, magenta ticks = costmap points.
// params: drivableArea [xmin, xmax, zmin, zmax] (virtual walls at the edge), edgeStep, rayCount, fovDeg, sensorRange, memoryTtl, memoryCell, vehicleWidth, vehicleLength
function transform(input, dt, params, state, api) {
  var av = input.av
  if (!av || !av.ego) return {}
  var e = av.ego
  var n = params.rayCount || 72
  var fov = ((params.fovDeg || 360) * Math.PI) / 180
  var range = params.sensorRange || 24
  var ttl = params.memoryTtl != null ? params.memoryTtl : 15
  var cell = params.memoryCell || 0.5
  var hl = (params.vehicleLength || 4) / 2 + 0.15
  var hw = (params.vehicleWidth || 2) / 2 + 0.15
  if (!state.mem) state.mem = {}
  var mem = state.mem
  var pos = input.position
  var full = fov >= 2 * Math.PI - 1e-3
  var angles = []
  var ranges = []
  var rearClear = params.rearRange || 8
  var draw = params.debugDraw !== false
  var rayStride = params.debugRayStride || 2
  for (var i = 0; i < n; i++) {
    var th = full ? -Math.PI + (2 * Math.PI * i) / n : n === 1 ? 0 : -fov / 2 + (fov * i) / (n - 1)
    var c = Math.cos(th)
    var s = Math.sin(th)
    var dir = [
      e.fwd[0] * c + e.left[0] * s,
      e.fwd[1] * c + e.left[1] * s,
      e.fwd[2] * c + e.left[2] * s,
    ]
    // start just outside the hull rectangle along this ray
    var tHull = Math.min(Math.abs(c) > 1e-6 ? hl / Math.abs(c) : 1e9, Math.abs(s) > 1e-6 ? hw / Math.abs(s) : 1e9)
    var origin = api.vec.offsetAlong(pos, dir, tHull)
    var r = api.raycast(origin, dir, range, { visualize: false })
    angles.push(th)
    if (r.hit) {
      if (draw && i % rayStride === 0) api.visualizeLine(origin, api.vec.offsetAlong(origin, dir, r.distance), '#ff4d4d')
      ranges.push(r.distance)
      var hx = origin[0] + dir[0] * r.distance
      var hz = origin[2] + dir[2] * r.distance
      mem[Math.round(hx / cell) + ',' + Math.round(hz / cell)] = { x: hx, z: hz, t: e.t }
      if (c < -0.9 && r.distance < rearClear) rearClear = r.distance
    } else {
      ranges.push(range)
    }
  }
  var pts = []
  // virtual walls along the edge of the drivable area (map prior): [xmin, xmax, zmin, zmax]
  var area = params.drivableArea
  if (area && area.length === 4) {
    var step = params.edgeStep || 1.2
    var reach = range
    var xs = Math.max(area[0], pos[0] - reach)
    var xe = Math.min(area[1], pos[0] + reach)
    var zs = Math.max(area[2], pos[2] - reach)
    var ze = Math.min(area[3], pos[2] + reach)
    var j
    if (pos[2] - area[2] < reach) for (j = xs; j <= xe; j += step) pts.push([j, area[2]])
    if (area[3] - pos[2] < reach) for (j = xs; j <= xe; j += step) pts.push([j, area[3]])
    if (pos[0] - area[0] < reach) for (j = zs; j <= ze; j += step) pts.push([area[0], j])
    if (area[1] - pos[0] < reach) for (j = zs; j <= ze; j += step) pts.push([area[1], j])
  }
  var keys = Object.keys(mem)
  for (var k = 0; k < keys.length; k++) {
    var m = mem[keys[k]]
    if (e.t - m.t > ttl) delete mem[keys[k]]
    else pts.push([m.x, m.z])
  }
  if (draw) {
    // magenta ticks: remembered obstacle points (costmap), nearest 60
    var near = pts
      .map(function (q) {
        var ddx = q[0] - pos[0]
        var ddz = q[1] - pos[2]
        return [ddx * ddx + ddz * ddz, q]
      })
      .sort(function (a, b) {
        return a[0] - b[0]
      })
      .slice(0, params.debugMaxPoints || 60)
    for (var pi = 0; pi < near.length; pi++) {
      var q2 = near[pi][1]
      api.visualizeLine([q2[0], pos[1] - 0.4, q2[1]], [q2[0], pos[1] + 0.5, q2[1]], '#ff00ff')
    }
  }
  av.scan = { angles: angles, ranges: ranges, range: range }
  av.points = pts
  av.rearClear = rearClear
  return {}
}

// AV stack · SENSE / mission overlay (debug only, no effect on driving).
// Draws the whole mission route: mint polyline + poles at every waypoint; the active target pole is yellow.
// Reads av.mission.waypoints (av-mission stage) or params.waypoints [[x, z], ...].
// params: waypoints, debugDraw
function transform(input, dt, params, state, api) {
  if (params.debugDraw === false) return {}
  var av = input.av
  var wps = (av && av.mission && av.mission.waypoints) || params.waypoints
  if (!wps || !wps.length) return {}
  var y = input.position[1]
  var cur = input.target && input.target.pose && input.target.pose.position
  for (var i = 0; i < wps.length; i++) {
    var w = wps[i]
    var active = cur && Math.abs(cur[0] - w[0]) < 0.05 && Math.abs(cur[2] - w[1]) < 0.05
    api.visualizeLine([w[0], y - 0.5, w[1]], [w[0], y + 5, w[1]], active ? '#ffcc00' : '#00ffcc')
    if (i > 0) api.visualizeLine([wps[i - 1][0], y - 0.4, wps[i - 1][1]], [w[0], y - 0.4, w[1]], '#7dffb0')
  }
  return {}
}

// AV stack · PLAN / route + manoeuvre planner (Hybrid-A* over forward/reverse arc primitives).
// Two jobs, one search:
//  1. ROUTE: every `routeInterval` s plans a collision-free route to the goal over the costmap and publishes
//     `av.carrot` (a point ~lookahead metres along the forward part of the route). The local planner chases
//     the carrot instead of the raw goal, so a goal behind an obstacle no longer produces endless orbits.
//  2. MANOEUVRE: if the route starts by reversing (or the car is stuck) it takes over (`av.override`): drives the
//     multi-point turn segment by segment, re-plans on drift/blockage/stall, and hands back as soon as the route
//     has a long forward run.
// Runs BEFORE the local motion planner. Simulated time only.
// debug draw: magenta = route / manoeuvre path (+ status mast while manoeuvring), orange = current segment end.
// params: maneuverSpeed, routeInterval, routeExpansions, lookahead, primitiveLength, maxExpansions,
//         gearSwitchPenalty, reversePenalty, maxReverseRun, planMargin, tightMargin, guardMargin, stallTime, stuckTime,
//         goalReach, handbackFree, goalTolerance, maxCurvature, vehicleWidth, vehicleLength
function transform(input, dt, params, state, api) {
  var av = input.av
  if (!av || !av.ego) return {}
  var e = av.ego
  var tgt = input.target && input.target.pose && input.target.pose.position
  if (!tgt) return {}
  var gxw = tgt[0]
  var gzw = tgt[2]
  var kmax = params.maxCurvature || 0.115
  var planMargin = params.planMargin != null ? params.planMargin : 0.4
  var tightMargin = params.tightMargin != null ? params.tightMargin : 0.1
  var guardMargin = params.guardMargin != null ? params.guardMargin : 0.15
  var ell = params.primitiveLength || 1.8
  var maxExpFull = params.maxExpansions || 4000
  var routeExp = params.routeExpansions || 1500
  var routeInterval = params.routeInterval != null ? params.routeInterval : 0.8
  var lookahead = params.lookahead != null ? params.lookahead : 14
  var gearPen = params.gearSwitchPenalty != null ? params.gearSwitchPenalty : 4
  var revPen = params.reversePenalty != null ? params.reversePenalty : 4
  var handback = params.handbackFree != null ? params.handbackFree : 10
  var vMan = params.maneuverSpeed != null ? params.maneuverSpeed : 3
  var stuckTime = params.stuckTime != null ? params.stuckTime : 1.5
  var holdTol = params.goalTolerance != null ? params.goalTolerance : 3.5
  // route ends inside the waypoint acceptance zone (not only at its centre)
  var reach = params.goalReach != null ? params.goalReach : 3.5
  var maxRevRun = params.maxReverseRun != null ? params.maxReverseRun : 8
  var termHeadW = params.exitHeadingWeight != null ? params.exitHeadingWeight : 0
  var ks = [-kmax, -kmax / 2, 0, kmax / 2, kmax]
  var pos = input.position
  // next waypoint after the current target: the route should arrive heading towards it
  var nextWp = null
  var wps = av.mission ? av.mission.waypoints : params.waypoints
  if (wps && wps.length) {
    for (var wi = 0; wi < wps.length - 1; wi++) {
      if (Math.abs(wps[wi][0] - gxw) < 0.05 && Math.abs(wps[wi][1] - gzw) < 0.05) {
        nextWp = wps[wi + 1]
        break
      }
    }
  }
  var goalDist = Math.sqrt((gxw - pos[0]) * (gxw - pos[0]) + (gzw - pos[2]) * (gzw - pos[2]))

  // spatial hash over costmap points + swept-footprint test (hl/hw are the active margins)
  function makeHit(pts, hlA, hwA) {
    var grid = {}
    for (var i = 0; i < pts.length; i++) {
      var key = Math.floor(pts[i][0] / 2) + ',' + Math.floor(pts[i][1] / 2)
      ;(grid[key] || (grid[key] = [])).push(pts[i])
    }
    var R = Math.sqrt(hlA * hlA + hwA * hwA)
    return function (x, z, fx, fz) {
      var x0 = Math.floor((x - R) / 2)
      var x1 = Math.floor((x + R) / 2)
      var z0 = Math.floor((z - R) / 2)
      var z1 = Math.floor((z + R) / 2)
      for (var cx = x0; cx <= x1; cx++) {
        for (var cz = z0; cz <= z1; cz++) {
          var list = grid[cx + ',' + cz]
          if (!list) continue
          for (var q = 0; q < list.length; q++) {
            var dx = list[q][0] - x
            var dz = list[q][1] - z
            var lx = dx * fx + dz * fz
            var ly = dx * fz - dz * fx
            if (lx > -hlA && lx < hlA && ly > -hwA && ly < hwA) return true
          }
        }
      }
      return false
    }
  }

  function search(sx, sz, sfx, sfz, gx, gz, pts, maxExp) {
    var hlS = (params.vehicleLength || 4) / 2 + planMargin
    var hwS = (params.vehicleWidth || 2) / 2 + planMargin
    var hit = makeHit(pts, hlS, hwS)
    // start already inside the comfort margin (drift, soft contact): re-plan with the tight margin so
    // the planner can still drive out of the margin band instead of finding every primitive blocked
    if (hit(sx, sz, sfx, sfz)) {
      hlS = (params.vehicleLength || 4) / 2 + tightMargin
      hwS = (params.vehicleWidth || 2) / 2 + tightMargin
      hit = makeHit(pts, hlS, hwS)
    }
    function dist(x, z) {
      var dx = gx - x
      var dz = gz - z
      return Math.sqrt(dx * dx + dz * dz)
    }
    // binary min-heap on f
    var heap = []
    function push(nd) {
      heap.push(nd)
      var c = heap.length - 1
      while (c > 0) {
        var p = (c - 1) >> 1
        if (heap[p].f <= heap[c].f) break
        var t = heap[p]
        heap[p] = heap[c]
        heap[c] = t
        c = p
      }
    }
    function pop() {
      var top = heap[0]
      var last = heap.pop()
      if (heap.length > 0) {
        heap[0] = last
        var c = 0
        for (;;) {
          var l = 2 * c + 1
          var r = l + 1
          var m = c
          if (l < heap.length && heap[l].f < heap[m].f) m = l
          if (r < heap.length && heap[r].f < heap[m].f) m = r
          if (m === c) break
          var t = heap[m]
          heap[m] = heap[c]
          heap[c] = t
          c = m
        }
      }
      return top
    }
    function skey(x, z, fx, fz, g) {
      var ih = Math.round((Math.atan2(fz, fx) / (2 * Math.PI)) * 36)
      if (ih < 0) ih += 36
      return Math.round(x / 0.6) + ',' + Math.round(z / 0.6) + ',' + (ih % 36) + ',' + g
    }
    var HW = 1.4
    var start = { x: sx, z: sz, fx: sfx, fz: sfz, g: 0, gear: 0, k: 0, parent: null, f: dist(sx, sz) * HW, d: 0 }
    push(start)
    var best = {}
    best[skey(sx, sz, sfx, sfz, 0)] = 0
    var bestNode = start
    var bestH = dist(sx, sz)
    var goalNode = null
    var expansions = 0
    while (heap.length > 0 && expansions < maxExp) {
      var cur = pop()
      var ck = skey(cur.x, cur.z, cur.fx, cur.fz, cur.gear)
      if (best[ck] !== undefined && cur.g > best[ck] + 1e-6) continue
      expansions++
      var h = dist(cur.x, cur.z)
      if (h < bestH) {
        bestH = h
        bestNode = cur
      }
      if (h < reach) {
        if (cur.terminal || !nextWp) {
          goalNode = cur
          break
        }
        // arrival cost: leave the goal zone heading towards the next waypoint
        var ndx = nextWp[0] - cur.x
        var ndz = nextWp[1] - cur.z
        var nl = Math.sqrt(ndx * ndx + ndz * ndz) || 1
        var cosA = Math.max(-1, Math.min(1, (cur.fx * ndx + cur.fz * ndz) / nl))
        var termG = cur.g + termHeadW * Math.acos(cosA)
        push({ x: cur.x, z: cur.z, fx: cur.fx, fz: cur.fz, g: termG, gear: cur.gear, k: cur.k, parent: cur, terminal: true, f: termG })
        continue
      }
      for (var gi = 0; gi < 2; gi++) {
        var gear = gi === 0 ? 1 : -1
        for (var ki = 0; ki < ks.length; ki++) {
          var k = ks[ki]
          var lx = cur.fz
          var lz = -cur.fx
          var revRun = gear < 0 ? (cur.gear < 0 ? cur.revRun || 0 : 0) + ell : 0
          if (revRun > maxRevRun) continue
          var ok = true
          var nx = cur.x
          var nz = cur.z
          var nfx = cur.fx
          var nfz = cur.fz
          for (var sIdx = 1; sIdx <= 4; sIdx++) {
            var d = (gear * ell * sIdx) / 4
            var th = k * d
            var ddx
            var ddy
            if (Math.abs(k) < 1e-6) {
              ddx = d
              ddy = 0
            } else {
              ddx = Math.sin(th) / k
              ddy = (1 - Math.cos(th)) / k
            }
            nx = cur.x + cur.fx * ddx + lx * ddy
            nz = cur.z + cur.fz * ddx + lz * ddy
            var ct = Math.cos(th)
            var st = Math.sin(th)
            nfx = cur.fx * ct + lx * st
            nfz = cur.fz * ct + lz * st
            if (hit(nx, nz, nfx, nfz)) {
              ok = false
              break
            }
          }
          if (!ok) continue
          var step = ell * (gear < 0 ? revPen : 1) + (Math.abs(k) / kmax) * 0.4 * ell
          if (cur.gear !== 0 && cur.gear !== gear) step += gearPen
          if (cur.gear !== 0 && cur.k !== k) step += 0.3
          var g2 = cur.g + step
          var nk = skey(nx, nz, nfx, nfz, gear)
          if (best[nk] !== undefined && best[nk] <= g2) continue
          best[nk] = g2
          push({ x: nx, z: nz, fx: nfx, fz: nfz, g: g2, gear: gear, k: k, revRun: revRun, parent: cur, f: g2 + dist(nx, nz) * HW })
        }
      }
    }
    var end = goalNode || bestNode
    if (end.terminal) end = end.parent
    var segs = []
    for (var nd = end; nd && nd.parent; nd = nd.parent) {
      var last = segs[0]
      if (last && last.g === nd.gear && last.k === nd.k) {
        last.len += ell
      } else {
        segs.unshift({ g: nd.gear, k: nd.k, len: ell, end: null })
      }
    }
    // expected pose at the end of every segment (walk the chain again, front to back)
    var chain = []
    for (var cn = end; cn; cn = cn.parent) chain.unshift(cn)
    var si = -1
    var prevG = null
    var prevK = null
    for (var ci = 1; ci < chain.length; ci++) {
      var nn = chain[ci]
      if (si < 0 || nn.gear !== prevG || nn.k !== prevK) {
        si++
        prevG = nn.gear
        prevK = nn.k
      }
      segs[si].end = { x: nn.x, z: nn.z, fx: nn.fx, fz: nn.fz }
    }
    var pathPts = []
    for (var pj = 0; pj < chain.length; pj++) pathPts.push([chain[pj].x, chain[pj].z])
    var nodes = []
    for (var nj = 0; nj < chain.length; nj++) nodes.push({ x: chain[nj].x, z: chain[nj].z, g: chain[nj].gear })
    return { segs: segs, reached: !!goalNode, expansions: expansions, hRemaining: bestH, path: pathPts, nodes: nodes }
  }

  function begin(res) {
    state.segs = res.segs
    state.idx = 0
    state.segStart = null
    state.prevGear = 0
    state.path = res.path
  }
  function deviates(seg) {
    if (!seg || !seg.end) return false
    var ex = pos[0] - seg.end.x
    var ez = pos[2] - seg.end.z
    var dot = e.fwd[0] * seg.end.fx + e.fwd[2] * seg.end.fz
    return Math.sqrt(ex * ex + ez * ez) > 0.9 || dot < 0.97
  }
  function plan(maxE) {
    return search(pos[0], pos[2], e.fwd[0], e.fwd[2], gxw, gzw, av.points || [], maxE)
  }
  // route summary: first gear, length of the leading forward run, carrot point
  function summarize(res) {
    var nodes = res.nodes
    var firstGear = nodes.length > 1 ? nodes[1].g : 1
    var run = 0
    var carrot = null
    if (firstGear === 1) {
      var want = Math.min(lookahead, 6 + 1.0 * Math.max(0, e.speedF))
      var acc = 0
      for (var i = 1; i < nodes.length && nodes[i].g === 1; i++) {
        var dx = nodes[i].x - nodes[i - 1].x
        var dz = nodes[i].z - nodes[i - 1].z
        acc += Math.sqrt(dx * dx + dz * dz)
        carrot = [nodes[i].x, nodes[i].z]
        if (acc >= want) break
      }
      run = acc
      for (var j = i; j < nodes.length && nodes[j].g === 1; j++) {
        var ddx = nodes[j].x - nodes[j - 1].x
        var ddz = nodes[j].z - nodes[j - 1].z
        run += Math.sqrt(ddx * ddx + ddz * ddz)
      }
    }
    // speed limit from the bends ahead on the route: corner speed sqrt(aLat / kappa), reachable by braking
    var aLat = params.maxLatAccel || 7
    var aBrk = params.comfortDecel || 5
    var vLimit = Infinity
    var dAhead = 0
    for (var si = 0; si < res.segs.length && dAhead < 40 && res.segs[si].g > 0; si++) {
      var kk = Math.abs(res.segs[si].k)
      if (kk > 0.04) {
        var vi = Math.sqrt(aLat / kk)
        var allowed = Math.sqrt(vi * vi + 2 * aBrk * dAhead)
        if (allowed < vLimit) vLimit = allowed
      }
      dAhead += res.segs[si].len
    }
    return { firstGear: firstGear, run: run, carrot: carrot, reached: res.reached, nodes: nodes, path: res.path, vLimit: vLimit }
  }

  // stuck watchdog (own, independent of the local planner)
  if (state.stuckT === undefined) state.stuckT = 0
  if (!state.active && Math.abs(e.speed) < 0.25 && goalDist > holdTol) state.stuckT += dt
  else state.stuckT = 0

  if (!state.active) {
    if (state.route === undefined || e.t - state.routeT >= routeInterval) {
      state.route = summarize(plan(routeExp))
      state.routeT = e.t
      state.revFresh = true
      state.routes = (state.routes || 0) + 1
    }
    var rt = state.route
    // hysteresis: a reverse-first route must be confirmed by two consecutive plans before the car manoeuvres
    state.revVotes = rt.firstGear === -1 ? (state.revFresh ? (state.revVotes || 0) + 1 : state.revVotes || 1) : 0
    state.revFresh = false
    var wantManeuver = (rt.firstGear === -1 && (state.revVotes >= 2 || Math.abs(e.speed) < 0.3) && Math.abs(e.speed) < 1.5) || state.stuckT > stuckTime
    if (wantManeuver && goalDist > holdTol) {
      var res = plan(maxExpFull)
      if (res.segs.length > 0) {
        state.active = true
        state.replans = (state.replans || 0) + 1
        state.stuckT = 0
        begin(res)
      }
    }
    if (!state.active) {
      if (rt.carrot) av.carrot = rt.carrot
      av.route = { firstGear: rt.firstGear, run: rt.run, reached: rt.reached, vLimit: rt.vLimit }
      if (params.debugDraw !== false) {
        var y0 = pos[1]
        for (var di = 2; di < rt.path.length; di += 2) {
          api.visualizeLine([rt.path[di - 2][0], y0, rt.path[di - 2][1]], [rt.path[di][0], y0, rt.path[di][1]], '#ff44ff')
        }
      }
      api.watch('av.route', 'gear ' + rt.firstGear + ' run ' + rt.run.toFixed(1) + (rt.reached ? ' goal' : ' partial'))
      return {}
    }
  }

  // --- execute manoeuvre ---
  var cur = state.segs[state.idx]
  if (state.segStart === null) {
    // a gear change must come to rest first so the odometer does not count coasting
    if (cur.g === state.prevGear || Math.abs(e.speed) < 0.4) state.segStart = [pos[0], pos[2]]
  }
  var travelled = 0
  if (state.segStart) {
    var dx = pos[0] - state.segStart[0]
    var dz = pos[2] - state.segStart[1]
    travelled = Math.sqrt(dx * dx + dz * dz)
  }
  // --- execution guard: re-plan when the real pose makes the rest of the segment collide, or when stalled ---
  if (state.segStart !== null) {
    var guardL = (params.vehicleLength || 4) / 2 + guardMargin
    var guardW = (params.vehicleWidth || 2) / 2 + guardMargin
    var gHit = makeHit(av.points || [], guardL, guardW)
    var lx0 = e.left[0]
    var lz0 = e.left[2]
    var look = Math.min(2.0, Math.max(0, cur.len - travelled))
    var blockedAhead = false
    for (var gd = 0.5; gd <= look + 1e-6 && !blockedAhead; gd += 0.5) {
      var gdd = cur.g * gd
      var gth = cur.k * gdd
      var gx2 = Math.abs(cur.k) < 1e-6 ? gdd : Math.sin(gth) / cur.k
      var gy2 = Math.abs(cur.k) < 1e-6 ? 0 : (1 - Math.cos(gth)) / cur.k
      var px = pos[0] + e.fwd[0] * gx2 + lx0 * gy2
      var pz = pos[2] + e.fwd[2] * gx2 + lz0 * gy2
      var pfx = e.fwd[0] * Math.cos(gth) + lx0 * Math.sin(gth)
      var pfz = e.fwd[2] * Math.cos(gth) + lz0 * Math.sin(gth)
      if (gHit(px, pz, pfx, pfz)) blockedAhead = true
    }
    state.stallT = Math.abs(e.speed) < 0.15 ? (state.stallT || 0) + dt : 0
    var stallTime = params.stallTime != null ? params.stallTime : 1.2
    if ((blockedAhead || state.stallT > stallTime) && e.t - (state.lastReplanT || -9) > 0.6) {
      var fix = plan(maxExpFull)
      state.lastReplanT = e.t
      state.stallT = 0
      state.replans++
      if (fix.segs.length > 0) {
        begin(fix)
        state.prevGear = cur.g
        cur = state.segs[0]
        travelled = 0
      }
    }
  }
  // hand back once the rest of the plan starts with a long forward run
  var fwdRun = 0
  if (state.idx > 0 || state.segs.length === 1) {
    for (var si = state.idx; si < state.segs.length && state.segs[si].g > 0; si++) fwdRun += state.segs[si].len
    fwdRun -= travelled
  }
  var aheadFree = false
  if (fwdRun >= handback && cur.g > 0) {
    // the car must really have room ahead on its own heading, not just a plan that will get there
    var aHit = makeHit(av.points || [], (params.vehicleLength || 4) / 2 + planMargin, (params.vehicleWidth || 2) / 2 + planMargin)
    aheadFree = true
    for (var ad = 0; ad <= handback && aheadFree; ad += 1) {
      // along the current segment's arc (what the local planner would also pick), not just straight on
      var ath = cur.k * ad
      var ax = Math.abs(cur.k) < 1e-6 ? ad : Math.sin(ath) / cur.k
      var ay = Math.abs(cur.k) < 1e-6 ? 0 : (1 - Math.cos(ath)) / cur.k
      var apx = pos[0] + e.fwd[0] * ax + e.left[0] * ay
      var apz = pos[2] + e.fwd[2] * ax + e.left[2] * ay
      if (aHit(apx, apz, e.fwd[0] * Math.cos(ath) + e.left[0] * Math.sin(ath), e.fwd[2] * Math.cos(ath) + e.left[2] * Math.sin(ath))) aheadFree = false
    }
  }
  if (aheadFree) {
    state.active = false
    state.route = undefined
    return {}
  }
  var finished = state.segStart !== null && travelled >= cur.len - 0.25
  if (finished) {
    state.prevGear = cur.g
    if (state.idx + 1 >= state.segs.length || deviates(cur)) {
      var again = plan(maxExpFull)
      state.replans++
      if (again.segs.length === 0 || state.idx + 1 >= state.segs.length) {
        state.active = false
        state.route = undefined
        if (again.segs.length === 0) return {}
      }
      if (again.segs.length > 0 && state.active) {
        begin(again)
        state.prevGear = cur.g
      }
    } else {
      state.idx++
      state.segStart = null
    }
    if (!state.active) return {}
    cur = state.segs[state.idx]
    travelled = 0
  }
  if (params.debugDraw !== false && state.path) {
    var py = pos[1]
    for (var pi = 2; pi < state.path.length; pi += 2) {
      api.visualizeLine([state.path[pi - 2][0], py, state.path[pi - 2][1]], [state.path[pi][0], py, state.path[pi][1]], '#ff44ff')
    }
    if (cur.end) api.visualizeLine(pos, [cur.end.x, py, cur.end.z], '#ff8800')
    api.visualizeLine([pos[0], py + 1.2, pos[2]], [pos[0], py + 4, pos[2]], '#ff44ff')
  }
  var remain = state.segStart ? Math.max(0, cur.len - travelled) : cur.len
  var vMax = Math.min(vMan, 0.9 + Math.sqrt(2 * 3 * remain))
  var wrongWay = state.segStart === null || cur.g * e.speed < -0.35
  av.override = { kappa: cur.k, vDesired: wrongWay ? 0 : cur.g * vMax }
  av.mode = 'maneuver'
  api.watch('av.maneuver', 'seg ' + state.idx + '/' + state.segs.length + ' g' + cur.g + ' k' + cur.k.toFixed(3) + ' replans ' + state.replans)
  return {}
}

// AV stack · PLAN / local motion planner (sampling-based, receding horizon).
// Candidate paths = constant-curvature turn (limited turn angle) followed by a straight, so a path can
// swing around an obstacle and then run alongside it. Each path is swept with the vehicle footprint
// (margin grows with speed) against the costmap. Cost = progress to goal, heading, required stopping
// length, clearance, smoothness. Publishes av.plan {kappa, free, freeSoft, clearance, blocked, horizon}.
// debug draw: yellow = line to goal / route carrot, dark blue = candidate fan, green = chosen path, orange = where it would hit.
// params: vehicleWidth, vehicleLength, safetyMargin, marginSpeedGain, softMargin, maxCurvature, arcCount,
//         horizonMin, horizonGain, horizonMax, comfortDecel, wProgress, wHeading, wRequired, wFree, wSoft,
//         wSmooth, wTurn, minFree, rearIgnore, debugDraw
function transform(input, dt, params, state, api) {
  var av = input.av
  if (!av || !av.ego) return {}
  var e = av.ego
  var tgt = input.target && input.target.pose && input.target.pose.position
  if (!tgt) {
    av.plan = { kappa: 0, free: 0, freeSoft: 0, clearance: 0, blocked: false, horizon: 0, noGoal: true }
    return {}
  }
  var pos = input.position
  var tdx = tgt[0] - pos[0]
  var tdz = tgt[2] - pos[2]
  av.goal = { x: tgt[0], z: tgt[2], dist: Math.sqrt(tdx * tdx + tdz * tdz) }
  // manoeuvre planner owns the controls (multi-point turn): pass its command through
  if (av.override) {
    av.plan = { kappa: av.override.kappa, vDesired: av.override.vDesired, free: 99, freeSoft: 99, clearance: 9, blocked: false, horizon: 0, override: true }
    return {}
  }
  // chase the route's carrot (global plan) when there is one, else the raw goal
  var aim = av.carrot ? [av.carrot[0], 0, av.carrot[1]] : tgt
  var gdx = aim[0] - pos[0]
  var gdz = aim[2] - pos[2]
  var gx = gdx * e.fwd[0] + gdz * e.fwd[2]
  var gy = gdx * e.left[0] + gdz * e.left[2]
  var goalDist = Math.sqrt(gx * gx + gy * gy)

  var v = Math.max(0, e.speedF)
  var margin = (params.safetyMargin != null ? params.safetyMargin : 0.5) + (params.marginSpeedGain != null ? params.marginSpeedGain : 0.05) * v
  var soft = params.softMargin != null ? params.softMargin : 1.1
  var halfW = (params.vehicleWidth || 2) / 2 + margin
  var halfL = (params.vehicleLength || 4) / 2 + margin
  var kmax = params.maxCurvature || 0.115
  var count = params.arcCount || 31
  var hMin = params.horizonMin != null ? params.horizonMin : 10
  var hMax = params.horizonMax != null ? params.horizonMax : 26
  var H = Math.min(hMax, hMin + (params.horizonGain != null ? params.horizonGain : 1.2) * v)
  var aBrake = params.comfortDecel || 5
  var Lreq = Math.min(H, (v * v) / (2 * aBrake) + 5)
  var wProg = params.wProgress != null ? params.wProgress : 1.0
  var wHead = params.wHeading != null ? params.wHeading : 2.0
  var wReq = params.wRequired != null ? params.wRequired : 60
  var wFree = params.wFree != null ? params.wFree : 10
  var wSoft = params.wSoft != null ? params.wSoft : 8
  var wSmooth = params.wSmooth != null ? params.wSmooth : 2.5
  var wTurn = params.wTurn != null ? params.wTurn : 1.5
  var minFree = params.minFree != null ? params.minFree : 4.5
  var ds = 0.75
  var turnAngles = [0.5, 1.15]

  // costmap into ego frame
  var pts = av.points || []
  var ox = []
  var oy = []
  for (var i = 0; i < pts.length; i++) {
    var dx = pts[i][0] - pos[0]
    var dz = pts[i][1] - pos[2]
    var px = dx * e.fwd[0] + dz * e.fwd[2]
    var py = dx * e.left[0] + dz * e.left[2]
    if (px > -halfL - soft - 3 && px < H + halfL + soft + 3 && py > -H - 4 && py < H + 4) {
      ox.push(px)
      oy.push(py)
    }
  }

  // pose along a path: turn at `kappa` for `turnLen`, then straight
  function poseAt(kappa, turnLen, s, out) {
    var sa = s < turnLen ? s : turnLen
    var th = kappa * sa
    var x
    var y
    if (Math.abs(kappa) < 1e-6) {
      x = sa
      y = 0
    } else {
      x = Math.sin(th) / kappa
      y = (1 - Math.cos(th)) / kappa
    }
    if (s > turnLen) {
      x += Math.cos(th) * (s - turnLen)
      y += Math.sin(th) * (s - turnLen)
    }
    out.x = x
    out.y = y
    out.th = th
  }
  var P = { x: 0, y: 0, th: 0 }

  // forward paths only sweep the front of the footprint: an obstacle already behind/at the tail (touching
  // start pose) must not veto driving away from it
  var rearIgnore = params.rearIgnore != null ? params.rearIgnore : 1.4
  function freeLength(kappa, turnLen, hw, hl) {
    var hlRear = Math.max(0.3, hl - rearIgnore)
    for (var s = 0; s <= H; s += ds) {
      poseAt(kappa, turnLen, s, P)
      var ct = Math.cos(P.th)
      var st = Math.sin(P.th)
      for (var q = 0; q < ox.length; q++) {
        var rx = ox[q] - P.x
        var ry = oy[q] - P.y
        var lx = ct * rx + st * ry
        var ly = -st * rx + ct * ry
        if (lx > -hlRear && lx < hl && ly > -hw && ly < hw) return Math.max(0, s - ds)
      }
    }
    return H
  }

  var prev = state.prevKappa || 0
  var prevTurn = state.prevTurn || 0
  var best = null
  var bestCost = Infinity
  var bestHard = 0
  var bestSoft = 0
  var bestTurnLen = 0
  var cand = []
  for (var a = 0; a < count; a++) {
    var kappa = count === 1 ? 0 : -kmax + (2 * kmax * a) / (count - 1)
    for (var ti = 0; ti < turnAngles.length; ti++) {
      if (Math.abs(kappa) < 1e-6 && ti > 0) continue
      var turnLen = Math.abs(kappa) < 1e-6 ? H : Math.min(H, turnAngles[ti] / Math.abs(kappa))
      var fHard = freeLength(kappa, turnLen, halfW, halfL)
      var fSoft = freeLength(kappa, turnLen, halfW + soft - margin, halfL + soft - margin)
      var L = fHard
      poseAt(kappa, turnLen, L, P)
      var gdEnd = Math.sqrt((gx - P.x) * (gx - P.x) + (gy - P.y) * (gy - P.y))
      var progress = goalDist - gdEnd
      var herr = Math.atan2(gy - P.y, gx - P.x) - P.th
      while (herr > Math.PI) herr -= 2 * Math.PI
      while (herr < -Math.PI) herr += 2 * Math.PI
      var cost =
        -wProg * progress +
        wHead * Math.abs(herr) +
        wReq * Math.max(0, 1 - L / Lreq) +
        wFree * (1 - L / H) +
        wSoft * (1 - Math.min(fSoft, H) / H) +
        wSmooth * (Math.abs(kappa - prev) / kmax) +
        wTurn * Math.abs(kappa * turnLen)
      if (cost < bestCost) {
        bestCost = cost
        best = kappa
        bestHard = fHard
        bestSoft = fSoft
        bestTurnLen = turnLen
      }
      if (params.debugDraw !== false && a % 8 === 0 && ti === 0) cand.push([kappa, turnLen, fHard])
    }
  }
  state.prevKappa = best

  // lateral clearance of the chosen path over the distance that matters (beyond the hard margin)
  var clearance = 0
  var margins = [0.5, 1.0, 1.5, 2.5]
  var needLen = Math.min(bestHard, Lreq)
  for (var mi = 0; mi < margins.length; mi++) {
    var fm = freeLength(best, bestTurnLen, halfW + margins[mi], halfL + margins[mi])
    if (fm >= needLen - 1e-6) clearance = margins[mi]
    else break
  }

  av.plan = {
    kappa: best,
    free: bestHard,
    freeSoft: bestSoft,
    clearance: clearance,
    margin: margin,
    blocked: bestHard < minFree,
    horizon: H,
    required: Lreq,
    cost: bestCost,
  }
  api.watch('av.plan.kappa', Math.round(best * 1000) / 1000)
  api.watch('av.plan.free', Math.round(bestHard * 10) / 10 + ' clr ' + clearance)

  if (params.debugDraw !== false) {
    var y0 = pos[1]
    var W = { x: 0, y: 0, th: 0 }
    function world(x, y) {
      return [pos[0] + e.fwd[0] * x + e.left[0] * y, y0, pos[2] + e.fwd[2] * x + e.left[2] * y]
    }
    function drawPath(kk, tl, len, color, step) {
      var prevW = null
      for (var s = 0; s <= len + 1e-6; s += step) {
        poseAt(kk, tl, s, W)
        var wp = world(W.x, W.y)
        if (prevW) api.visualizeLine(prevW, wp, color)
        prevW = wp
      }
    }
    api.visualizeLine(pos, [aim[0], y0, aim[2]], '#ffcc00')
    for (var ci = 0; ci < cand.length; ci++) drawPath(cand[ci][0], cand[ci][1], cand[ci][2], '#3a5a9a', Math.max(4, cand[ci][2] / 3))
    drawPath(best, bestTurnLen, bestHard, '#22dd66', 2.5)
    if (bestHard < H) drawPath(best, bestTurnLen, Math.min(H, bestHard + 3), '#ff8800', 3)
  }
  return {}
}

// AV stack · PLAN / speed planner.
// v_des = min(cruise, stopping-distance limit, clearance limit, route bends ahead, lateral-acceleration limit, goal approach).
// Clearance limit: lots of room beside obstacles → full speed; squeezing past → slow.
// Goal approach only slows for the FINAL waypoint (av.mission, else params.waypoints; otherwise every goal is final).
// Publishes av.plan.vDesired / av.plan.vLimit.
// params: cruiseSpeed, comfortDecel, maxLatAccel, stopMargin, crawlSpeed, goalTolerance, clearSpeedBase,
//         clearSpeedGain, waypoints
function transform(input, dt, params, state, api) {
  var av = input.av
  if (!av || !av.plan) return {}
  var plan = av.plan
  if (plan.override) return {}
  var cruise = params.cruiseSpeed != null ? params.cruiseSpeed : 10
  var aBrake = params.comfortDecel || 5
  var aLat = params.maxLatAccel || 7
  var stopMargin = params.stopMargin != null ? params.stopMargin : 1.2
  var crawl = params.crawlSpeed != null ? params.crawlSpeed : 2
  var base = params.clearSpeedBase != null ? params.clearSpeedBase : 5
  var gain = params.clearSpeedGain != null ? params.clearSpeedGain : 3.5
  var limit = 'cruise'
  var v = cruise
  var vFree = Math.sqrt(2 * aBrake * Math.max(0, plan.free - stopMargin))
  if (vFree < v) {
    v = vFree
    limit = 'free'
  }
  // lateral gap to the nearest obstacle surface along the chosen path (safety margin + measured extra room)
  var vClear = base + gain * Math.max(0, (plan.margin || 0.5) + (plan.clearance || 0) - 0.3)
  if (vClear < v) {
    v = vClear
    limit = 'clearance'
  }
  // bends ahead on the global route (corner speed, reachable by braking)
  if (av.route && av.route.vLimit < v) {
    v = Math.max(av.route.vLimit, crawl)
    limit = 'route'
  }
  var k = Math.abs(plan.kappa)
  if (k > 1e-4) {
    var vCurve = Math.sqrt(aLat / k)
    if (vCurve < v) {
      v = vCurve
      limit = 'curve'
    }
  }
  if (av.goal) {
    var tol = params.goalTolerance != null ? params.goalTolerance : 3.5
    var wps = params.waypoints
    var isFinal = true
    if (av.mission) {
      isFinal = av.mission.isFinal
    } else if (wps && wps.length) {
      var last = wps[wps.length - 1]
      isFinal = Math.abs(av.goal.x - last[0]) < 0.05 && Math.abs(av.goal.z - last[1]) < 0.05
    }
    if (isFinal) {
      var vGoal = Math.sqrt(2 * aBrake * Math.max(0, av.goal.dist - tol))
      if (vGoal < v) {
        v = Math.max(vGoal, crawl)
        limit = 'goal'
      }
    }
  }
  if (!plan.blocked && v < crawl) v = crawl
  plan.vDesired = v
  plan.vLimit = limit
  api.watch('av.vLimit', limit + ' ' + v.toFixed(1))
  return {}
}

// AV stack · PLAN / route + manoeuvre planner (Hybrid-A* over forward/reverse arc primitives).
// Two jobs, one search:
//  1. ROUTE: every `routeInterval` s plans a collision-free route to the goal over the costmap and publishes
//     `av.carrot` (a point ~lookahead metres along the forward part of the route). The local planner chases
//     the carrot instead of the raw goal, so a goal behind an obstacle no longer produces endless orbits.
//  2. MANOEUVRE: if the route starts by reversing (or the car is stuck) it takes over (`av.override`): drives the
//     multi-point turn segment by segment, re-plans on drift/blockage/stall, and hands back as soon as the route
//     has a long forward run.
// Runs BEFORE the local motion planner. Simulated time only.
// debug draw: magenta = route / manoeuvre path (+ status mast while manoeuvring), orange = current segment end.
// params: maneuverSpeed, routeInterval, routeExpansions, lookahead, primitiveLength, maxExpansions,
//         gearSwitchPenalty, reversePenalty, maxReverseRun, planMargin, tightMargin, guardMargin, stallTime, stuckTime,
//         goalReach, handbackFree, goalTolerance, maxCurvature, vehicleWidth, vehicleLength
function transform(input, dt, params, state, api) {
  var av = input.av
  if (!av || !av.ego) return {}
  var e = av.ego
  var tgt = input.target && input.target.pose && input.target.pose.position
  if (!tgt) return {}
  var gxw = tgt[0]
  var gzw = tgt[2]
  var kmax = params.maxCurvature || 0.115
  var planMargin = params.planMargin != null ? params.planMargin : 0.4
  var tightMargin = params.tightMargin != null ? params.tightMargin : 0.1
  var guardMargin = params.guardMargin != null ? params.guardMargin : 0.15
  var ell = params.primitiveLength || 1.8
  var maxExpFull = params.maxExpansions || 4000
  var routeExp = params.routeExpansions || 1500
  var routeInterval = params.routeInterval != null ? params.routeInterval : 0.8
  var lookahead = params.lookahead != null ? params.lookahead : 14
  var gearPen = params.gearSwitchPenalty != null ? params.gearSwitchPenalty : 4
  var revPen = params.reversePenalty != null ? params.reversePenalty : 4
  var handback = params.handbackFree != null ? params.handbackFree : 10
  var vMan = params.maneuverSpeed != null ? params.maneuverSpeed : 3
  var stuckTime = params.stuckTime != null ? params.stuckTime : 1.5
  var holdTol = params.goalTolerance != null ? params.goalTolerance : 3.5
  // route ends inside the waypoint acceptance zone (not only at its centre)
  var reach = params.goalReach != null ? params.goalReach : 3.5
  var maxRevRun = params.maxReverseRun != null ? params.maxReverseRun : 8
  var termHeadW = params.exitHeadingWeight != null ? params.exitHeadingWeight : 0
  var ks = [-kmax, -kmax / 2, 0, kmax / 2, kmax]
  var pos = input.position
  // next waypoint after the current target: the route should arrive heading towards it
  var nextWp = null
  var wps = av.mission ? av.mission.waypoints : params.waypoints
  if (wps && wps.length) {
    for (var wi = 0; wi < wps.length - 1; wi++) {
      if (Math.abs(wps[wi][0] - gxw) < 0.05 && Math.abs(wps[wi][1] - gzw) < 0.05) {
        nextWp = wps[wi + 1]
        break
      }
    }
  }
  var goalDist = Math.sqrt((gxw - pos[0]) * (gxw - pos[0]) + (gzw - pos[2]) * (gzw - pos[2]))

  // spatial hash over costmap points + swept-footprint test (hl/hw are the active margins)
  function makeHit(pts, hlA, hwA) {
    var grid = {}
    for (var i = 0; i < pts.length; i++) {
      var key = Math.floor(pts[i][0] / 2) + ',' + Math.floor(pts[i][1] / 2)
      ;(grid[key] || (grid[key] = [])).push(pts[i])
    }
    var R = Math.sqrt(hlA * hlA + hwA * hwA)
    return function (x, z, fx, fz) {
      var x0 = Math.floor((x - R) / 2)
      var x1 = Math.floor((x + R) / 2)
      var z0 = Math.floor((z - R) / 2)
      var z1 = Math.floor((z + R) / 2)
      for (var cx = x0; cx <= x1; cx++) {
        for (var cz = z0; cz <= z1; cz++) {
          var list = grid[cx + ',' + cz]
          if (!list) continue
          for (var q = 0; q < list.length; q++) {
            var dx = list[q][0] - x
            var dz = list[q][1] - z
            var lx = dx * fx + dz * fz
            var ly = dx * fz - dz * fx
            if (lx > -hlA && lx < hlA && ly > -hwA && ly < hwA) return true
          }
        }
      }
      return false
    }
  }

  function search(sx, sz, sfx, sfz, gx, gz, pts, maxExp) {
    var hlS = (params.vehicleLength || 4) / 2 + planMargin
    var hwS = (params.vehicleWidth || 2) / 2 + planMargin
    var hit = makeHit(pts, hlS, hwS)
    // start already inside the comfort margin (drift, soft contact): re-plan with the tight margin so
    // the planner can still drive out of the margin band instead of finding every primitive blocked
    if (hit(sx, sz, sfx, sfz)) {
      hlS = (params.vehicleLength || 4) / 2 + tightMargin
      hwS = (params.vehicleWidth || 2) / 2 + tightMargin
      hit = makeHit(pts, hlS, hwS)
    }
    function dist(x, z) {
      var dx = gx - x
      var dz = gz - z
      return Math.sqrt(dx * dx + dz * dz)
    }
    // binary min-heap on f
    var heap = []
    function push(nd) {
      heap.push(nd)
      var c = heap.length - 1
      while (c > 0) {
        var p = (c - 1) >> 1
        if (heap[p].f <= heap[c].f) break
        var t = heap[p]
        heap[p] = heap[c]
        heap[c] = t
        c = p
      }
    }
    function pop() {
      var top = heap[0]
      var last = heap.pop()
      if (heap.length > 0) {
        heap[0] = last
        var c = 0
        for (;;) {
          var l = 2 * c + 1
          var r = l + 1
          var m = c
          if (l < heap.length && heap[l].f < heap[m].f) m = l
          if (r < heap.length && heap[r].f < heap[m].f) m = r
          if (m === c) break
          var t = heap[m]
          heap[m] = heap[c]
          heap[c] = t
          c = m
        }
      }
      return top
    }
    function skey(x, z, fx, fz, g) {
      var ih = Math.round((Math.atan2(fz, fx) / (2 * Math.PI)) * 36)
      if (ih < 0) ih += 36
      return Math.round(x / 0.6) + ',' + Math.round(z / 0.6) + ',' + (ih % 36) + ',' + g
    }
    var HW = 1.4
    var start = { x: sx, z: sz, fx: sfx, fz: sfz, g: 0, gear: 0, k: 0, parent: null, f: dist(sx, sz) * HW, d: 0 }
    push(start)
    var best = {}
    best[skey(sx, sz, sfx, sfz, 0)] = 0
    var bestNode = start
    var bestH = dist(sx, sz)
    var goalNode = null
    var expansions = 0
    while (heap.length > 0 && expansions < maxExp) {
      var cur = pop()
      var ck = skey(cur.x, cur.z, cur.fx, cur.fz, cur.gear)
      if (best[ck] !== undefined && cur.g > best[ck] + 1e-6) continue
      expansions++
      var h = dist(cur.x, cur.z)
      if (h < bestH) {
        bestH = h
        bestNode = cur
      }
      if (h < reach) {
        if (cur.terminal || !nextWp) {
          goalNode = cur
          break
        }
        // arrival cost: leave the goal zone heading towards the next waypoint
        var ndx = nextWp[0] - cur.x
        var ndz = nextWp[1] - cur.z
        var nl = Math.sqrt(ndx * ndx + ndz * ndz) || 1
        var cosA = Math.max(-1, Math.min(1, (cur.fx * ndx + cur.fz * ndz) / nl))
        var termG = cur.g + termHeadW * Math.acos(cosA)
        push({ x: cur.x, z: cur.z, fx: cur.fx, fz: cur.fz, g: termG, gear: cur.gear, k: cur.k, parent: cur, terminal: true, f: termG })
        continue
      }
      for (var gi = 0; gi < 2; gi++) {
        var gear = gi === 0 ? 1 : -1
        for (var ki = 0; ki < ks.length; ki++) {
          var k = ks[ki]
          var lx = cur.fz
          var lz = -cur.fx
          var revRun = gear < 0 ? (cur.gear < 0 ? cur.revRun || 0 : 0) + ell : 0
          if (revRun > maxRevRun) continue
          var ok = true
          var nx = cur.x
          var nz = cur.z
          var nfx = cur.fx
          var nfz = cur.fz
          for (var sIdx = 1; sIdx <= 4; sIdx++) {
            var d = (gear * ell * sIdx) / 4
            var th = k * d
            var ddx
            var ddy
            if (Math.abs(k) < 1e-6) {
              ddx = d
              ddy = 0
            } else {
              ddx = Math.sin(th) / k
              ddy = (1 - Math.cos(th)) / k
            }
            nx = cur.x + cur.fx * ddx + lx * ddy
            nz = cur.z + cur.fz * ddx + lz * ddy
            var ct = Math.cos(th)
            var st = Math.sin(th)
            nfx = cur.fx * ct + lx * st
            nfz = cur.fz * ct + lz * st
            if (hit(nx, nz, nfx, nfz)) {
              ok = false
              break
            }
          }
          if (!ok) continue
          var step = ell * (gear < 0 ? revPen : 1) + (Math.abs(k) / kmax) * 0.4 * ell
          if (cur.gear !== 0 && cur.gear !== gear) step += gearPen
          if (cur.gear !== 0 && cur.k !== k) step += 0.3
          var g2 = cur.g + step
          var nk = skey(nx, nz, nfx, nfz, gear)
          if (best[nk] !== undefined && best[nk] <= g2) continue
          best[nk] = g2
          push({ x: nx, z: nz, fx: nfx, fz: nfz, g: g2, gear: gear, k: k, revRun: revRun, parent: cur, f: g2 + dist(nx, nz) * HW })
        }
      }
    }
    var end = goalNode || bestNode
    if (end.terminal) end = end.parent
    var segs = []
    for (var nd = end; nd && nd.parent; nd = nd.parent) {
      var last = segs[0]
      if (last && last.g === nd.gear && last.k === nd.k) {
        last.len += ell
      } else {
        segs.unshift({ g: nd.gear, k: nd.k, len: ell, end: null })
      }
    }
    // expected pose at the end of every segment (walk the chain again, front to back)
    var chain = []
    for (var cn = end; cn; cn = cn.parent) chain.unshift(cn)
    var si = -1
    var prevG = null
    var prevK = null
    for (var ci = 1; ci < chain.length; ci++) {
      var nn = chain[ci]
      if (si < 0 || nn.gear !== prevG || nn.k !== prevK) {
        si++
        prevG = nn.gear
        prevK = nn.k
      }
      segs[si].end = { x: nn.x, z: nn.z, fx: nn.fx, fz: nn.fz }
    }
    var pathPts = []
    for (var pj = 0; pj < chain.length; pj++) pathPts.push([chain[pj].x, chain[pj].z])
    var nodes = []
    for (var nj = 0; nj < chain.length; nj++) nodes.push({ x: chain[nj].x, z: chain[nj].z, g: chain[nj].gear })
    return { segs: segs, reached: !!goalNode, expansions: expansions, hRemaining: bestH, path: pathPts, nodes: nodes }
  }

  function begin(res) {
    state.segs = res.segs
    state.idx = 0
    state.segStart = null
    state.prevGear = 0
    state.path = res.path
  }
  function deviates(seg) {
    if (!seg || !seg.end) return false
    var ex = pos[0] - seg.end.x
    var ez = pos[2] - seg.end.z
    var dot = e.fwd[0] * seg.end.fx + e.fwd[2] * seg.end.fz
    return Math.sqrt(ex * ex + ez * ez) > 0.9 || dot < 0.97
  }
  function plan(maxE) {
    return search(pos[0], pos[2], e.fwd[0], e.fwd[2], gxw, gzw, av.points || [], maxE)
  }
  // route summary: first gear, length of the leading forward run, carrot point
  function summarize(res) {
    var nodes = res.nodes
    var firstGear = nodes.length > 1 ? nodes[1].g : 1
    var run = 0
    var carrot = null
    if (firstGear === 1) {
      var want = Math.min(lookahead, 6 + 1.0 * Math.max(0, e.speedF))
      var acc = 0
      for (var i = 1; i < nodes.length && nodes[i].g === 1; i++) {
        var dx = nodes[i].x - nodes[i - 1].x
        var dz = nodes[i].z - nodes[i - 1].z
        acc += Math.sqrt(dx * dx + dz * dz)
        carrot = [nodes[i].x, nodes[i].z]
        if (acc >= want) break
      }
      run = acc
      for (var j = i; j < nodes.length && nodes[j].g === 1; j++) {
        var ddx = nodes[j].x - nodes[j - 1].x
        var ddz = nodes[j].z - nodes[j - 1].z
        run += Math.sqrt(ddx * ddx + ddz * ddz)
      }
    }
    // speed limit from the bends ahead on the route: corner speed sqrt(aLat / kappa), reachable by braking
    var aLat = params.maxLatAccel || 7
    var aBrk = params.comfortDecel || 5
    var vLimit = Infinity
    var dAhead = 0
    for (var si = 0; si < res.segs.length && dAhead < 40 && res.segs[si].g > 0; si++) {
      var kk = Math.abs(res.segs[si].k)
      if (kk > 0.04) {
        var vi = Math.sqrt(aLat / kk)
        var allowed = Math.sqrt(vi * vi + 2 * aBrk * dAhead)
        if (allowed < vLimit) vLimit = allowed
      }
      dAhead += res.segs[si].len
    }
    return { firstGear: firstGear, run: run, carrot: carrot, reached: res.reached, nodes: nodes, path: res.path, vLimit: vLimit }
  }

  // stuck watchdog (own, independent of the local planner)
  if (state.stuckT === undefined) state.stuckT = 0
  if (!state.active && Math.abs(e.speed) < 0.25 && goalDist > holdTol) state.stuckT += dt
  else state.stuckT = 0

  if (!state.active) {
    if (state.route === undefined || e.t - state.routeT >= routeInterval) {
      state.route = summarize(plan(routeExp))
      state.routeT = e.t
      state.revFresh = true
      state.routes = (state.routes || 0) + 1
    }
    var rt = state.route
    // hysteresis: a reverse-first route must be confirmed by two consecutive plans before the car manoeuvres
    state.revVotes = rt.firstGear === -1 ? (state.revFresh ? (state.revVotes || 0) + 1 : state.revVotes || 1) : 0
    state.revFresh = false
    var wantManeuver = (rt.firstGear === -1 && (state.revVotes >= 2 || Math.abs(e.speed) < 0.3) && Math.abs(e.speed) < 1.5) || state.stuckT > stuckTime
    if (wantManeuver && goalDist > holdTol) {
      var res = plan(maxExpFull)
      if (res.segs.length > 0) {
        state.active = true
        state.replans = (state.replans || 0) + 1
        state.stuckT = 0
        begin(res)
      }
    }
    if (!state.active) {
      if (rt.carrot) av.carrot = rt.carrot
      av.route = { firstGear: rt.firstGear, run: rt.run, reached: rt.reached, vLimit: rt.vLimit }
      if (params.debugDraw !== false) {
        var y0 = pos[1]
        for (var di = 2; di < rt.path.length; di += 2) {
          api.visualizeLine([rt.path[di - 2][0], y0, rt.path[di - 2][1]], [rt.path[di][0], y0, rt.path[di][1]], '#ff44ff')
        }
      }
      api.watch('av.route', 'gear ' + rt.firstGear + ' run ' + rt.run.toFixed(1) + (rt.reached ? ' goal' : ' partial'))
      return {}
    }
  }

  // --- execute manoeuvre ---
  var cur = state.segs[state.idx]
  if (state.segStart === null) {
    // a gear change must come to rest first so the odometer does not count coasting
    if (cur.g === state.prevGear || Math.abs(e.speed) < 0.4) state.segStart = [pos[0], pos[2]]
  }
  var travelled = 0
  if (state.segStart) {
    var dx = pos[0] - state.segStart[0]
    var dz = pos[2] - state.segStart[1]
    travelled = Math.sqrt(dx * dx + dz * dz)
  }
  // --- execution guard: re-plan when the real pose makes the rest of the segment collide, or when stalled ---
  if (state.segStart !== null) {
    var guardL = (params.vehicleLength || 4) / 2 + guardMargin
    var guardW = (params.vehicleWidth || 2) / 2 + guardMargin
    var gHit = makeHit(av.points || [], guardL, guardW)
    var lx0 = e.left[0]
    var lz0 = e.left[2]
    var look = Math.min(2.0, Math.max(0, cur.len - travelled))
    var blockedAhead = false
    for (var gd = 0.5; gd <= look + 1e-6 && !blockedAhead; gd += 0.5) {
      var gdd = cur.g * gd
      var gth = cur.k * gdd
      var gx2 = Math.abs(cur.k) < 1e-6 ? gdd : Math.sin(gth) / cur.k
      var gy2 = Math.abs(cur.k) < 1e-6 ? 0 : (1 - Math.cos(gth)) / cur.k
      var px = pos[0] + e.fwd[0] * gx2 + lx0 * gy2
      var pz = pos[2] + e.fwd[2] * gx2 + lz0 * gy2
      var pfx = e.fwd[0] * Math.cos(gth) + lx0 * Math.sin(gth)
      var pfz = e.fwd[2] * Math.cos(gth) + lz0 * Math.sin(gth)
      if (gHit(px, pz, pfx, pfz)) blockedAhead = true
    }
    state.stallT = Math.abs(e.speed) < 0.15 ? (state.stallT || 0) + dt : 0
    var stallTime = params.stallTime != null ? params.stallTime : 1.2
    if ((blockedAhead || state.stallT > stallTime) && e.t - (state.lastReplanT || -9) > 0.6) {
      var fix = plan(maxExpFull)
      state.lastReplanT = e.t
      state.stallT = 0
      state.replans++
      if (fix.segs.length > 0) {
        begin(fix)
        state.prevGear = cur.g
        cur = state.segs[0]
        travelled = 0
      }
    }
  }
  // hand back once the rest of the plan starts with a long forward run
  var fwdRun = 0
  if (state.idx > 0 || state.segs.length === 1) {
    for (var si = state.idx; si < state.segs.length && state.segs[si].g > 0; si++) fwdRun += state.segs[si].len
    fwdRun -= travelled
  }
  var aheadFree = false
  if (fwdRun >= handback && cur.g > 0) {
    // the car must really have room ahead on its own heading, not just a plan that will get there
    var aHit = makeHit(av.points || [], (params.vehicleLength || 4) / 2 + planMargin, (params.vehicleWidth || 2) / 2 + planMargin)
    aheadFree = true
    for (var ad = 0; ad <= handback && aheadFree; ad += 1) {
      // along the current segment's arc (what the local planner would also pick), not just straight on
      var ath = cur.k * ad
      var ax = Math.abs(cur.k) < 1e-6 ? ad : Math.sin(ath) / cur.k
      var ay = Math.abs(cur.k) < 1e-6 ? 0 : (1 - Math.cos(ath)) / cur.k
      var apx = pos[0] + e.fwd[0] * ax + e.left[0] * ay
      var apz = pos[2] + e.fwd[2] * ax + e.left[2] * ay
      if (aHit(apx, apz, e.fwd[0] * Math.cos(ath) + e.left[0] * Math.sin(ath), e.fwd[2] * Math.cos(ath) + e.left[2] * Math.sin(ath))) aheadFree = false
    }
  }
  if (aheadFree) {
    state.active = false
    state.route = undefined
    return {}
  }
  var finished = state.segStart !== null && travelled >= cur.len - 0.25
  if (finished) {
    state.prevGear = cur.g
    if (state.idx + 1 >= state.segs.length || deviates(cur)) {
      var again = plan(maxExpFull)
      state.replans++
      if (again.segs.length === 0 || state.idx + 1 >= state.segs.length) {
        state.active = false
        state.route = undefined
        if (again.segs.length === 0) return {}
      }
      if (again.segs.length > 0 && state.active) {
        begin(again)
        state.prevGear = cur.g
      }
    } else {
      state.idx++
      state.segStart = null
    }
    if (!state.active) return {}
    cur = state.segs[state.idx]
    travelled = 0
  }
  if (params.debugDraw !== false && state.path) {
    var py = pos[1]
    for (var pi = 2; pi < state.path.length; pi += 2) {
      api.visualizeLine([state.path[pi - 2][0], py, state.path[pi - 2][1]], [state.path[pi][0], py, state.path[pi][1]], '#ff44ff')
    }
    if (cur.end) api.visualizeLine(pos, [cur.end.x, py, cur.end.z], '#ff8800')
    api.visualizeLine([pos[0], py + 1.2, pos[2]], [pos[0], py + 4, pos[2]], '#ff44ff')
  }
  var remain = state.segStart ? Math.max(0, cur.len - travelled) : cur.len
  var vMax = Math.min(vMan, 0.9 + Math.sqrt(2 * 3 * remain))
  var wrongWay = state.segStart === null || cur.g * e.speed < -0.35
  av.override = { kappa: cur.k, vDesired: wrongWay ? 0 : cur.g * vMax }
  av.mode = 'maneuver'
  api.watch('av.maneuver', 'seg ' + state.idx + '/' + state.segs.length + ' g' + cur.g + ' k' + cur.k.toFixed(3) + ' replans ' + state.replans)
  return {}
}

// AV stack · PLAN / local motion planner (sampling-based, receding horizon).
// Candidate paths = constant-curvature turn (limited turn angle) followed by a straight, so a path can
// swing around an obstacle and then run alongside it. Each path is swept with the vehicle footprint
// (margin grows with speed) against the costmap. Cost = progress to goal, heading, required stopping
// length, clearance, smoothness. Publishes av.plan {kappa, free, freeSoft, clearance, blocked, horizon}.
// debug draw: yellow = line to goal / route carrot, dark blue = candidate fan, green = chosen path, orange = where it would hit.
// params: vehicleWidth, vehicleLength, safetyMargin, marginSpeedGain, softMargin, maxCurvature, arcCount,
//         horizonMin, horizonGain, horizonMax, comfortDecel, wProgress, wHeading, wRequired, wFree, wSoft,
//         wSmooth, wTurn, minFree, rearIgnore, debugDraw
function transform(input, dt, params, state, api) {
  var av = input.av
  if (!av || !av.ego) return {}
  var e = av.ego
  var tgt = input.target && input.target.pose && input.target.pose.position
  if (!tgt) {
    av.plan = { kappa: 0, free: 0, freeSoft: 0, clearance: 0, blocked: false, horizon: 0, noGoal: true }
    return {}
  }
  var pos = input.position
  var tdx = tgt[0] - pos[0]
  var tdz = tgt[2] - pos[2]
  av.goal = { x: tgt[0], z: tgt[2], dist: Math.sqrt(tdx * tdx + tdz * tdz) }
  // manoeuvre planner owns the controls (multi-point turn): pass its command through
  if (av.override) {
    av.plan = { kappa: av.override.kappa, vDesired: av.override.vDesired, free: 99, freeSoft: 99, clearance: 9, blocked: false, horizon: 0, override: true }
    return {}
  }
  // chase the route's carrot (global plan) when there is one, else the raw goal
  var aim = av.carrot ? [av.carrot[0], 0, av.carrot[1]] : tgt
  var gdx = aim[0] - pos[0]
  var gdz = aim[2] - pos[2]
  var gx = gdx * e.fwd[0] + gdz * e.fwd[2]
  var gy = gdx * e.left[0] + gdz * e.left[2]
  var goalDist = Math.sqrt(gx * gx + gy * gy)

  var v = Math.max(0, e.speedF)
  var margin = (params.safetyMargin != null ? params.safetyMargin : 0.5) + (params.marginSpeedGain != null ? params.marginSpeedGain : 0.05) * v
  var soft = params.softMargin != null ? params.softMargin : 1.1
  var halfW = (params.vehicleWidth || 2) / 2 + margin
  var halfL = (params.vehicleLength || 4) / 2 + margin
  var kmax = params.maxCurvature || 0.115
  var count = params.arcCount || 31
  var hMin = params.horizonMin != null ? params.horizonMin : 10
  var hMax = params.horizonMax != null ? params.horizonMax : 26
  var H = Math.min(hMax, hMin + (params.horizonGain != null ? params.horizonGain : 1.2) * v)
  var aBrake = params.comfortDecel || 5
  var Lreq = Math.min(H, (v * v) / (2 * aBrake) + 5)
  var wProg = params.wProgress != null ? params.wProgress : 1.0
  var wHead = params.wHeading != null ? params.wHeading : 2.0
  var wReq = params.wRequired != null ? params.wRequired : 60
  var wFree = params.wFree != null ? params.wFree : 10
  var wSoft = params.wSoft != null ? params.wSoft : 8
  var wSmooth = params.wSmooth != null ? params.wSmooth : 2.5
  var wTurn = params.wTurn != null ? params.wTurn : 1.5
  var minFree = params.minFree != null ? params.minFree : 4.5
  var ds = 0.75
  var turnAngles = [0.5, 1.15]

  // costmap into ego frame
  var pts = av.points || []
  var ox = []
  var oy = []
  for (var i = 0; i < pts.length; i++) {
    var dx = pts[i][0] - pos[0]
    var dz = pts[i][1] - pos[2]
    var px = dx * e.fwd[0] + dz * e.fwd[2]
    var py = dx * e.left[0] + dz * e.left[2]
    if (px > -halfL - soft - 3 && px < H + halfL + soft + 3 && py > -H - 4 && py < H + 4) {
      ox.push(px)
      oy.push(py)
    }
  }

  // pose along a path: turn at `kappa` for `turnLen`, then straight
  function poseAt(kappa, turnLen, s, out) {
    var sa = s < turnLen ? s : turnLen
    var th = kappa * sa
    var x
    var y
    if (Math.abs(kappa) < 1e-6) {
      x = sa
      y = 0
    } else {
      x = Math.sin(th) / kappa
      y = (1 - Math.cos(th)) / kappa
    }
    if (s > turnLen) {
      x += Math.cos(th) * (s - turnLen)
      y += Math.sin(th) * (s - turnLen)
    }
    out.x = x
    out.y = y
    out.th = th
  }
  var P = { x: 0, y: 0, th: 0 }

  // forward paths only sweep the front of the footprint: an obstacle already behind/at the tail (touching
  // start pose) must not veto driving away from it
  var rearIgnore = params.rearIgnore != null ? params.rearIgnore : 1.4
  function freeLength(kappa, turnLen, hw, hl) {
    var hlRear = Math.max(0.3, hl - rearIgnore)
    for (var s = 0; s <= H; s += ds) {
      poseAt(kappa, turnLen, s, P)
      var ct = Math.cos(P.th)
      var st = Math.sin(P.th)
      for (var q = 0; q < ox.length; q++) {
        var rx = ox[q] - P.x
        var ry = oy[q] - P.y
        var lx = ct * rx + st * ry
        var ly = -st * rx + ct * ry
        if (lx > -hlRear && lx < hl && ly > -hw && ly < hw) return Math.max(0, s - ds)
      }
    }
    return H
  }

  var prev = state.prevKappa || 0
  var prevTurn = state.prevTurn || 0
  var best = null
  var bestCost = Infinity
  var bestHard = 0
  var bestSoft = 0
  var bestTurnLen = 0
  var cand = []
  for (var a = 0; a < count; a++) {
    var kappa = count === 1 ? 0 : -kmax + (2 * kmax * a) / (count - 1)
    for (var ti = 0; ti < turnAngles.length; ti++) {
      if (Math.abs(kappa) < 1e-6 && ti > 0) continue
      var turnLen = Math.abs(kappa) < 1e-6 ? H : Math.min(H, turnAngles[ti] / Math.abs(kappa))
      var fHard = freeLength(kappa, turnLen, halfW, halfL)
      var fSoft = freeLength(kappa, turnLen, halfW + soft - margin, halfL + soft - margin)
      var L = fHard
      poseAt(kappa, turnLen, L, P)
      var gdEnd = Math.sqrt((gx - P.x) * (gx - P.x) + (gy - P.y) * (gy - P.y))
      var progress = goalDist - gdEnd
      var herr = Math.atan2(gy - P.y, gx - P.x) - P.th
      while (herr > Math.PI) herr -= 2 * Math.PI
      while (herr < -Math.PI) herr += 2 * Math.PI
      var cost =
        -wProg * progress +
        wHead * Math.abs(herr) +
        wReq * Math.max(0, 1 - L / Lreq) +
        wFree * (1 - L / H) +
        wSoft * (1 - Math.min(fSoft, H) / H) +
        wSmooth * (Math.abs(kappa - prev) / kmax) +
        wTurn * Math.abs(kappa * turnLen)
      if (cost < bestCost) {
        bestCost = cost
        best = kappa
        bestHard = fHard
        bestSoft = fSoft
        bestTurnLen = turnLen
      }
      if (params.debugDraw !== false && a % 8 === 0 && ti === 0) cand.push([kappa, turnLen, fHard])
    }
  }
  state.prevKappa = best

  // lateral clearance of the chosen path over the distance that matters (beyond the hard margin)
  var clearance = 0
  var margins = [0.5, 1.0, 1.5, 2.5]
  var needLen = Math.min(bestHard, Lreq)
  for (var mi = 0; mi < margins.length; mi++) {
    var fm = freeLength(best, bestTurnLen, halfW + margins[mi], halfL + margins[mi])
    if (fm >= needLen - 1e-6) clearance = margins[mi]
    else break
  }

  av.plan = {
    kappa: best,
    free: bestHard,
    freeSoft: bestSoft,
    clearance: clearance,
    margin: margin,
    blocked: bestHard < minFree,
    horizon: H,
    required: Lreq,
    cost: bestCost,
  }
  api.watch('av.plan.kappa', Math.round(best * 1000) / 1000)
  api.watch('av.plan.free', Math.round(bestHard * 10) / 10 + ' clr ' + clearance)

  if (params.debugDraw !== false) {
    var y0 = pos[1]
    var W = { x: 0, y: 0, th: 0 }
    function world(x, y) {
      return [pos[0] + e.fwd[0] * x + e.left[0] * y, y0, pos[2] + e.fwd[2] * x + e.left[2] * y]
    }
    function drawPath(kk, tl, len, color, step) {
      var prevW = null
      for (var s = 0; s <= len + 1e-6; s += step) {
        poseAt(kk, tl, s, W)
        var wp = world(W.x, W.y)
        if (prevW) api.visualizeLine(prevW, wp, color)
        prevW = wp
      }
    }
    api.visualizeLine(pos, [aim[0], y0, aim[2]], '#ffcc00')
    for (var ci = 0; ci < cand.length; ci++) drawPath(cand[ci][0], cand[ci][1], cand[ci][2], '#3a5a9a', Math.max(4, cand[ci][2] / 3))
    drawPath(best, bestTurnLen, bestHard, '#22dd66', 2.5)
    if (bestHard < H) drawPath(best, bestTurnLen, Math.min(H, bestHard + 3), '#ff8800', 3)
  }
  return {}
}

// AV stack · PLAN / speed planner.
// v_des = min(cruise, stopping-distance limit, clearance limit, route bends ahead, lateral-acceleration limit, goal approach).
// Clearance limit: lots of room beside obstacles → full speed; squeezing past → slow.
// Goal approach only slows for the FINAL waypoint (av.mission, else params.waypoints; otherwise every goal is final).
// Publishes av.plan.vDesired / av.plan.vLimit.
// params: cruiseSpeed, comfortDecel, maxLatAccel, stopMargin, crawlSpeed, goalTolerance, clearSpeedBase,
//         clearSpeedGain, waypoints
function transform(input, dt, params, state, api) {
  var av = input.av
  if (!av || !av.plan) return {}
  var plan = av.plan
  if (plan.override) return {}
  var cruise = params.cruiseSpeed != null ? params.cruiseSpeed : 10
  var aBrake = params.comfortDecel || 5
  var aLat = params.maxLatAccel || 7
  var stopMargin = params.stopMargin != null ? params.stopMargin : 1.2
  var crawl = params.crawlSpeed != null ? params.crawlSpeed : 2
  var base = params.clearSpeedBase != null ? params.clearSpeedBase : 5
  var gain = params.clearSpeedGain != null ? params.clearSpeedGain : 3.5
  var limit = 'cruise'
  var v = cruise
  var vFree = Math.sqrt(2 * aBrake * Math.max(0, plan.free - stopMargin))
  if (vFree < v) {
    v = vFree
    limit = 'free'
  }
  // lateral gap to the nearest obstacle surface along the chosen path (safety margin + measured extra room)
  var vClear = base + gain * Math.max(0, (plan.margin || 0.5) + (plan.clearance || 0) - 0.3)
  if (vClear < v) {
    v = vClear
    limit = 'clearance'
  }
  // bends ahead on the global route (corner speed, reachable by braking)
  if (av.route && av.route.vLimit < v) {
    v = Math.max(av.route.vLimit, crawl)
    limit = 'route'
  }
  var k = Math.abs(plan.kappa)
  if (k > 1e-4) {
    var vCurve = Math.sqrt(aLat / k)
    if (vCurve < v) {
      v = vCurve
      limit = 'curve'
    }
  }
  if (av.goal) {
    var tol = params.goalTolerance != null ? params.goalTolerance : 3.5
    var wps = params.waypoints
    var isFinal = true
    if (av.mission) {
      isFinal = av.mission.isFinal
    } else if (wps && wps.length) {
      var last = wps[wps.length - 1]
      isFinal = Math.abs(av.goal.x - last[0]) < 0.05 && Math.abs(av.goal.z - last[1]) < 0.05
    }
    if (isFinal) {
      var vGoal = Math.sqrt(2 * aBrake * Math.max(0, av.goal.dist - tol))
      if (vGoal < v) {
        v = Math.max(vGoal, crawl)
        limit = 'goal'
      }
    }
  }
  if (!plan.blocked && v < crawl) v = crawl
  plan.vDesired = v
  plan.vLimit = limit
  api.watch('av.vLimit', limit + ' ' + v.toFixed(1))
  return {}
}

// AV stack · PLAN / behaviour supervisor.
// Watches planner health and flags `av.needManeuver` when the local planner is blocked
// or the vehicle is stuck; holds at the final goal. Sets av.mode ('drive' | 'hold').
// debug draw: vertical mast above the car = status (green drive, orange needs manoeuvre, white hold).
// Simulated time only. params: stuckTime, blockedTime, holdAtGoal, goalTolerance
function transform(input, dt, params, state, api) {
  var av = input.av
  if (!av || !av.plan || !av.ego) return {}
  var e = av.ego
  var plan = av.plan
  if (state.stuckT === undefined) {
    state.stuckT = 0
    state.blockedT = 0
  }
  var stuckTime = params.stuckTime != null ? params.stuckTime : 1.5
  var blockedTime = params.blockedTime != null ? params.blockedTime : 0.4
  var wantsMove = (plan.vDesired || 0) > 0.8
  if (wantsMove && Math.abs(e.speed) < 0.25) state.stuckT += dt
  else state.stuckT = 0
  if (plan.blocked && Math.abs(e.speed) < 1.2) state.blockedT += dt
  else state.blockedT = 0
  av.needManeuver = state.blockedT > blockedTime || state.stuckT > stuckTime
  av.mode = av.override ? 'maneuver' : 'drive'
  var tol = params.goalTolerance != null ? params.goalTolerance : 3.5
  var finalGoal = !av.mission || av.mission.isFinal
  if (params.holdAtGoal !== false && finalGoal && av.goal && av.goal.dist < tol) {
    av.mode = 'hold'
    plan.override = false
    plan.vDesired = 0
    plan.kappa = 0
  }
  if (params.debugDraw !== false) {
    // status mast above the car: green drive, orange manoeuvre requested, white hold
    var c = av.mode === 'hold' ? '#ffffff' : av.needManeuver ? '#ff8800' : '#00ff66'
    api.visualizeLine([e.pos[0], e.pos[1] + 1.2, e.pos[2]], [e.pos[0], e.pos[1] + 4, e.pos[2]], c)
  }
  return {}
}

// AV stack · CONTROL / lateral (curvature tracking).
// steering = feed-forward(kappa_plan / kappaPerSteer) + P feedback on measured curvature,
// with a steering-rate limiter (comfort / actuator model).
// debug draw: white = commanded steering direction.
// params: kappaPerSteer, fbGain, steerRate
function transform(input, dt, params, state, api) {
  var av = input.av
  if (!av || !av.plan || !av.ego) return {}
  var e = av.ego
  var kps = params.kappaPerSteer || 0.12
  var fb = params.fbGain != null ? params.fbGain : 0.35
  var rate = params.steerRate != null ? params.steerRate : 4
  var kCmd = av.plan.kappa
  var steer = kCmd / kps
  if (Math.abs(e.speed) > 2 && av.mode !== 'reverse') {
    steer += (fb * (kCmd - e.kappa)) / kps
  }
  if (steer > 1) steer = 1
  if (steer < -1) steer = -1
  var prev = state.steer || 0
  var maxStep = rate * dt
  if (steer > prev + maxStep) steer = prev + maxStep
  if (steer < prev - maxStep) steer = prev - maxStep
  state.steer = steer
  // car2 treats exactly 0 as "no steering command" (wheel re-centres on its own)
  input.actions.steering_angle = Math.abs(steer) < 1e-4 ? 0 : steer
  av.cmdSteer = steer
  if (params.debugDraw !== false) {
    // white: commanded steering direction from the nose (4 m chord)
    var th = steer * kps * 4
    var nose = api.vec.offsetAlong(input.position, e.fwd, 2)
    var dir = [e.fwd[0] * Math.cos(th) + e.left[0] * Math.sin(th), 0, e.fwd[2] * Math.cos(th) + e.left[2] * Math.sin(th)]
    api.visualizeLine(nose, api.vec.offsetAlong(nose, dir, 4), '#ffffff')
  }
  return {}
}

// AV stack · CONTROL / longitudinal (speed PI with deadband feed-forward).
// The actuator has a static-friction deadband, so the controller adds `deadband` as feed-forward
// and PI-trims on top. Negative demand maps to the car's `brake` input (reverse thrust at standstill).
// params: kp, ki, deadband, maxThrottle, maxBrake, brakeGain
function transform(input, dt, params, state, api) {
  var av = input.av
  if (!av || !av.plan || !av.ego) return {}
  var e = av.ego
  var vDes = av.plan.vDesired || 0
  var kp = params.kp != null ? params.kp : 0.03
  var ki = params.ki != null ? params.ki : 0.02
  var db = params.deadband != null ? params.deadband : 0.36
  var maxThr = params.maxThrottle != null ? params.maxThrottle : 0.46
  var maxBrk = params.maxBrake != null ? params.maxBrake : 0.6
  var brakeGain = params.brakeGain != null ? params.brakeGain : 0.12
  // signed demand: positive = forward drive (throttle), negative = reverse drive (brake channel)
  var dir = vDes >= 0 ? 1 : -1
  var vAlong = e.speed * dir // speed in the demanded direction
  var vTarget = Math.abs(vDes)
  var err = vTarget - vAlong
  var thr = 0
  var brk = 0
  var drive = 0 // magnitude along the demanded direction
  var retard = 0 // magnitude opposing motion in the demanded direction
  if (vTarget < 0.05 && Math.abs(e.speed) < 0.3) {
    state.i = 0
  } else if (err > 0) {
    state.i = Math.min(0.1, (state.i || 0) + ki * err * dt)
    drive = Math.min(maxThr, db + kp * err + state.i)
  } else {
    state.i = Math.max(0, (state.i || 0) * 0.9)
    retard = Math.min(maxBrk, brakeGain * -err)
    if (vAlong < 0.3 && vTarget < 0.05) retard = 0
  }
  if (vTarget < 0.05 && Math.abs(e.speed) >= 0.3) {
    // demand zero but still rolling: brake against the current direction of travel
    var oppose = e.speed > 0 ? 1 : -1
    var b = Math.min(maxBrk, brakeGain * Math.abs(e.speed))
    if (oppose > 0) brk = b
    else thr = b
  } else if (dir > 0) {
    thr = drive
    brk = retard
  } else {
    brk = drive
    thr = retard
  }
  input.actions.throttle = thr
  input.actions.brake = brk
  av.cmd = { throttle: thr, brake: brk }
  return {}
}

// AV stack · SAFETY / autonomous emergency braking (independent monitor, own sensing).
// Runs after control and may only reduce throttle / add brake. Uses a smaller margin while the manoeuvre planner is driving (it already keeps swept clearance).
// debug draw: dark gold = AEB look-ahead, red = AEB triggered.
// params: aebDecel, aebMargin, aebHalfWidth
function transform(input, dt, params, state, api) {
  var av = input.av
  if (!av || !av.ego) return {}
  var e = av.ego
  if (e.speed < 0.8) {
    av.aeb = false
    return {}
  }
  var a = params.aebDecel || 7
  var margin = params.aebMargin != null ? params.aebMargin : 1.0
  if (av.mode === 'maneuver') margin = 0.2
  var hw = params.aebHalfWidth != null ? params.aebHalfWidth : 0.9
  var need = (e.speed * e.speed) / (2 * a) + margin
  var origin = api.vec.offsetAlong(input.position, e.fwd, 2.3)
  var hit = api.raycastSpread(origin, e.fwd, need + 1, hw, 5, { visualize: false })
  av.aeb = false
  var drawOn = params.debugDraw !== false
  if (drawOn) api.visualizeLine(origin, api.vec.offsetAlong(origin, e.fwd, need), '#b8860b')
  if (hit.hit && hit.distance < need) {
    if (drawOn) api.visualizeLine(origin, api.vec.offsetAlong(origin, e.fwd, hit.distance), '#ff0000')
    av.aeb = true
    input.actions.throttle = 0
    var b = Math.min(1, 0.3 + (need - hit.distance) / need)
    if (b > (input.actions.brake || 0)) input.actions.brake = b
    api.watch('av.aeb', hit.distance)
  }
  return {}
}

// AV stack · SENSE / state estimation ("localization" layer).
// Publishes the ego state on the shared blackboard `input.av.ego` for all later stages.
// debug draw (params.debugDraw, default true): cyan = velocity vector.
// Owns the simulated clock (state.t) so no downstream stage needs a wall clock.
function transform(input, dt, params, state, api) {
  // fresh blackboard every frame (the input object is reused by the runtime)
  var av = (input.av = {})
  if (state.t === undefined) {
    state.t = 0
    state.speedF = 0
    state.prevSpeed = 0
    state.accelF = 0
  }
  state.t += dt
  var up = api.getUpVector(input.rotation)
  var fwd = api.vec.normalize(api.vec.projectOntoPlane(api.getForwardVector(input.rotation), up))
  var left = api.vec.normalize(api.vec.cross(up, fwd))
  var speed = api.vec.getForwardSpeed(input.velocity, fwd)
  var yawRate = api.vec.dot(input.angularVelocity, up)
  var a = dt > 1e-6 ? (speed - state.prevSpeed) / dt : 0
  state.prevSpeed = speed
  state.accelF += (a - state.accelF) * Math.min(1, dt * 8)
  state.speedF += (speed - state.speedF) * Math.min(1, dt * 20)
  av.ego = {
    t: state.t,
    dt: dt,
    pos: input.position,
    fwd: fwd,
    left: left,
    up: up,
    speed: speed,
    speedF: state.speedF,
    accel: state.accelF,
    yawRate: yawRate,
    kappa: Math.abs(speed) > 1.5 ? yawRate / speed : 0,
  }
  api.watch('av.speed', Math.round(speed * 10) / 10)
  if (params.debugDraw !== false) {
    // cyan: velocity vector
    api.visualizeLine(input.position, api.vec.add(input.position, api.vec.scale(input.velocity, 0.6)), '#00e5ff')
  }
  return {}
}

// AV stack · SENSE / perception.
// 360° range-scan ring (lidar-like, mounted at the vehicle centre, rays start on the hull)
// + obstacle memory ("local costmap") so the planners also know what is behind / beside.
// Publishes: av.scan {angles, ranges, range}, av.points [[x,z],...] (world), av.rearClear.
// debug draw (params.debugDraw, debugRayStride, debugMaxPoints): red = lidar hit rays, magenta ticks = costmap points.
// params: drivableArea [xmin, xmax, zmin, zmax] (virtual walls at the edge), edgeStep, rayCount, fovDeg, sensorRange, memoryTtl, memoryCell, vehicleWidth, vehicleLength
function transform(input, dt, params, state, api) {
  var av = input.av
  if (!av || !av.ego) return {}
  var e = av.ego
  var n = params.rayCount || 72
  var fov = ((params.fovDeg || 360) * Math.PI) / 180
  var range = params.sensorRange || 24
  var ttl = params.memoryTtl != null ? params.memoryTtl : 15
  var cell = params.memoryCell || 0.5
  var hl = (params.vehicleLength || 4) / 2 + 0.15
  var hw = (params.vehicleWidth || 2) / 2 + 0.15
  if (!state.mem) state.mem = {}
  var mem = state.mem
  var pos = input.position
  var full = fov >= 2 * Math.PI - 1e-3
  var angles = []
  var ranges = []
  var rearClear = params.rearRange || 8
  var draw = params.debugDraw !== false
  var rayStride = params.debugRayStride || 2
  for (var i = 0; i < n; i++) {
    var th = full ? -Math.PI + (2 * Math.PI * i) / n : n === 1 ? 0 : -fov / 2 + (fov * i) / (n - 1)
    var c = Math.cos(th)
    var s = Math.sin(th)
    var dir = [
      e.fwd[0] * c + e.left[0] * s,
      e.fwd[1] * c + e.left[1] * s,
      e.fwd[2] * c + e.left[2] * s,
    ]
    // start just outside the hull rectangle along this ray
    var tHull = Math.min(Math.abs(c) > 1e-6 ? hl / Math.abs(c) : 1e9, Math.abs(s) > 1e-6 ? hw / Math.abs(s) : 1e9)
    var origin = api.vec.offsetAlong(pos, dir, tHull)
    var r = api.raycast(origin, dir, range, { visualize: false })
    angles.push(th)
    if (r.hit) {
      if (draw && i % rayStride === 0) api.visualizeLine(origin, api.vec.offsetAlong(origin, dir, r.distance), '#ff4d4d')
      ranges.push(r.distance)
      var hx = origin[0] + dir[0] * r.distance
      var hz = origin[2] + dir[2] * r.distance
      mem[Math.round(hx / cell) + ',' + Math.round(hz / cell)] = { x: hx, z: hz, t: e.t }
      if (c < -0.9 && r.distance < rearClear) rearClear = r.distance
    } else {
      ranges.push(range)
    }
  }
  var pts = []
  // virtual walls along the edge of the drivable area (map prior): [xmin, xmax, zmin, zmax]
  var area = params.drivableArea
  if (area && area.length === 4) {
    var step = params.edgeStep || 1.2
    var reach = range
    var xs = Math.max(area[0], pos[0] - reach)
    var xe = Math.min(area[1], pos[0] + reach)
    var zs = Math.max(area[2], pos[2] - reach)
    var ze = Math.min(area[3], pos[2] + reach)
    var j
    if (pos[2] - area[2] < reach) for (j = xs; j <= xe; j += step) pts.push([j, area[2]])
    if (area[3] - pos[2] < reach) for (j = xs; j <= xe; j += step) pts.push([j, area[3]])
    if (pos[0] - area[0] < reach) for (j = zs; j <= ze; j += step) pts.push([area[0], j])
    if (area[1] - pos[0] < reach) for (j = zs; j <= ze; j += step) pts.push([area[1], j])
  }
  var keys = Object.keys(mem)
  for (var k = 0; k < keys.length; k++) {
    var m = mem[keys[k]]
    if (e.t - m.t > ttl) delete mem[keys[k]]
    else pts.push([m.x, m.z])
  }
  if (draw) {
    // magenta ticks: remembered obstacle points (costmap), nearest 60
    var near = pts
      .map(function (q) {
        var ddx = q[0] - pos[0]
        var ddz = q[1] - pos[2]
        return [ddx * ddx + ddz * ddz, q]
      })
      .sort(function (a, b) {
        return a[0] - b[0]
      })
      .slice(0, params.debugMaxPoints || 60)
    for (var pi = 0; pi < near.length; pi++) {
      var q2 = near[pi][1]
      api.visualizeLine([q2[0], pos[1] - 0.4, q2[1]], [q2[0], pos[1] + 0.5, q2[1]], '#ff00ff')
    }
  }
  av.scan = { angles: angles, ranges: ranges, range: range }
  av.points = pts
  av.rearClear = rearClear
  return {}
}

// AV stack · SENSE / mission overlay (debug only, no effect on driving).
// Draws the whole mission route: mint polyline + poles at every waypoint; the active target pole is yellow.
// Reads av.mission.waypoints (av-mission stage) or params.waypoints [[x, z], ...].
// params: waypoints, debugDraw
function transform(input, dt, params, state, api) {
  if (params.debugDraw === false) return {}
  var av = input.av
  var wps = (av && av.mission && av.mission.waypoints) || params.waypoints
  if (!wps || !wps.length) return {}
  var y = input.position[1]
  var cur = input.target && input.target.pose && input.target.pose.position
  for (var i = 0; i < wps.length; i++) {
    var w = wps[i]
    var active = cur && Math.abs(cur[0] - w[0]) < 0.05 && Math.abs(cur[2] - w[1]) < 0.05
    api.visualizeLine([w[0], y - 0.5, w[1]], [w[0], y + 5, w[1]], active ? '#ffcc00' : '#00ffcc')
    if (i > 0) api.visualizeLine([wps[i - 1][0], y - 0.4, wps[i - 1][1]], [w[0], y - 0.4, w[1]], '#7dffb0')
  }
  return {}
}

// AV stack · PLAN / route + manoeuvre planner (Hybrid-A* over forward/reverse arc primitives).
// Two jobs, one search:
//  1. ROUTE: every `routeInterval` s plans a collision-free route to the goal over the costmap and publishes
//     `av.carrot` (a point ~lookahead metres along the forward part of the route). The local planner chases
//     the carrot instead of the raw goal, so a goal behind an obstacle no longer produces endless orbits.
//  2. MANOEUVRE: if the route starts by reversing (or the car is stuck) it takes over (`av.override`): drives the
//     multi-point turn segment by segment, re-plans on drift/blockage/stall, and hands back as soon as the route
//     has a long forward run.
// Runs BEFORE the local motion planner. Simulated time only.
// debug draw: magenta = route / manoeuvre path (+ status mast while manoeuvring), orange = current segment end.
// params: maneuverSpeed, routeInterval, routeExpansions, lookahead, primitiveLength, maxExpansions,
//         gearSwitchPenalty, reversePenalty, maxReverseRun, planMargin, tightMargin, guardMargin, stallTime, stuckTime,
//         goalReach, handbackFree, goalTolerance, maxCurvature, vehicleWidth, vehicleLength
function transform(input, dt, params, state, api) {
  var av = input.av
  if (!av || !av.ego) return {}
  var e = av.ego
  var tgt = input.target && input.target.pose && input.target.pose.position
  if (!tgt) return {}
  var gxw = tgt[0]
  var gzw = tgt[2]
  var kmax = params.maxCurvature || 0.115
  var planMargin = params.planMargin != null ? params.planMargin : 0.4
  var tightMargin = params.tightMargin != null ? params.tightMargin : 0.1
  var guardMargin = params.guardMargin != null ? params.guardMargin : 0.15
  var ell = params.primitiveLength || 1.8
  var maxExpFull = params.maxExpansions || 4000
  var routeExp = params.routeExpansions || 1500
  var routeInterval = params.routeInterval != null ? params.routeInterval : 0.8
  var lookahead = params.lookahead != null ? params.lookahead : 14
  var gearPen = params.gearSwitchPenalty != null ? params.gearSwitchPenalty : 4
  var revPen = params.reversePenalty != null ? params.reversePenalty : 4
  var handback = params.handbackFree != null ? params.handbackFree : 10
  var vMan = params.maneuverSpeed != null ? params.maneuverSpeed : 3
  var stuckTime = params.stuckTime != null ? params.stuckTime : 1.5
  var holdTol = params.goalTolerance != null ? params.goalTolerance : 3.5
  // route ends inside the waypoint acceptance zone (not only at its centre)
  var reach = params.goalReach != null ? params.goalReach : 3.5
  var maxRevRun = params.maxReverseRun != null ? params.maxReverseRun : 8
  var termHeadW = params.exitHeadingWeight != null ? params.exitHeadingWeight : 0
  var ks = [-kmax, -kmax / 2, 0, kmax / 2, kmax]
  var pos = input.position
  // next waypoint after the current target: the route should arrive heading towards it
  var nextWp = null
  var wps = av.mission ? av.mission.waypoints : params.waypoints
  if (wps && wps.length) {
    for (var wi = 0; wi < wps.length - 1; wi++) {
      if (Math.abs(wps[wi][0] - gxw) < 0.05 && Math.abs(wps[wi][1] - gzw) < 0.05) {
        nextWp = wps[wi + 1]
        break
      }
    }
  }
  var goalDist = Math.sqrt((gxw - pos[0]) * (gxw - pos[0]) + (gzw - pos[2]) * (gzw - pos[2]))

  // spatial hash over costmap points + swept-footprint test (hl/hw are the active margins)
  function makeHit(pts, hlA, hwA) {
    var grid = {}
    for (var i = 0; i < pts.length; i++) {
      var key = Math.floor(pts[i][0] / 2) + ',' + Math.floor(pts[i][1] / 2)
      ;(grid[key] || (grid[key] = [])).push(pts[i])
    }
    var R = Math.sqrt(hlA * hlA + hwA * hwA)
    return function (x, z, fx, fz) {
      var x0 = Math.floor((x - R) / 2)
      var x1 = Math.floor((x + R) / 2)
      var z0 = Math.floor((z - R) / 2)
      var z1 = Math.floor((z + R) / 2)
      for (var cx = x0; cx <= x1; cx++) {
        for (var cz = z0; cz <= z1; cz++) {
          var list = grid[cx + ',' + cz]
          if (!list) continue
          for (var q = 0; q < list.length; q++) {
            var dx = list[q][0] - x
            var dz = list[q][1] - z
            var lx = dx * fx + dz * fz
            var ly = dx * fz - dz * fx
            if (lx > -hlA && lx < hlA && ly > -hwA && ly < hwA) return true
          }
        }
      }
      return false
    }
  }

  function search(sx, sz, sfx, sfz, gx, gz, pts, maxExp) {
    var hlS = (params.vehicleLength || 4) / 2 + planMargin
    var hwS = (params.vehicleWidth || 2) / 2 + planMargin
    var hit = makeHit(pts, hlS, hwS)
    // start already inside the comfort margin (drift, soft contact): re-plan with the tight margin so
    // the planner can still drive out of the margin band instead of finding every primitive blocked
    if (hit(sx, sz, sfx, sfz)) {
      hlS = (params.vehicleLength || 4) / 2 + tightMargin
      hwS = (params.vehicleWidth || 2) / 2 + tightMargin
      hit = makeHit(pts, hlS, hwS)
    }
    function dist(x, z) {
      var dx = gx - x
      var dz = gz - z
      return Math.sqrt(dx * dx + dz * dz)
    }
    // binary min-heap on f
    var heap = []
    function push(nd) {
      heap.push(nd)
      var c = heap.length - 1
      while (c > 0) {
        var p = (c - 1) >> 1
        if (heap[p].f <= heap[c].f) break
        var t = heap[p]
        heap[p] = heap[c]
        heap[c] = t
        c = p
      }
    }
    function pop() {
      var top = heap[0]
      var last = heap.pop()
      if (heap.length > 0) {
        heap[0] = last
        var c = 0
        for (;;) {
          var l = 2 * c + 1
          var r = l + 1
          var m = c
          if (l < heap.length && heap[l].f < heap[m].f) m = l
          if (r < heap.length && heap[r].f < heap[m].f) m = r
          if (m === c) break
          var t = heap[m]
          heap[m] = heap[c]
          heap[c] = t
          c = m
        }
      }
      return top
    }
    function skey(x, z, fx, fz, g) {
      var ih = Math.round((Math.atan2(fz, fx) / (2 * Math.PI)) * 36)
      if (ih < 0) ih += 36
      return Math.round(x / 0.6) + ',' + Math.round(z / 0.6) + ',' + (ih % 36) + ',' + g
    }
    var HW = 1.4
    var start = { x: sx, z: sz, fx: sfx, fz: sfz, g: 0, gear: 0, k: 0, parent: null, f: dist(sx, sz) * HW, d: 0 }
    push(start)
    var best = {}
    best[skey(sx, sz, sfx, sfz, 0)] = 0
    var bestNode = start
    var bestH = dist(sx, sz)
    var goalNode = null
    var expansions = 0
    while (heap.length > 0 && expansions < maxExp) {
      var cur = pop()
      var ck = skey(cur.x, cur.z, cur.fx, cur.fz, cur.gear)
      if (best[ck] !== undefined && cur.g > best[ck] + 1e-6) continue
      expansions++
      var h = dist(cur.x, cur.z)
      if (h < bestH) {
        bestH = h
        bestNode = cur
      }
      if (h < reach) {
        if (cur.terminal || !nextWp) {
          goalNode = cur
          break
        }
        // arrival cost: leave the goal zone heading towards the next waypoint
        var ndx = nextWp[0] - cur.x
        var ndz = nextWp[1] - cur.z
        var nl = Math.sqrt(ndx * ndx + ndz * ndz) || 1
        var cosA = Math.max(-1, Math.min(1, (cur.fx * ndx + cur.fz * ndz) / nl))
        var termG = cur.g + termHeadW * Math.acos(cosA)
        push({ x: cur.x, z: cur.z, fx: cur.fx, fz: cur.fz, g: termG, gear: cur.gear, k: cur.k, parent: cur, terminal: true, f: termG })
        continue
      }
      for (var gi = 0; gi < 2; gi++) {
        var gear = gi === 0 ? 1 : -1
        for (var ki = 0; ki < ks.length; ki++) {
          var k = ks[ki]
          var lx = cur.fz
          var lz = -cur.fx
          var revRun = gear < 0 ? (cur.gear < 0 ? cur.revRun || 0 : 0) + ell : 0
          if (revRun > maxRevRun) continue
          var ok = true
          var nx = cur.x
          var nz = cur.z
          var nfx = cur.fx
          var nfz = cur.fz
          for (var sIdx = 1; sIdx <= 4; sIdx++) {
            var d = (gear * ell * sIdx) / 4
            var th = k * d
            var ddx
            var ddy
            if (Math.abs(k) < 1e-6) {
              ddx = d
              ddy = 0
            } else {
              ddx = Math.sin(th) / k
              ddy = (1 - Math.cos(th)) / k
            }
            nx = cur.x + cur.fx * ddx + lx * ddy
            nz = cur.z + cur.fz * ddx + lz * ddy
            var ct = Math.cos(th)
            var st = Math.sin(th)
            nfx = cur.fx * ct + lx * st
            nfz = cur.fz * ct + lz * st
            if (hit(nx, nz, nfx, nfz)) {
              ok = false
              break
            }
          }
          if (!ok) continue
          var step = ell * (gear < 0 ? revPen : 1) + (Math.abs(k) / kmax) * 0.4 * ell
          if (cur.gear !== 0 && cur.gear !== gear) step += gearPen
          if (cur.gear !== 0 && cur.k !== k) step += 0.3
          var g2 = cur.g + step
          var nk = skey(nx, nz, nfx, nfz, gear)
          if (best[nk] !== undefined && best[nk] <= g2) continue
          best[nk] = g2
          push({ x: nx, z: nz, fx: nfx, fz: nfz, g: g2, gear: gear, k: k, revRun: revRun, parent: cur, f: g2 + dist(nx, nz) * HW })
        }
      }
    }
    var end = goalNode || bestNode
    if (end.terminal) end = end.parent
    var segs = []
    for (var nd = end; nd && nd.parent; nd = nd.parent) {
      var last = segs[0]
      if (last && last.g === nd.gear && last.k === nd.k) {
        last.len += ell
      } else {
        segs.unshift({ g: nd.gear, k: nd.k, len: ell, end: null })
      }
    }
    // expected pose at the end of every segment (walk the chain again, front to back)
    var chain = []
    for (var cn = end; cn; cn = cn.parent) chain.unshift(cn)
    var si = -1
    var prevG = null
    var prevK = null
    for (var ci = 1; ci < chain.length; ci++) {
      var nn = chain[ci]
      if (si < 0 || nn.gear !== prevG || nn.k !== prevK) {
        si++
        prevG = nn.gear
        prevK = nn.k
      }
      segs[si].end = { x: nn.x, z: nn.z, fx: nn.fx, fz: nn.fz }
    }
    var pathPts = []
    for (var pj = 0; pj < chain.length; pj++) pathPts.push([chain[pj].x, chain[pj].z])
    var nodes = []
    for (var nj = 0; nj < chain.length; nj++) nodes.push({ x: chain[nj].x, z: chain[nj].z, g: chain[nj].gear })
    return { segs: segs, reached: !!goalNode, expansions: expansions, hRemaining: bestH, path: pathPts, nodes: nodes }
  }

  function begin(res) {
    state.segs = res.segs
    state.idx = 0
    state.segStart = null
    state.prevGear = 0
    state.path = res.path
  }
  function deviates(seg) {
    if (!seg || !seg.end) return false
    var ex = pos[0] - seg.end.x
    var ez = pos[2] - seg.end.z
    var dot = e.fwd[0] * seg.end.fx + e.fwd[2] * seg.end.fz
    return Math.sqrt(ex * ex + ez * ez) > 0.9 || dot < 0.97
  }
  function plan(maxE) {
    return search(pos[0], pos[2], e.fwd[0], e.fwd[2], gxw, gzw, av.points || [], maxE)
  }
  // route summary: first gear, length of the leading forward run, carrot point
  function summarize(res) {
    var nodes = res.nodes
    var firstGear = nodes.length > 1 ? nodes[1].g : 1
    var run = 0
    var carrot = null
    if (firstGear === 1) {
      var want = Math.min(lookahead, 6 + 1.0 * Math.max(0, e.speedF))
      var acc = 0
      for (var i = 1; i < nodes.length && nodes[i].g === 1; i++) {
        var dx = nodes[i].x - nodes[i - 1].x
        var dz = nodes[i].z - nodes[i - 1].z
        acc += Math.sqrt(dx * dx + dz * dz)
        carrot = [nodes[i].x, nodes[i].z]
        if (acc >= want) break
      }
      run = acc
      for (var j = i; j < nodes.length && nodes[j].g === 1; j++) {
        var ddx = nodes[j].x - nodes[j - 1].x
        var ddz = nodes[j].z - nodes[j - 1].z
        run += Math.sqrt(ddx * ddx + ddz * ddz)
      }
    }
    // speed limit from the bends ahead on the route: corner speed sqrt(aLat / kappa), reachable by braking
    var aLat = params.maxLatAccel || 7
    var aBrk = params.comfortDecel || 5
    var vLimit = Infinity
    var dAhead = 0
    for (var si = 0; si < res.segs.length && dAhead < 40 && res.segs[si].g > 0; si++) {
      var kk = Math.abs(res.segs[si].k)
      if (kk > 0.04) {
        var vi = Math.sqrt(aLat / kk)
        var allowed = Math.sqrt(vi * vi + 2 * aBrk * dAhead)
        if (allowed < vLimit) vLimit = allowed
      }
      dAhead += res.segs[si].len
    }
    return { firstGear: firstGear, run: run, carrot: carrot, reached: res.reached, nodes: nodes, path: res.path, vLimit: vLimit }
  }

  // stuck watchdog (own, independent of the local planner)
  if (state.stuckT === undefined) state.stuckT = 0
  if (!state.active && Math.abs(e.speed) < 0.25 && goalDist > holdTol) state.stuckT += dt
  else state.stuckT = 0

  if (!state.active) {
    if (state.route === undefined || e.t - state.routeT >= routeInterval) {
      state.route = summarize(plan(routeExp))
      state.routeT = e.t
      state.revFresh = true
      state.routes = (state.routes || 0) + 1
    }
    var rt = state.route
    // hysteresis: a reverse-first route must be confirmed by two consecutive plans before the car manoeuvres
    state.revVotes = rt.firstGear === -1 ? (state.revFresh ? (state.revVotes || 0) + 1 : state.revVotes || 1) : 0
    state.revFresh = false
    var wantManeuver = (rt.firstGear === -1 && (state.revVotes >= 2 || Math.abs(e.speed) < 0.3) && Math.abs(e.speed) < 1.5) || state.stuckT > stuckTime
    if (wantManeuver && goalDist > holdTol) {
      var res = plan(maxExpFull)
      if (res.segs.length > 0) {
        state.active = true
        state.replans = (state.replans || 0) + 1
        state.stuckT = 0
        begin(res)
      }
    }
    if (!state.active) {
      if (rt.carrot) av.carrot = rt.carrot
      av.route = { firstGear: rt.firstGear, run: rt.run, reached: rt.reached, vLimit: rt.vLimit }
      if (params.debugDraw !== false) {
        var y0 = pos[1]
        for (var di = 2; di < rt.path.length; di += 2) {
          api.visualizeLine([rt.path[di - 2][0], y0, rt.path[di - 2][1]], [rt.path[di][0], y0, rt.path[di][1]], '#ff44ff')
        }
      }
      api.watch('av.route', 'gear ' + rt.firstGear + ' run ' + rt.run.toFixed(1) + (rt.reached ? ' goal' : ' partial'))
      return {}
    }
  }

  // --- execute manoeuvre ---
  var cur = state.segs[state.idx]
  if (state.segStart === null) {
    // a gear change must come to rest first so the odometer does not count coasting
    if (cur.g === state.prevGear || Math.abs(e.speed) < 0.4) state.segStart = [pos[0], pos[2]]
  }
  var travelled = 0
  if (state.segStart) {
    var dx = pos[0] - state.segStart[0]
    var dz = pos[2] - state.segStart[1]
    travelled = Math.sqrt(dx * dx + dz * dz)
  }
  // --- execution guard: re-plan when the real pose makes the rest of the segment collide, or when stalled ---
  if (state.segStart !== null) {
    var guardL = (params.vehicleLength || 4) / 2 + guardMargin
    var guardW = (params.vehicleWidth || 2) / 2 + guardMargin
    var gHit = makeHit(av.points || [], guardL, guardW)
    var lx0 = e.left[0]
    var lz0 = e.left[2]
    var look = Math.min(2.0, Math.max(0, cur.len - travelled))
    var blockedAhead = false
    for (var gd = 0.5; gd <= look + 1e-6 && !blockedAhead; gd += 0.5) {
      var gdd = cur.g * gd
      var gth = cur.k * gdd
      var gx2 = Math.abs(cur.k) < 1e-6 ? gdd : Math.sin(gth) / cur.k
      var gy2 = Math.abs(cur.k) < 1e-6 ? 0 : (1 - Math.cos(gth)) / cur.k
      var px = pos[0] + e.fwd[0] * gx2 + lx0 * gy2
      var pz = pos[2] + e.fwd[2] * gx2 + lz0 * gy2
      var pfx = e.fwd[0] * Math.cos(gth) + lx0 * Math.sin(gth)
      var pfz = e.fwd[2] * Math.cos(gth) + lz0 * Math.sin(gth)
      if (gHit(px, pz, pfx, pfz)) blockedAhead = true
    }
    state.stallT = Math.abs(e.speed) < 0.15 ? (state.stallT || 0) + dt : 0
    var stallTime = params.stallTime != null ? params.stallTime : 1.2
    if ((blockedAhead || state.stallT > stallTime) && e.t - (state.lastReplanT || -9) > 0.6) {
      var fix = plan(maxExpFull)
      state.lastReplanT = e.t
      state.stallT = 0
      state.replans++
      if (fix.segs.length > 0) {
        begin(fix)
        state.prevGear = cur.g
        cur = state.segs[0]
        travelled = 0
      }
    }
  }
  // hand back once the rest of the plan starts with a long forward run
  var fwdRun = 0
  if (state.idx > 0 || state.segs.length === 1) {
    for (var si = state.idx; si < state.segs.length && state.segs[si].g > 0; si++) fwdRun += state.segs[si].len
    fwdRun -= travelled
  }
  var aheadFree = false
  if (fwdRun >= handback && cur.g > 0) {
    // the car must really have room ahead on its own heading, not just a plan that will get there
    var aHit = makeHit(av.points || [], (params.vehicleLength || 4) / 2 + planMargin, (params.vehicleWidth || 2) / 2 + planMargin)
    aheadFree = true
    for (var ad = 0; ad <= handback && aheadFree; ad += 1) {
      // along the current segment's arc (what the local planner would also pick), not just straight on
      var ath = cur.k * ad
      var ax = Math.abs(cur.k) < 1e-6 ? ad : Math.sin(ath) / cur.k
      var ay = Math.abs(cur.k) < 1e-6 ? 0 : (1 - Math.cos(ath)) / cur.k
      var apx = pos[0] + e.fwd[0] * ax + e.left[0] * ay
      var apz = pos[2] + e.fwd[2] * ax + e.left[2] * ay
      if (aHit(apx, apz, e.fwd[0] * Math.cos(ath) + e.left[0] * Math.sin(ath), e.fwd[2] * Math.cos(ath) + e.left[2] * Math.sin(ath))) aheadFree = false
    }
  }
  if (aheadFree) {
    state.active = false
    state.route = undefined
    return {}
  }
  var finished = state.segStart !== null && travelled >= cur.len - 0.25
  if (finished) {
    state.prevGear = cur.g
    if (state.idx + 1 >= state.segs.length || deviates(cur)) {
      var again = plan(maxExpFull)
      state.replans++
      if (again.segs.length === 0 || state.idx + 1 >= state.segs.length) {
        state.active = false
        state.route = undefined
        if (again.segs.length === 0) return {}
      }
      if (again.segs.length > 0 && state.active) {
        begin(again)
        state.prevGear = cur.g
      }
    } else {
      state.idx++
      state.segStart = null
    }
    if (!state.active) return {}
    cur = state.segs[state.idx]
    travelled = 0
  }
  if (params.debugDraw !== false && state.path) {
    var py = pos[1]
    for (var pi = 2; pi < state.path.length; pi += 2) {
      api.visualizeLine([state.path[pi - 2][0], py, state.path[pi - 2][1]], [state.path[pi][0], py, state.path[pi][1]], '#ff44ff')
    }
    if (cur.end) api.visualizeLine(pos, [cur.end.x, py, cur.end.z], '#ff8800')
    api.visualizeLine([pos[0], py + 1.2, pos[2]], [pos[0], py + 4, pos[2]], '#ff44ff')
  }
  var remain = state.segStart ? Math.max(0, cur.len - travelled) : cur.len
  var vMax = Math.min(vMan, 0.9 + Math.sqrt(2 * 3 * remain))
  var wrongWay = state.segStart === null || cur.g * e.speed < -0.35
  av.override = { kappa: cur.k, vDesired: wrongWay ? 0 : cur.g * vMax }
  av.mode = 'maneuver'
  api.watch('av.maneuver', 'seg ' + state.idx + '/' + state.segs.length + ' g' + cur.g + ' k' + cur.k.toFixed(3) + ' replans ' + state.replans)
  return {}
}

// AV stack · PLAN / local motion planner (sampling-based, receding horizon).
// Candidate paths = constant-curvature turn (limited turn angle) followed by a straight, so a path can
// swing around an obstacle and then run alongside it. Each path is swept with the vehicle footprint
// (margin grows with speed) against the costmap. Cost = progress to goal, heading, required stopping
// length, clearance, smoothness. Publishes av.plan {kappa, free, freeSoft, clearance, blocked, horizon}.
// debug draw: yellow = line to goal / route carrot, dark blue = candidate fan, green = chosen path, orange = where it would hit.
// params: vehicleWidth, vehicleLength, safetyMargin, marginSpeedGain, softMargin, maxCurvature, arcCount,
//         horizonMin, horizonGain, horizonMax, comfortDecel, wProgress, wHeading, wRequired, wFree, wSoft,
//         wSmooth, wTurn, minFree, rearIgnore, debugDraw
function transform(input, dt, params, state, api) {
  var av = input.av
  if (!av || !av.ego) return {}
  var e = av.ego
  var tgt = input.target && input.target.pose && input.target.pose.position
  if (!tgt) {
    av.plan = { kappa: 0, free: 0, freeSoft: 0, clearance: 0, blocked: false, horizon: 0, noGoal: true }
    return {}
  }
  var pos = input.position
  var tdx = tgt[0] - pos[0]
  var tdz = tgt[2] - pos[2]
  av.goal = { x: tgt[0], z: tgt[2], dist: Math.sqrt(tdx * tdx + tdz * tdz) }
  // manoeuvre planner owns the controls (multi-point turn): pass its command through
  if (av.override) {
    av.plan = { kappa: av.override.kappa, vDesired: av.override.vDesired, free: 99, freeSoft: 99, clearance: 9, blocked: false, horizon: 0, override: true }
    return {}
  }
  // chase the route's carrot (global plan) when there is one, else the raw goal
  var aim = av.carrot ? [av.carrot[0], 0, av.carrot[1]] : tgt
  var gdx = aim[0] - pos[0]
  var gdz = aim[2] - pos[2]
  var gx = gdx * e.fwd[0] + gdz * e.fwd[2]
  var gy = gdx * e.left[0] + gdz * e.left[2]
  var goalDist = Math.sqrt(gx * gx + gy * gy)

  var v = Math.max(0, e.speedF)
  var margin = (params.safetyMargin != null ? params.safetyMargin : 0.5) + (params.marginSpeedGain != null ? params.marginSpeedGain : 0.05) * v
  var soft = params.softMargin != null ? params.softMargin : 1.1
  var halfW = (params.vehicleWidth || 2) / 2 + margin
  var halfL = (params.vehicleLength || 4) / 2 + margin
  var kmax = params.maxCurvature || 0.115
  var count = params.arcCount || 31
  var hMin = params.horizonMin != null ? params.horizonMin : 10
  var hMax = params.horizonMax != null ? params.horizonMax : 26
  var H = Math.min(hMax, hMin + (params.horizonGain != null ? params.horizonGain : 1.2) * v)
  var aBrake = params.comfortDecel || 5
  var Lreq = Math.min(H, (v * v) / (2 * aBrake) + 5)
  var wProg = params.wProgress != null ? params.wProgress : 1.0
  var wHead = params.wHeading != null ? params.wHeading : 2.0
  var wReq = params.wRequired != null ? params.wRequired : 60
  var wFree = params.wFree != null ? params.wFree : 10
  var wSoft = params.wSoft != null ? params.wSoft : 8
  var wSmooth = params.wSmooth != null ? params.wSmooth : 2.5
  var wTurn = params.wTurn != null ? params.wTurn : 1.5
  var minFree = params.minFree != null ? params.minFree : 4.5
  var ds = 0.75
  var turnAngles = [0.5, 1.15]

  // costmap into ego frame
  var pts = av.points || []
  var ox = []
  var oy = []
  for (var i = 0; i < pts.length; i++) {
    var dx = pts[i][0] - pos[0]
    var dz = pts[i][1] - pos[2]
    var px = dx * e.fwd[0] + dz * e.fwd[2]
    var py = dx * e.left[0] + dz * e.left[2]
    if (px > -halfL - soft - 3 && px < H + halfL + soft + 3 && py > -H - 4 && py < H + 4) {
      ox.push(px)
      oy.push(py)
    }
  }

  // pose along a path: turn at `kappa` for `turnLen`, then straight
  function poseAt(kappa, turnLen, s, out) {
    var sa = s < turnLen ? s : turnLen
    var th = kappa * sa
    var x
    var y
    if (Math.abs(kappa) < 1e-6) {
      x = sa
      y = 0
    } else {
      x = Math.sin(th) / kappa
      y = (1 - Math.cos(th)) / kappa
    }
    if (s > turnLen) {
      x += Math.cos(th) * (s - turnLen)
      y += Math.sin(th) * (s - turnLen)
    }
    out.x = x
    out.y = y
    out.th = th
  }
  var P = { x: 0, y: 0, th: 0 }

  // forward paths only sweep the front of the footprint: an obstacle already behind/at the tail (touching
  // start pose) must not veto driving away from it
  var rearIgnore = params.rearIgnore != null ? params.rearIgnore : 1.4
  function freeLength(kappa, turnLen, hw, hl) {
    var hlRear = Math.max(0.3, hl - rearIgnore)
    for (var s = 0; s <= H; s += ds) {
      poseAt(kappa, turnLen, s, P)
      var ct = Math.cos(P.th)
      var st = Math.sin(P.th)
      for (var q = 0; q < ox.length; q++) {
        var rx = ox[q] - P.x
        var ry = oy[q] - P.y
        var lx = ct * rx + st * ry
        var ly = -st * rx + ct * ry
        if (lx > -hlRear && lx < hl && ly > -hw && ly < hw) return Math.max(0, s - ds)
      }
    }
    return H
  }

  var prev = state.prevKappa || 0
  var prevTurn = state.prevTurn || 0
  var best = null
  var bestCost = Infinity
  var bestHard = 0
  var bestSoft = 0
  var bestTurnLen = 0
  var cand = []
  for (var a = 0; a < count; a++) {
    var kappa = count === 1 ? 0 : -kmax + (2 * kmax * a) / (count - 1)
    for (var ti = 0; ti < turnAngles.length; ti++) {
      if (Math.abs(kappa) < 1e-6 && ti > 0) continue
      var turnLen = Math.abs(kappa) < 1e-6 ? H : Math.min(H, turnAngles[ti] / Math.abs(kappa))
      var fHard = freeLength(kappa, turnLen, halfW, halfL)
      var fSoft = freeLength(kappa, turnLen, halfW + soft - margin, halfL + soft - margin)
      var L = fHard
      poseAt(kappa, turnLen, L, P)
      var gdEnd = Math.sqrt((gx - P.x) * (gx - P.x) + (gy - P.y) * (gy - P.y))
      var progress = goalDist - gdEnd
      var herr = Math.atan2(gy - P.y, gx - P.x) - P.th
      while (herr > Math.PI) herr -= 2 * Math.PI
      while (herr < -Math.PI) herr += 2 * Math.PI
      var cost =
        -wProg * progress +
        wHead * Math.abs(herr) +
        wReq * Math.max(0, 1 - L / Lreq) +
        wFree * (1 - L / H) +
        wSoft * (1 - Math.min(fSoft, H) / H) +
        wSmooth * (Math.abs(kappa - prev) / kmax) +
        wTurn * Math.abs(kappa * turnLen)
      if (cost < bestCost) {
        bestCost = cost
        best = kappa
        bestHard = fHard
        bestSoft = fSoft
        bestTurnLen = turnLen
      }
      if (params.debugDraw !== false && a % 8 === 0 && ti === 0) cand.push([kappa, turnLen, fHard])
    }
  }
  state.prevKappa = best

  // lateral clearance of the chosen path over the distance that matters (beyond the hard margin)
  var clearance = 0
  var margins = [0.5, 1.0, 1.5, 2.5]
  var needLen = Math.min(bestHard, Lreq)
  for (var mi = 0; mi < margins.length; mi++) {
    var fm = freeLength(best, bestTurnLen, halfW + margins[mi], halfL + margins[mi])
    if (fm >= needLen - 1e-6) clearance = margins[mi]
    else break
  }

  av.plan = {
    kappa: best,
    free: bestHard,
    freeSoft: bestSoft,
    clearance: clearance,
    margin: margin,
    blocked: bestHard < minFree,
    horizon: H,
    required: Lreq,
    cost: bestCost,
  }
  api.watch('av.plan.kappa', Math.round(best * 1000) / 1000)
  api.watch('av.plan.free', Math.round(bestHard * 10) / 10 + ' clr ' + clearance)

  if (params.debugDraw !== false) {
    var y0 = pos[1]
    var W = { x: 0, y: 0, th: 0 }
    function world(x, y) {
      return [pos[0] + e.fwd[0] * x + e.left[0] * y, y0, pos[2] + e.fwd[2] * x + e.left[2] * y]
    }
    function drawPath(kk, tl, len, color, step) {
      var prevW = null
      for (var s = 0; s <= len + 1e-6; s += step) {
        poseAt(kk, tl, s, W)
        var wp = world(W.x, W.y)
        if (prevW) api.visualizeLine(prevW, wp, color)
        prevW = wp
      }
    }
    api.visualizeLine(pos, [aim[0], y0, aim[2]], '#ffcc00')
    for (var ci = 0; ci < cand.length; ci++) drawPath(cand[ci][0], cand[ci][1], cand[ci][2], '#3a5a9a', Math.max(4, cand[ci][2] / 3))
    drawPath(best, bestTurnLen, bestHard, '#22dd66', 2.5)
    if (bestHard < H) drawPath(best, bestTurnLen, Math.min(H, bestHard + 3), '#ff8800', 3)
  }
  return {}
}

// AV stack · PLAN / speed planner.
// v_des = min(cruise, stopping-distance limit, clearance limit, route bends ahead, lateral-acceleration limit, goal approach).
// Clearance limit: lots of room beside obstacles → full speed; squeezing past → slow.
// Goal approach only slows for the FINAL waypoint (av.mission, else params.waypoints; otherwise every goal is final).
// Publishes av.plan.vDesired / av.plan.vLimit.
// params: cruiseSpeed, comfortDecel, maxLatAccel, stopMargin, crawlSpeed, goalTolerance, clearSpeedBase,
//         clearSpeedGain, waypoints
function transform(input, dt, params, state, api) {
  var av = input.av
  if (!av || !av.plan) return {}
  var plan = av.plan
  if (plan.override) return {}
  var cruise = params.cruiseSpeed != null ? params.cruiseSpeed : 10
  var aBrake = params.comfortDecel || 5
  var aLat = params.maxLatAccel || 7
  var stopMargin = params.stopMargin != null ? params.stopMargin : 1.2
  var crawl = params.crawlSpeed != null ? params.crawlSpeed : 2
  var base = params.clearSpeedBase != null ? params.clearSpeedBase : 5
  var gain = params.clearSpeedGain != null ? params.clearSpeedGain : 3.5
  var limit = 'cruise'
  var v = cruise
  var vFree = Math.sqrt(2 * aBrake * Math.max(0, plan.free - stopMargin))
  if (vFree < v) {
    v = vFree
    limit = 'free'
  }
  // lateral gap to the nearest obstacle surface along the chosen path (safety margin + measured extra room)
  var vClear = base + gain * Math.max(0, (plan.margin || 0.5) + (plan.clearance || 0) - 0.3)
  if (vClear < v) {
    v = vClear
    limit = 'clearance'
  }
  // bends ahead on the global route (corner speed, reachable by braking)
  if (av.route && av.route.vLimit < v) {
    v = Math.max(av.route.vLimit, crawl)
    limit = 'route'
  }
  var k = Math.abs(plan.kappa)
  if (k > 1e-4) {
    var vCurve = Math.sqrt(aLat / k)
    if (vCurve < v) {
      v = vCurve
      limit = 'curve'
    }
  }
  if (av.goal) {
    var tol = params.goalTolerance != null ? params.goalTolerance : 3.5
    var wps = params.waypoints
    var isFinal = true
    if (av.mission) {
      isFinal = av.mission.isFinal
    } else if (wps && wps.length) {
      var last = wps[wps.length - 1]
      isFinal = Math.abs(av.goal.x - last[0]) < 0.05 && Math.abs(av.goal.z - last[1]) < 0.05
    }
    if (isFinal) {
      var vGoal = Math.sqrt(2 * aBrake * Math.max(0, av.goal.dist - tol))
      if (vGoal < v) {
        v = Math.max(vGoal, crawl)
        limit = 'goal'
      }
    }
  }
  if (!plan.blocked && v < crawl) v = crawl
  plan.vDesired = v
  plan.vLimit = limit
  api.watch('av.vLimit', limit + ' ' + v.toFixed(1))
  return {}
}

// AV stack · PLAN / behaviour supervisor.
// Watches planner health and flags `av.needManeuver` when the local planner is blocked
// or the vehicle is stuck; holds at the final goal. Sets av.mode ('drive' | 'hold').
// debug draw: vertical mast above the car = status (green drive, orange needs manoeuvre, white hold).
// Simulated time only. params: stuckTime, blockedTime, holdAtGoal, goalTolerance
function transform(input, dt, params, state, api) {
  var av = input.av
  if (!av || !av.plan || !av.ego) return {}
  var e = av.ego
  var plan = av.plan
  if (state.stuckT === undefined) {
    state.stuckT = 0
    state.blockedT = 0
  }
  var stuckTime = params.stuckTime != null ? params.stuckTime : 1.5
  var blockedTime = params.blockedTime != null ? params.blockedTime : 0.4
  var wantsMove = (plan.vDesired || 0) > 0.8
  if (wantsMove && Math.abs(e.speed) < 0.25) state.stuckT += dt
  else state.stuckT = 0
  if (plan.blocked && Math.abs(e.speed) < 1.2) state.blockedT += dt
  else state.blockedT = 0
  av.needManeuver = state.blockedT > blockedTime || state.stuckT > stuckTime
  av.mode = av.override ? 'maneuver' : 'drive'
  var tol = params.goalTolerance != null ? params.goalTolerance : 3.5
  var finalGoal = !av.mission || av.mission.isFinal
  if (params.holdAtGoal !== false && finalGoal && av.goal && av.goal.dist < tol) {
    av.mode = 'hold'
    plan.override = false
    plan.vDesired = 0
    plan.kappa = 0
  }
  if (params.debugDraw !== false) {
    // status mast above the car: green drive, orange manoeuvre requested, white hold
    var c = av.mode === 'hold' ? '#ffffff' : av.needManeuver ? '#ff8800' : '#00ff66'
    api.visualizeLine([e.pos[0], e.pos[1] + 1.2, e.pos[2]], [e.pos[0], e.pos[1] + 4, e.pos[2]], c)
  }
  return {}
}

// AV stack · CONTROL / lateral (curvature tracking).
// steering = feed-forward(kappa_plan / kappaPerSteer) + P feedback on measured curvature,
// with a steering-rate limiter (comfort / actuator model).
// debug draw: white = commanded steering direction.
// params: kappaPerSteer, fbGain, steerRate
function transform(input, dt, params, state, api) {
  var av = input.av
  if (!av || !av.plan || !av.ego) return {}
  var e = av.ego
  var kps = params.kappaPerSteer || 0.12
  var fb = params.fbGain != null ? params.fbGain : 0.35
  var rate = params.steerRate != null ? params.steerRate : 4
  var kCmd = av.plan.kappa
  var steer = kCmd / kps
  if (Math.abs(e.speed) > 2 && av.mode !== 'reverse') {
    steer += (fb * (kCmd - e.kappa)) / kps
  }
  if (steer > 1) steer = 1
  if (steer < -1) steer = -1
  var prev = state.steer || 0
  var maxStep = rate * dt
  if (steer > prev + maxStep) steer = prev + maxStep
  if (steer < prev - maxStep) steer = prev - maxStep
  state.steer = steer
  // car2 treats exactly 0 as "no steering command" (wheel re-centres on its own)
  input.actions.steering_angle = Math.abs(steer) < 1e-4 ? 0 : steer
  av.cmdSteer = steer
  if (params.debugDraw !== false) {
    // white: commanded steering direction from the nose (4 m chord)
    var th = steer * kps * 4
    var nose = api.vec.offsetAlong(input.position, e.fwd, 2)
    var dir = [e.fwd[0] * Math.cos(th) + e.left[0] * Math.sin(th), 0, e.fwd[2] * Math.cos(th) + e.left[2] * Math.sin(th)]
    api.visualizeLine(nose, api.vec.offsetAlong(nose, dir, 4), '#ffffff')
  }
  return {}
}

// AV stack · CONTROL / longitudinal (speed PI with deadband feed-forward).
// The actuator has a static-friction deadband, so the controller adds `deadband` as feed-forward
// and PI-trims on top. Negative demand maps to the car's `brake` input (reverse thrust at standstill).
// params: kp, ki, deadband, maxThrottle, maxBrake, brakeGain
function transform(input, dt, params, state, api) {
  var av = input.av
  if (!av || !av.plan || !av.ego) return {}
  var e = av.ego
  var vDes = av.plan.vDesired || 0
  var kp = params.kp != null ? params.kp : 0.03
  var ki = params.ki != null ? params.ki : 0.02
  var db = params.deadband != null ? params.deadband : 0.36
  var maxThr = params.maxThrottle != null ? params.maxThrottle : 0.46
  var maxBrk = params.maxBrake != null ? params.maxBrake : 0.6
  var brakeGain = params.brakeGain != null ? params.brakeGain : 0.12
  // signed demand: positive = forward drive (throttle), negative = reverse drive (brake channel)
  var dir = vDes >= 0 ? 1 : -1
  var vAlong = e.speed * dir // speed in the demanded direction
  var vTarget = Math.abs(vDes)
  var err = vTarget - vAlong
  var thr = 0
  var brk = 0
  var drive = 0 // magnitude along the demanded direction
  var retard = 0 // magnitude opposing motion in the demanded direction
  if (vTarget < 0.05 && Math.abs(e.speed) < 0.3) {
    state.i = 0
  } else if (err > 0) {
    state.i = Math.min(0.1, (state.i || 0) + ki * err * dt)
    drive = Math.min(maxThr, db + kp * err + state.i)
  } else {
    state.i = Math.max(0, (state.i || 0) * 0.9)
    retard = Math.min(maxBrk, brakeGain * -err)
    if (vAlong < 0.3 && vTarget < 0.05) retard = 0
  }
  if (vTarget < 0.05 && Math.abs(e.speed) >= 0.3) {
    // demand zero but still rolling: brake against the current direction of travel
    var oppose = e.speed > 0 ? 1 : -1
    var b = Math.min(maxBrk, brakeGain * Math.abs(e.speed))
    if (oppose > 0) brk = b
    else thr = b
  } else if (dir > 0) {
    thr = drive
    brk = retard
  } else {
    brk = drive
    thr = retard
  }
  input.actions.throttle = thr
  input.actions.brake = brk
  av.cmd = { throttle: thr, brake: brk }
  return {}
}

// AV stack · SAFETY / autonomous emergency braking (independent monitor, own sensing).
// Runs after control and may only reduce throttle / add brake. Uses a smaller margin while the manoeuvre planner is driving (it already keeps swept clearance).
// debug draw: dark gold = AEB look-ahead, red = AEB triggered.
// params: aebDecel, aebMargin, aebHalfWidth
function transform(input, dt, params, state, api) {
  var av = input.av
  if (!av || !av.ego) return {}
  var e = av.ego
  if (e.speed < 0.8) {
    av.aeb = false
    return {}
  }
  var a = params.aebDecel || 7
  var margin = params.aebMargin != null ? params.aebMargin : 1.0
  if (av.mode === 'maneuver') margin = 0.2
  var hw = params.aebHalfWidth != null ? params.aebHalfWidth : 0.9
  var need = (e.speed * e.speed) / (2 * a) + margin
  var origin = api.vec.offsetAlong(input.position, e.fwd, 2.3)
  var hit = api.raycastSpread(origin, e.fwd, need + 1, hw, 5, { visualize: false })
  av.aeb = false
  var drawOn = params.debugDraw !== false
  if (drawOn) api.visualizeLine(origin, api.vec.offsetAlong(origin, e.fwd, need), '#b8860b')
  if (hit.hit && hit.distance < need) {
    if (drawOn) api.visualizeLine(origin, api.vec.offsetAlong(origin, e.fwd, hit.distance), '#ff0000')
    av.aeb = true
    input.actions.throttle = 0
    var b = Math.min(1, 0.3 + (need - hit.distance) / need)
    if (b > (input.actions.brake || 0)) input.actions.brake = b
    api.watch('av.aeb', hit.distance)
  }
  return {}
}

// AV stack · MISSION: position-only waypoint sequencer.
// Publishes `input.target` (current waypoint) and `av.mission` {index, waypoints, isFinal} for the whole stack.
// Position-only on purpose: a pass-through waypoint must never demand a heading (the stock targetPoseInput does).
// Edit `waypoints` as [[x, z], ...] (world metres, floor plane). The last waypoint is the stop point (mode 'stop')
// or the loop restarts (mode 'loop').
// params: waypoints, acceptRadius (default 9), mode ('stop' | 'loop'), speed (target speed hint)
function transform(input, dt, params, state, api) {
  var av = input.av
  var wps = params.waypoints
  if (!av || !wps || !wps.length) return {}
  if (state.i === undefined) state.i = 0
  var radius = params.acceptRadius != null ? params.acceptRadius : 9
  var loop = params.mode === 'loop'
  var pos = input.position
  var last = wps.length - 1
  var cur = wps[state.i]
  var d = Math.sqrt((pos[0] - cur[0]) * (pos[0] - cur[0]) + (pos[2] - cur[1]) * (pos[2] - cur[1]))
  if (d < radius) {
    if (state.i < last) state.i += 1
    else if (loop) state.i = 0
    cur = wps[state.i]
  }
  input.target = {
    pose: { position: [cur[0], 0, cur[1]], rotation: [0, 0, 0] },
    speed: params.speed != null ? params.speed : 10,
  }
  av.mission = { index: state.i, waypoints: wps, isFinal: !loop && state.i === last }
  return {}
}

// AV stack · SENSE / state estimation ("localization" layer).
// Publishes the ego state on the shared blackboard `input.av.ego` for all later stages.
// debug draw (params.debugDraw, default true): cyan = velocity vector.
// Owns the simulated clock (state.t) so no downstream stage needs a wall clock.
function transform(input, dt, params, state, api) {
  // fresh blackboard every frame (the input object is reused by the runtime)
  var av = (input.av = {})
  if (state.t === undefined) {
    state.t = 0
    state.speedF = 0
    state.prevSpeed = 0
    state.accelF = 0
  }
  state.t += dt
  var up = api.getUpVector(input.rotation)
  var fwd = api.vec.normalize(api.vec.projectOntoPlane(api.getForwardVector(input.rotation), up))
  var left = api.vec.normalize(api.vec.cross(up, fwd))
  var speed = api.vec.getForwardSpeed(input.velocity, fwd)
  var yawRate = api.vec.dot(input.angularVelocity, up)
  var a = dt > 1e-6 ? (speed - state.prevSpeed) / dt : 0
  state.prevSpeed = speed
  state.accelF += (a - state.accelF) * Math.min(1, dt * 8)
  state.speedF += (speed - state.speedF) * Math.min(1, dt * 20)
  av.ego = {
    t: state.t,
    dt: dt,
    pos: input.position,
    fwd: fwd,
    left: left,
    up: up,
    speed: speed,
    speedF: state.speedF,
    accel: state.accelF,
    yawRate: yawRate,
    kappa: Math.abs(speed) > 1.5 ? yawRate / speed : 0,
  }
  api.watch('av.speed', Math.round(speed * 10) / 10)
  if (params.debugDraw !== false) {
    // cyan: velocity vector
    api.visualizeLine(input.position, api.vec.add(input.position, api.vec.scale(input.velocity, 0.6)), '#00e5ff')
  }
  return {}
}

// AV stack · SENSE / perception.
// 360° range-scan ring (lidar-like, mounted at the vehicle centre, rays start on the hull)
// + obstacle memory ("local costmap") so the planners also know what is behind / beside.
// Publishes: av.scan {angles, ranges, range}, av.points [[x,z],...] (world), av.rearClear.
// debug draw (params.debugDraw, debugRayStride, debugMaxPoints): red = lidar hit rays, magenta ticks = costmap points.
// params: drivableArea [xmin, xmax, zmin, zmax] (virtual walls at the edge), edgeStep, rayCount, fovDeg, sensorRange, memoryTtl, memoryCell, vehicleWidth, vehicleLength
function transform(input, dt, params, state, api) {
  var av = input.av
  if (!av || !av.ego) return {}
  var e = av.ego
  var n = params.rayCount || 72
  var fov = ((params.fovDeg || 360) * Math.PI) / 180
  var range = params.sensorRange || 24
  var ttl = params.memoryTtl != null ? params.memoryTtl : 15
  var cell = params.memoryCell || 0.5
  var hl = (params.vehicleLength || 4) / 2 + 0.15
  var hw = (params.vehicleWidth || 2) / 2 + 0.15
  if (!state.mem) state.mem = {}
  var mem = state.mem
  var pos = input.position
  var full = fov >= 2 * Math.PI - 1e-3
  var angles = []
  var ranges = []
  var rearClear = params.rearRange || 8
  var draw = params.debugDraw !== false
  var rayStride = params.debugRayStride || 2
  for (var i = 0; i < n; i++) {
    var th = full ? -Math.PI + (2 * Math.PI * i) / n : n === 1 ? 0 : -fov / 2 + (fov * i) / (n - 1)
    var c = Math.cos(th)
    var s = Math.sin(th)
    var dir = [
      e.fwd[0] * c + e.left[0] * s,
      e.fwd[1] * c + e.left[1] * s,
      e.fwd[2] * c + e.left[2] * s,
    ]
    // start just outside the hull rectangle along this ray
    var tHull = Math.min(Math.abs(c) > 1e-6 ? hl / Math.abs(c) : 1e9, Math.abs(s) > 1e-6 ? hw / Math.abs(s) : 1e9)
    var origin = api.vec.offsetAlong(pos, dir, tHull)
    var r = api.raycast(origin, dir, range, { visualize: false })
    angles.push(th)
    if (r.hit) {
      if (draw && i % rayStride === 0) api.visualizeLine(origin, api.vec.offsetAlong(origin, dir, r.distance), '#ff4d4d')
      ranges.push(r.distance)
      var hx = origin[0] + dir[0] * r.distance
      var hz = origin[2] + dir[2] * r.distance
      mem[Math.round(hx / cell) + ',' + Math.round(hz / cell)] = { x: hx, z: hz, t: e.t }
      if (c < -0.9 && r.distance < rearClear) rearClear = r.distance
    } else {
      ranges.push(range)
    }
  }
  var pts = []
  // virtual walls along the edge of the drivable area (map prior): [xmin, xmax, zmin, zmax]
  var area = params.drivableArea
  if (area && area.length === 4) {
    var step = params.edgeStep || 1.2
    var reach = range
    var xs = Math.max(area[0], pos[0] - reach)
    var xe = Math.min(area[1], pos[0] + reach)
    var zs = Math.max(area[2], pos[2] - reach)
    var ze = Math.min(area[3], pos[2] + reach)
    var j
    if (pos[2] - area[2] < reach) for (j = xs; j <= xe; j += step) pts.push([j, area[2]])
    if (area[3] - pos[2] < reach) for (j = xs; j <= xe; j += step) pts.push([j, area[3]])
    if (pos[0] - area[0] < reach) for (j = zs; j <= ze; j += step) pts.push([area[0], j])
    if (area[1] - pos[0] < reach) for (j = zs; j <= ze; j += step) pts.push([area[1], j])
  }
  var keys = Object.keys(mem)
  for (var k = 0; k < keys.length; k++) {
    var m = mem[keys[k]]
    if (e.t - m.t > ttl) delete mem[keys[k]]
    else pts.push([m.x, m.z])
  }
  if (draw) {
    // magenta ticks: remembered obstacle points (costmap), nearest 60
    var near = pts
      .map(function (q) {
        var ddx = q[0] - pos[0]
        var ddz = q[1] - pos[2]
        return [ddx * ddx + ddz * ddz, q]
      })
      .sort(function (a, b) {
        return a[0] - b[0]
      })
      .slice(0, params.debugMaxPoints || 60)
    for (var pi = 0; pi < near.length; pi++) {
      var q2 = near[pi][1]
      api.visualizeLine([q2[0], pos[1] - 0.4, q2[1]], [q2[0], pos[1] + 0.5, q2[1]], '#ff00ff')
    }
  }
  av.scan = { angles: angles, ranges: ranges, range: range }
  av.points = pts
  av.rearClear = rearClear
  return {}
}

// AV stack · SENSE / mission overlay (debug only, no effect on driving).
// Draws the whole mission route: mint polyline + poles at every waypoint; the active target pole is yellow.
// Reads av.mission.waypoints (av-mission stage) or params.waypoints [[x, z], ...].
// params: waypoints, debugDraw
function transform(input, dt, params, state, api) {
  if (params.debugDraw === false) return {}
  var av = input.av
  var wps = (av && av.mission && av.mission.waypoints) || params.waypoints
  if (!wps || !wps.length) return {}
  var y = input.position[1]
  var cur = input.target && input.target.pose && input.target.pose.position
  for (var i = 0; i < wps.length; i++) {
    var w = wps[i]
    var active = cur && Math.abs(cur[0] - w[0]) < 0.05 && Math.abs(cur[2] - w[1]) < 0.05
    api.visualizeLine([w[0], y - 0.5, w[1]], [w[0], y + 5, w[1]], active ? '#ffcc00' : '#00ffcc')
    if (i > 0) api.visualizeLine([wps[i - 1][0], y - 0.4, wps[i - 1][1]], [w[0], y - 0.4, w[1]], '#7dffb0')
  }
  return {}
}

// AV stack · PLAN / route + manoeuvre planner (Hybrid-A* over forward/reverse arc primitives).
// Two jobs, one search:
//  1. ROUTE: every `routeInterval` s plans a collision-free route to the goal over the costmap and publishes
//     `av.carrot` (a point ~lookahead metres along the forward part of the route). The local planner chases
//     the carrot instead of the raw goal, so a goal behind an obstacle no longer produces endless orbits.
//  2. MANOEUVRE: if the route starts by reversing (or the car is stuck) it takes over (`av.override`): drives the
//     multi-point turn segment by segment, re-plans on drift/blockage/stall, and hands back as soon as the route
//     has a long forward run.
// Runs BEFORE the local motion planner. Simulated time only.
// debug draw: magenta = route / manoeuvre path (+ status mast while manoeuvring), orange = current segment end.
// params: maneuverSpeed, routeInterval, routeExpansions, lookahead, primitiveLength, maxExpansions,
//         gearSwitchPenalty, reversePenalty, maxReverseRun, planMargin, tightMargin, guardMargin, stallTime, stuckTime,
//         goalReach, handbackFree, goalTolerance, maxCurvature, vehicleWidth, vehicleLength
function transform(input, dt, params, state, api) {
  var av = input.av
  if (!av || !av.ego) return {}
  var e = av.ego
  var tgt = input.target && input.target.pose && input.target.pose.position
  if (!tgt) return {}
  var gxw = tgt[0]
  var gzw = tgt[2]
  var kmax = params.maxCurvature || 0.115
  var planMargin = params.planMargin != null ? params.planMargin : 0.4
  var tightMargin = params.tightMargin != null ? params.tightMargin : 0.1
  var guardMargin = params.guardMargin != null ? params.guardMargin : 0.15
  var ell = params.primitiveLength || 1.8
  var maxExpFull = params.maxExpansions || 4000
  var routeExp = params.routeExpansions || 1500
  var routeInterval = params.routeInterval != null ? params.routeInterval : 0.8
  var lookahead = params.lookahead != null ? params.lookahead : 14
  var gearPen = params.gearSwitchPenalty != null ? params.gearSwitchPenalty : 4
  var revPen = params.reversePenalty != null ? params.reversePenalty : 4
  var handback = params.handbackFree != null ? params.handbackFree : 10
  var vMan = params.maneuverSpeed != null ? params.maneuverSpeed : 3
  var stuckTime = params.stuckTime != null ? params.stuckTime : 1.5
  var holdTol = params.goalTolerance != null ? params.goalTolerance : 3.5
  // route ends inside the waypoint acceptance zone (not only at its centre)
  var reach = params.goalReach != null ? params.goalReach : 3.5
  var maxRevRun = params.maxReverseRun != null ? params.maxReverseRun : 8
  var termHeadW = params.exitHeadingWeight != null ? params.exitHeadingWeight : 0
  var ks = [-kmax, -kmax / 2, 0, kmax / 2, kmax]
  var pos = input.position
  // next waypoint after the current target: the route should arrive heading towards it
  var nextWp = null
  var wps = av.mission ? av.mission.waypoints : params.waypoints
  if (wps && wps.length) {
    for (var wi = 0; wi < wps.length - 1; wi++) {
      if (Math.abs(wps[wi][0] - gxw) < 0.05 && Math.abs(wps[wi][1] - gzw) < 0.05) {
        nextWp = wps[wi + 1]
        break
      }
    }
  }
  var goalDist = Math.sqrt((gxw - pos[0]) * (gxw - pos[0]) + (gzw - pos[2]) * (gzw - pos[2]))

  // spatial hash over costmap points + swept-footprint test (hl/hw are the active margins)
  function makeHit(pts, hlA, hwA) {
    var grid = {}
    for (var i = 0; i < pts.length; i++) {
      var key = Math.floor(pts[i][0] / 2) + ',' + Math.floor(pts[i][1] / 2)
      ;(grid[key] || (grid[key] = [])).push(pts[i])
    }
    var R = Math.sqrt(hlA * hlA + hwA * hwA)
    return function (x, z, fx, fz) {
      var x0 = Math.floor((x - R) / 2)
      var x1 = Math.floor((x + R) / 2)
      var z0 = Math.floor((z - R) / 2)
      var z1 = Math.floor((z + R) / 2)
      for (var cx = x0; cx <= x1; cx++) {
        for (var cz = z0; cz <= z1; cz++) {
          var list = grid[cx + ',' + cz]
          if (!list) continue
          for (var q = 0; q < list.length; q++) {
            var dx = list[q][0] - x
            var dz = list[q][1] - z
            var lx = dx * fx + dz * fz
            var ly = dx * fz - dz * fx
            if (lx > -hlA && lx < hlA && ly > -hwA && ly < hwA) return true
          }
        }
      }
      return false
    }
  }

  function search(sx, sz, sfx, sfz, gx, gz, pts, maxExp) {
    var hlS = (params.vehicleLength || 4) / 2 + planMargin
    var hwS = (params.vehicleWidth || 2) / 2 + planMargin
    var hit = makeHit(pts, hlS, hwS)
    // start already inside the comfort margin (drift, soft contact): re-plan with the tight margin so
    // the planner can still drive out of the margin band instead of finding every primitive blocked
    if (hit(sx, sz, sfx, sfz)) {
      hlS = (params.vehicleLength || 4) / 2 + tightMargin
      hwS = (params.vehicleWidth || 2) / 2 + tightMargin
      hit = makeHit(pts, hlS, hwS)
    }
    function dist(x, z) {
      var dx = gx - x
      var dz = gz - z
      return Math.sqrt(dx * dx + dz * dz)
    }
    // binary min-heap on f
    var heap = []
    function push(nd) {
      heap.push(nd)
      var c = heap.length - 1
      while (c > 0) {
        var p = (c - 1) >> 1
        if (heap[p].f <= heap[c].f) break
        var t = heap[p]
        heap[p] = heap[c]
        heap[c] = t
        c = p
      }
    }
    function pop() {
      var top = heap[0]
      var last = heap.pop()
      if (heap.length > 0) {
        heap[0] = last
        var c = 0
        for (;;) {
          var l = 2 * c + 1
          var r = l + 1
          var m = c
          if (l < heap.length && heap[l].f < heap[m].f) m = l
          if (r < heap.length && heap[r].f < heap[m].f) m = r
          if (m === c) break
          var t = heap[m]
          heap[m] = heap[c]
          heap[c] = t
          c = m
        }
      }
      return top
    }
    function skey(x, z, fx, fz, g) {
      var ih = Math.round((Math.atan2(fz, fx) / (2 * Math.PI)) * 36)
      if (ih < 0) ih += 36
      return Math.round(x / 0.6) + ',' + Math.round(z / 0.6) + ',' + (ih % 36) + ',' + g
    }
    var HW = 1.4
    var start = { x: sx, z: sz, fx: sfx, fz: sfz, g: 0, gear: 0, k: 0, parent: null, f: dist(sx, sz) * HW, d: 0 }
    push(start)
    var best = {}
    best[skey(sx, sz, sfx, sfz, 0)] = 0
    var bestNode = start
    var bestH = dist(sx, sz)
    var goalNode = null
    var expansions = 0
    while (heap.length > 0 && expansions < maxExp) {
      var cur = pop()
      var ck = skey(cur.x, cur.z, cur.fx, cur.fz, cur.gear)
      if (best[ck] !== undefined && cur.g > best[ck] + 1e-6) continue
      expansions++
      var h = dist(cur.x, cur.z)
      if (h < bestH) {
        bestH = h
        bestNode = cur
      }
      if (h < reach) {
        if (cur.terminal || !nextWp) {
          goalNode = cur
          break
        }
        // arrival cost: leave the goal zone heading towards the next waypoint
        var ndx = nextWp[0] - cur.x
        var ndz = nextWp[1] - cur.z
        var nl = Math.sqrt(ndx * ndx + ndz * ndz) || 1
        var cosA = Math.max(-1, Math.min(1, (cur.fx * ndx + cur.fz * ndz) / nl))
        var termG = cur.g + termHeadW * Math.acos(cosA)
        push({ x: cur.x, z: cur.z, fx: cur.fx, fz: cur.fz, g: termG, gear: cur.gear, k: cur.k, parent: cur, terminal: true, f: termG })
        continue
      }
      for (var gi = 0; gi < 2; gi++) {
        var gear = gi === 0 ? 1 : -1
        for (var ki = 0; ki < ks.length; ki++) {
          var k = ks[ki]
          var lx = cur.fz
          var lz = -cur.fx
          var revRun = gear < 0 ? (cur.gear < 0 ? cur.revRun || 0 : 0) + ell : 0
          if (revRun > maxRevRun) continue
          var ok = true
          var nx = cur.x
          var nz = cur.z
          var nfx = cur.fx
          var nfz = cur.fz
          for (var sIdx = 1; sIdx <= 4; sIdx++) {
            var d = (gear * ell * sIdx) / 4
            var th = k * d
            var ddx
            var ddy
            if (Math.abs(k) < 1e-6) {
              ddx = d
              ddy = 0
            } else {
              ddx = Math.sin(th) / k
              ddy = (1 - Math.cos(th)) / k
            }
            nx = cur.x + cur.fx * ddx + lx * ddy
            nz = cur.z + cur.fz * ddx + lz * ddy
            var ct = Math.cos(th)
            var st = Math.sin(th)
            nfx = cur.fx * ct + lx * st
            nfz = cur.fz * ct + lz * st
            if (hit(nx, nz, nfx, nfz)) {
              ok = false
              break
            }
          }
          if (!ok) continue
          var step = ell * (gear < 0 ? revPen : 1) + (Math.abs(k) / kmax) * 0.4 * ell
          if (cur.gear !== 0 && cur.gear !== gear) step += gearPen
          if (cur.gear !== 0 && cur.k !== k) step += 0.3
          var g2 = cur.g + step
          var nk = skey(nx, nz, nfx, nfz, gear)
          if (best[nk] !== undefined && best[nk] <= g2) continue
          best[nk] = g2
          push({ x: nx, z: nz, fx: nfx, fz: nfz, g: g2, gear: gear, k: k, revRun: revRun, parent: cur, f: g2 + dist(nx, nz) * HW })
        }
      }
    }
    var end = goalNode || bestNode
    if (end.terminal) end = end.parent
    var segs = []
    for (var nd = end; nd && nd.parent; nd = nd.parent) {
      var last = segs[0]
      if (last && last.g === nd.gear && last.k === nd.k) {
        last.len += ell
      } else {
        segs.unshift({ g: nd.gear, k: nd.k, len: ell, end: null })
      }
    }
    // expected pose at the end of every segment (walk the chain again, front to back)
    var chain = []
    for (var cn = end; cn; cn = cn.parent) chain.unshift(cn)
    var si = -1
    var prevG = null
    var prevK = null
    for (var ci = 1; ci < chain.length; ci++) {
      var nn = chain[ci]
      if (si < 0 || nn.gear !== prevG || nn.k !== prevK) {
        si++
        prevG = nn.gear
        prevK = nn.k
      }
      segs[si].end = { x: nn.x, z: nn.z, fx: nn.fx, fz: nn.fz }
    }
    var pathPts = []
    for (var pj = 0; pj < chain.length; pj++) pathPts.push([chain[pj].x, chain[pj].z])
    var nodes = []
    for (var nj = 0; nj < chain.length; nj++) nodes.push({ x: chain[nj].x, z: chain[nj].z, g: chain[nj].gear })
    return { segs: segs, reached: !!goalNode, expansions: expansions, hRemaining: bestH, path: pathPts, nodes: nodes }
  }

  function begin(res) {
    state.segs = res.segs
    state.idx = 0
    state.segStart = null
    state.prevGear = 0
    state.path = res.path
  }
  function deviates(seg) {
    if (!seg || !seg.end) return false
    var ex = pos[0] - seg.end.x
    var ez = pos[2] - seg.end.z
    var dot = e.fwd[0] * seg.end.fx + e.fwd[2] * seg.end.fz
    return Math.sqrt(ex * ex + ez * ez) > 0.9 || dot < 0.97
  }
  function plan(maxE) {
    return search(pos[0], pos[2], e.fwd[0], e.fwd[2], gxw, gzw, av.points || [], maxE)
  }
  // route summary: first gear, length of the leading forward run, carrot point
  function summarize(res) {
    var nodes = res.nodes
    var firstGear = nodes.length > 1 ? nodes[1].g : 1
    var run = 0
    var carrot = null
    if (firstGear === 1) {
      var want = Math.min(lookahead, 6 + 1.0 * Math.max(0, e.speedF))
      var acc = 0
      for (var i = 1; i < nodes.length && nodes[i].g === 1; i++) {
        var dx = nodes[i].x - nodes[i - 1].x
        var dz = nodes[i].z - nodes[i - 1].z
        acc += Math.sqrt(dx * dx + dz * dz)
        carrot = [nodes[i].x, nodes[i].z]
        if (acc >= want) break
      }
      run = acc
      for (var j = i; j < nodes.length && nodes[j].g === 1; j++) {
        var ddx = nodes[j].x - nodes[j - 1].x
        var ddz = nodes[j].z - nodes[j - 1].z
        run += Math.sqrt(ddx * ddx + ddz * ddz)
      }
    }
    // speed limit from the bends ahead on the route: corner speed sqrt(aLat / kappa), reachable by braking
    var aLat = params.maxLatAccel || 7
    var aBrk = params.comfortDecel || 5
    var vLimit = Infinity
    var dAhead = 0
    for (var si = 0; si < res.segs.length && dAhead < 40 && res.segs[si].g > 0; si++) {
      var kk = Math.abs(res.segs[si].k)
      if (kk > 0.04) {
        var vi = Math.sqrt(aLat / kk)
        var allowed = Math.sqrt(vi * vi + 2 * aBrk * dAhead)
        if (allowed < vLimit) vLimit = allowed
      }
      dAhead += res.segs[si].len
    }
    return { firstGear: firstGear, run: run, carrot: carrot, reached: res.reached, nodes: nodes, path: res.path, vLimit: vLimit }
  }

  // stuck watchdog (own, independent of the local planner)
  if (state.stuckT === undefined) state.stuckT = 0
  if (!state.active && Math.abs(e.speed) < 0.25 && goalDist > holdTol) state.stuckT += dt
  else state.stuckT = 0

  if (!state.active) {
    if (state.route === undefined || e.t - state.routeT >= routeInterval) {
      state.route = summarize(plan(routeExp))
      state.routeT = e.t
      state.revFresh = true
      state.routes = (state.routes || 0) + 1
    }
    var rt = state.route
    // hysteresis: a reverse-first route must be confirmed by two consecutive plans before the car manoeuvres
    state.revVotes = rt.firstGear === -1 ? (state.revFresh ? (state.revVotes || 0) + 1 : state.revVotes || 1) : 0
    state.revFresh = false
    var wantManeuver = (rt.firstGear === -1 && (state.revVotes >= 2 || Math.abs(e.speed) < 0.3) && Math.abs(e.speed) < 1.5) || state.stuckT > stuckTime
    if (wantManeuver && goalDist > holdTol) {
      var res = plan(maxExpFull)
      if (res.segs.length > 0) {
        state.active = true
        state.replans = (state.replans || 0) + 1
        state.stuckT = 0
        begin(res)
      }
    }
    if (!state.active) {
      if (rt.carrot) av.carrot = rt.carrot
      av.route = { firstGear: rt.firstGear, run: rt.run, reached: rt.reached, vLimit: rt.vLimit }
      if (params.debugDraw !== false) {
        var y0 = pos[1]
        for (var di = 2; di < rt.path.length; di += 2) {
          api.visualizeLine([rt.path[di - 2][0], y0, rt.path[di - 2][1]], [rt.path[di][0], y0, rt.path[di][1]], '#ff44ff')
        }
      }
      api.watch('av.route', 'gear ' + rt.firstGear + ' run ' + rt.run.toFixed(1) + (rt.reached ? ' goal' : ' partial'))
      return {}
    }
  }

  // --- execute manoeuvre ---
  var cur = state.segs[state.idx]
  if (state.segStart === null) {
    // a gear change must come to rest first so the odometer does not count coasting
    if (cur.g === state.prevGear || Math.abs(e.speed) < 0.4) state.segStart = [pos[0], pos[2]]
  }
  var travelled = 0
  if (state.segStart) {
    var dx = pos[0] - state.segStart[0]
    var dz = pos[2] - state.segStart[1]
    travelled = Math.sqrt(dx * dx + dz * dz)
  }
  // --- execution guard: re-plan when the real pose makes the rest of the segment collide, or when stalled ---
  if (state.segStart !== null) {
    var guardL = (params.vehicleLength || 4) / 2 + guardMargin
    var guardW = (params.vehicleWidth || 2) / 2 + guardMargin
    var gHit = makeHit(av.points || [], guardL, guardW)
    var lx0 = e.left[0]
    var lz0 = e.left[2]
    var look = Math.min(2.0, Math.max(0, cur.len - travelled))
    var blockedAhead = false
    for (var gd = 0.5; gd <= look + 1e-6 && !blockedAhead; gd += 0.5) {
      var gdd = cur.g * gd
      var gth = cur.k * gdd
      var gx2 = Math.abs(cur.k) < 1e-6 ? gdd : Math.sin(gth) / cur.k
      var gy2 = Math.abs(cur.k) < 1e-6 ? 0 : (1 - Math.cos(gth)) / cur.k
      var px = pos[0] + e.fwd[0] * gx2 + lx0 * gy2
      var pz = pos[2] + e.fwd[2] * gx2 + lz0 * gy2
      var pfx = e.fwd[0] * Math.cos(gth) + lx0 * Math.sin(gth)
      var pfz = e.fwd[2] * Math.cos(gth) + lz0 * Math.sin(gth)
      if (gHit(px, pz, pfx, pfz)) blockedAhead = true
    }
    state.stallT = Math.abs(e.speed) < 0.15 ? (state.stallT || 0) + dt : 0
    var stallTime = params.stallTime != null ? params.stallTime : 1.2
    if ((blockedAhead || state.stallT > stallTime) && e.t - (state.lastReplanT || -9) > 0.6) {
      var fix = plan(maxExpFull)
      state.lastReplanT = e.t
      state.stallT = 0
      state.replans++
      if (fix.segs.length > 0) {
        begin(fix)
        state.prevGear = cur.g
        cur = state.segs[0]
        travelled = 0
      }
    }
  }
  // hand back once the rest of the plan starts with a long forward run
  var fwdRun = 0
  if (state.idx > 0 || state.segs.length === 1) {
    for (var si = state.idx; si < state.segs.length && state.segs[si].g > 0; si++) fwdRun += state.segs[si].len
    fwdRun -= travelled
  }
  var aheadFree = false
  if (fwdRun >= handback && cur.g > 0) {
    // the car must really have room ahead on its own heading, not just a plan that will get there
    var aHit = makeHit(av.points || [], (params.vehicleLength || 4) / 2 + planMargin, (params.vehicleWidth || 2) / 2 + planMargin)
    aheadFree = true
    for (var ad = 0; ad <= handback && aheadFree; ad += 1) {
      // along the current segment's arc (what the local planner would also pick), not just straight on
      var ath = cur.k * ad
      var ax = Math.abs(cur.k) < 1e-6 ? ad : Math.sin(ath) / cur.k
      var ay = Math.abs(cur.k) < 1e-6 ? 0 : (1 - Math.cos(ath)) / cur.k
      var apx = pos[0] + e.fwd[0] * ax + e.left[0] * ay
      var apz = pos[2] + e.fwd[2] * ax + e.left[2] * ay
      if (aHit(apx, apz, e.fwd[0] * Math.cos(ath) + e.left[0] * Math.sin(ath), e.fwd[2] * Math.cos(ath) + e.left[2] * Math.sin(ath))) aheadFree = false
    }
  }
  if (aheadFree) {
    state.active = false
    state.route = undefined
    return {}
  }
  var finished = state.segStart !== null && travelled >= cur.len - 0.25
  if (finished) {
    state.prevGear = cur.g
    if (state.idx + 1 >= state.segs.length || deviates(cur)) {
      var again = plan(maxExpFull)
      state.replans++
      if (again.segs.length === 0 || state.idx + 1 >= state.segs.length) {
        state.active = false
        state.route = undefined
        if (again.segs.length === 0) return {}
      }
      if (again.segs.length > 0 && state.active) {
        begin(again)
        state.prevGear = cur.g
      }
    } else {
      state.idx++
      state.segStart = null
    }
    if (!state.active) return {}
    cur = state.segs[state.idx]
    travelled = 0
  }
  if (params.debugDraw !== false && state.path) {
    var py = pos[1]
    for (var pi = 2; pi < state.path.length; pi += 2) {
      api.visualizeLine([state.path[pi - 2][0], py, state.path[pi - 2][1]], [state.path[pi][0], py, state.path[pi][1]], '#ff44ff')
    }
    if (cur.end) api.visualizeLine(pos, [cur.end.x, py, cur.end.z], '#ff8800')
    api.visualizeLine([pos[0], py + 1.2, pos[2]], [pos[0], py + 4, pos[2]], '#ff44ff')
  }
  var remain = state.segStart ? Math.max(0, cur.len - travelled) : cur.len
  var vMax = Math.min(vMan, 0.9 + Math.sqrt(2 * 3 * remain))
  var wrongWay = state.segStart === null || cur.g * e.speed < -0.35
  av.override = { kappa: cur.k, vDesired: wrongWay ? 0 : cur.g * vMax }
  av.mode = 'maneuver'
  api.watch('av.maneuver', 'seg ' + state.idx + '/' + state.segs.length + ' g' + cur.g + ' k' + cur.k.toFixed(3) + ' replans ' + state.replans)
  return {}
}

// AV stack · PLAN / local motion planner (sampling-based, receding horizon).
// Candidate paths = constant-curvature turn (limited turn angle) followed by a straight, so a path can
// swing around an obstacle and then run alongside it. Each path is swept with the vehicle footprint
// (margin grows with speed) against the costmap. Cost = progress to goal, heading, required stopping
// length, clearance, smoothness. Publishes av.plan {kappa, free, freeSoft, clearance, blocked, horizon}.
// debug draw: yellow = line to goal / route carrot, dark blue = candidate fan, green = chosen path, orange = where it would hit.
// params: vehicleWidth, vehicleLength, safetyMargin, marginSpeedGain, softMargin, maxCurvature, arcCount,
//         horizonMin, horizonGain, horizonMax, comfortDecel, wProgress, wHeading, wRequired, wFree, wSoft,
//         wSmooth, wTurn, minFree, rearIgnore, debugDraw
function transform(input, dt, params, state, api) {
  var av = input.av
  if (!av || !av.ego) return {}
  var e = av.ego
  var tgt = input.target && input.target.pose && input.target.pose.position
  if (!tgt) {
    av.plan = { kappa: 0, free: 0, freeSoft: 0, clearance: 0, blocked: false, horizon: 0, noGoal: true }
    return {}
  }
  var pos = input.position
  var tdx = tgt[0] - pos[0]
  var tdz = tgt[2] - pos[2]
  av.goal = { x: tgt[0], z: tgt[2], dist: Math.sqrt(tdx * tdx + tdz * tdz) }
  // manoeuvre planner owns the controls (multi-point turn): pass its command through
  if (av.override) {
    av.plan = { kappa: av.override.kappa, vDesired: av.override.vDesired, free: 99, freeSoft: 99, clearance: 9, blocked: false, horizon: 0, override: true }
    return {}
  }
  // chase the route's carrot (global plan) when there is one, else the raw goal
  var aim = av.carrot ? [av.carrot[0], 0, av.carrot[1]] : tgt
  var gdx = aim[0] - pos[0]
  var gdz = aim[2] - pos[2]
  var gx = gdx * e.fwd[0] + gdz * e.fwd[2]
  var gy = gdx * e.left[0] + gdz * e.left[2]
  var goalDist = Math.sqrt(gx * gx + gy * gy)

  var v = Math.max(0, e.speedF)
  var margin = (params.safetyMargin != null ? params.safetyMargin : 0.5) + (params.marginSpeedGain != null ? params.marginSpeedGain : 0.05) * v
  var soft = params.softMargin != null ? params.softMargin : 1.1
  var halfW = (params.vehicleWidth || 2) / 2 + margin
  var halfL = (params.vehicleLength || 4) / 2 + margin
  var kmax = params.maxCurvature || 0.115
  var count = params.arcCount || 31
  var hMin = params.horizonMin != null ? params.horizonMin : 10
  var hMax = params.horizonMax != null ? params.horizonMax : 26
  var H = Math.min(hMax, hMin + (params.horizonGain != null ? params.horizonGain : 1.2) * v)
  var aBrake = params.comfortDecel || 5
  var Lreq = Math.min(H, (v * v) / (2 * aBrake) + 5)
  var wProg = params.wProgress != null ? params.wProgress : 1.0
  var wHead = params.wHeading != null ? params.wHeading : 2.0
  var wReq = params.wRequired != null ? params.wRequired : 60
  var wFree = params.wFree != null ? params.wFree : 10
  var wSoft = params.wSoft != null ? params.wSoft : 8
  var wSmooth = params.wSmooth != null ? params.wSmooth : 2.5
  var wTurn = params.wTurn != null ? params.wTurn : 1.5
  var minFree = params.minFree != null ? params.minFree : 4.5
  var ds = 0.75
  var turnAngles = [0.5, 1.15]

  // costmap into ego frame
  var pts = av.points || []
  var ox = []
  var oy = []
  for (var i = 0; i < pts.length; i++) {
    var dx = pts[i][0] - pos[0]
    var dz = pts[i][1] - pos[2]
    var px = dx * e.fwd[0] + dz * e.fwd[2]
    var py = dx * e.left[0] + dz * e.left[2]
    if (px > -halfL - soft - 3 && px < H + halfL + soft + 3 && py > -H - 4 && py < H + 4) {
      ox.push(px)
      oy.push(py)
    }
  }

  // pose along a path: turn at `kappa` for `turnLen`, then straight
  function poseAt(kappa, turnLen, s, out) {
    var sa = s < turnLen ? s : turnLen
    var th = kappa * sa
    var x
    var y
    if (Math.abs(kappa) < 1e-6) {
      x = sa
      y = 0
    } else {
      x = Math.sin(th) / kappa
      y = (1 - Math.cos(th)) / kappa
    }
    if (s > turnLen) {
      x += Math.cos(th) * (s - turnLen)
      y += Math.sin(th) * (s - turnLen)
    }
    out.x = x
    out.y = y
    out.th = th
  }
  var P = { x: 0, y: 0, th: 0 }

  // forward paths only sweep the front of the footprint: an obstacle already behind/at the tail (touching
  // start pose) must not veto driving away from it
  var rearIgnore = params.rearIgnore != null ? params.rearIgnore : 1.4
  function freeLength(kappa, turnLen, hw, hl) {
    var hlRear = Math.max(0.3, hl - rearIgnore)
    for (var s = 0; s <= H; s += ds) {
      poseAt(kappa, turnLen, s, P)
      var ct = Math.cos(P.th)
      var st = Math.sin(P.th)
      for (var q = 0; q < ox.length; q++) {
        var rx = ox[q] - P.x
        var ry = oy[q] - P.y
        var lx = ct * rx + st * ry
        var ly = -st * rx + ct * ry
        if (lx > -hlRear && lx < hl && ly > -hw && ly < hw) return Math.max(0, s - ds)
      }
    }
    return H
  }

  var prev = state.prevKappa || 0
  var prevTurn = state.prevTurn || 0
  var best = null
  var bestCost = Infinity
  var bestHard = 0
  var bestSoft = 0
  var bestTurnLen = 0
  var cand = []
  for (var a = 0; a < count; a++) {
    var kappa = count === 1 ? 0 : -kmax + (2 * kmax * a) / (count - 1)
    for (var ti = 0; ti < turnAngles.length; ti++) {
      if (Math.abs(kappa) < 1e-6 && ti > 0) continue
      var turnLen = Math.abs(kappa) < 1e-6 ? H : Math.min(H, turnAngles[ti] / Math.abs(kappa))
      var fHard = freeLength(kappa, turnLen, halfW, halfL)
      var fSoft = freeLength(kappa, turnLen, halfW + soft - margin, halfL + soft - margin)
      var L = fHard
      poseAt(kappa, turnLen, L, P)
      var gdEnd = Math.sqrt((gx - P.x) * (gx - P.x) + (gy - P.y) * (gy - P.y))
      var progress = goalDist - gdEnd
      var herr = Math.atan2(gy - P.y, gx - P.x) - P.th
      while (herr > Math.PI) herr -= 2 * Math.PI
      while (herr < -Math.PI) herr += 2 * Math.PI
      var cost =
        -wProg * progress +
        wHead * Math.abs(herr) +
        wReq * Math.max(0, 1 - L / Lreq) +
        wFree * (1 - L / H) +
        wSoft * (1 - Math.min(fSoft, H) / H) +
        wSmooth * (Math.abs(kappa - prev) / kmax) +
        wTurn * Math.abs(kappa * turnLen)
      if (cost < bestCost) {
        bestCost = cost
        best = kappa
        bestHard = fHard
        bestSoft = fSoft
        bestTurnLen = turnLen
      }
      if (params.debugDraw !== false && a % 8 === 0 && ti === 0) cand.push([kappa, turnLen, fHard])
    }
  }
  state.prevKappa = best

  // lateral clearance of the chosen path over the distance that matters (beyond the hard margin)
  var clearance = 0
  var margins = [0.5, 1.0, 1.5, 2.5]
  var needLen = Math.min(bestHard, Lreq)
  for (var mi = 0; mi < margins.length; mi++) {
    var fm = freeLength(best, bestTurnLen, halfW + margins[mi], halfL + margins[mi])
    if (fm >= needLen - 1e-6) clearance = margins[mi]
    else break
  }

  av.plan = {
    kappa: best,
    free: bestHard,
    freeSoft: bestSoft,
    clearance: clearance,
    margin: margin,
    blocked: bestHard < minFree,
    horizon: H,
    required: Lreq,
    cost: bestCost,
  }
  api.watch('av.plan.kappa', Math.round(best * 1000) / 1000)
  api.watch('av.plan.free', Math.round(bestHard * 10) / 10 + ' clr ' + clearance)

  if (params.debugDraw !== false) {
    var y0 = pos[1]
    var W = { x: 0, y: 0, th: 0 }
    function world(x, y) {
      return [pos[0] + e.fwd[0] * x + e.left[0] * y, y0, pos[2] + e.fwd[2] * x + e.left[2] * y]
    }
    function drawPath(kk, tl, len, color, step) {
      var prevW = null
      for (var s = 0; s <= len + 1e-6; s += step) {
        poseAt(kk, tl, s, W)
        var wp = world(W.x, W.y)
        if (prevW) api.visualizeLine(prevW, wp, color)
        prevW = wp
      }
    }
    api.visualizeLine(pos, [aim[0], y0, aim[2]], '#ffcc00')
    for (var ci = 0; ci < cand.length; ci++) drawPath(cand[ci][0], cand[ci][1], cand[ci][2], '#3a5a9a', Math.max(4, cand[ci][2] / 3))
    drawPath(best, bestTurnLen, bestHard, '#22dd66', 2.5)
    if (bestHard < H) drawPath(best, bestTurnLen, Math.min(H, bestHard + 3), '#ff8800', 3)
  }
  return {}
}

// AV stack · PLAN / speed planner.
// v_des = min(cruise, stopping-distance limit, clearance limit, route bends ahead, lateral-acceleration limit, goal approach).
// Clearance limit: lots of room beside obstacles → full speed; squeezing past → slow.
// Goal approach only slows for the FINAL waypoint (av.mission, else params.waypoints; otherwise every goal is final).
// Publishes av.plan.vDesired / av.plan.vLimit.
// params: cruiseSpeed, comfortDecel, maxLatAccel, stopMargin, crawlSpeed, goalTolerance, clearSpeedBase,
//         clearSpeedGain, waypoints
function transform(input, dt, params, state, api) {
  var av = input.av
  if (!av || !av.plan) return {}
  var plan = av.plan
  if (plan.override) return {}
  var cruise = params.cruiseSpeed != null ? params.cruiseSpeed : 10
  var aBrake = params.comfortDecel || 5
  var aLat = params.maxLatAccel || 7
  var stopMargin = params.stopMargin != null ? params.stopMargin : 1.2
  var crawl = params.crawlSpeed != null ? params.crawlSpeed : 2
  var base = params.clearSpeedBase != null ? params.clearSpeedBase : 5
  var gain = params.clearSpeedGain != null ? params.clearSpeedGain : 3.5
  var limit = 'cruise'
  var v = cruise
  var vFree = Math.sqrt(2 * aBrake * Math.max(0, plan.free - stopMargin))
  if (vFree < v) {
    v = vFree
    limit = 'free'
  }
  // lateral gap to the nearest obstacle surface along the chosen path (safety margin + measured extra room)
  var vClear = base + gain * Math.max(0, (plan.margin || 0.5) + (plan.clearance || 0) - 0.3)
  if (vClear < v) {
    v = vClear
    limit = 'clearance'
  }
  // bends ahead on the global route (corner speed, reachable by braking)
  if (av.route && av.route.vLimit < v) {
    v = Math.max(av.route.vLimit, crawl)
    limit = 'route'
  }
  var k = Math.abs(plan.kappa)
  if (k > 1e-4) {
    var vCurve = Math.sqrt(aLat / k)
    if (vCurve < v) {
      v = vCurve
      limit = 'curve'
    }
  }
  if (av.goal) {
    var tol = params.goalTolerance != null ? params.goalTolerance : 3.5
    var wps = params.waypoints
    var isFinal = true
    if (av.mission) {
      isFinal = av.mission.isFinal
    } else if (wps && wps.length) {
      var last = wps[wps.length - 1]
      isFinal = Math.abs(av.goal.x - last[0]) < 0.05 && Math.abs(av.goal.z - last[1]) < 0.05
    }
    if (isFinal) {
      var vGoal = Math.sqrt(2 * aBrake * Math.max(0, av.goal.dist - tol))
      if (vGoal < v) {
        v = Math.max(vGoal, crawl)
        limit = 'goal'
      }
    }
  }
  if (!plan.blocked && v < crawl) v = crawl
  plan.vDesired = v
  plan.vLimit = limit
  api.watch('av.vLimit', limit + ' ' + v.toFixed(1))
  return {}
}

// AV stack · PLAN / behaviour supervisor.
// Watches planner health and flags `av.needManeuver` when the local planner is blocked
// or the vehicle is stuck; holds at the final goal. Sets av.mode ('drive' | 'hold').
// debug draw: vertical mast above the car = status (green drive, orange needs manoeuvre, white hold).
// Simulated time only. params: stuckTime, blockedTime, holdAtGoal, goalTolerance
function transform(input, dt, params, state, api) {
  var av = input.av
  if (!av || !av.plan || !av.ego) return {}
  var e = av.ego
  var plan = av.plan
  if (state.stuckT === undefined) {
    state.stuckT = 0
    state.blockedT = 0
  }
  var stuckTime = params.stuckTime != null ? params.stuckTime : 1.5
  var blockedTime = params.blockedTime != null ? params.blockedTime : 0.4
  var wantsMove = (plan.vDesired || 0) > 0.8
  if (wantsMove && Math.abs(e.speed) < 0.25) state.stuckT += dt
  else state.stuckT = 0
  if (plan.blocked && Math.abs(e.speed) < 1.2) state.blockedT += dt
  else state.blockedT = 0
  av.needManeuver = state.blockedT > blockedTime || state.stuckT > stuckTime
  av.mode = av.override ? 'maneuver' : 'drive'
  var tol = params.goalTolerance != null ? params.goalTolerance : 3.5
  var finalGoal = !av.mission || av.mission.isFinal
  if (params.holdAtGoal !== false && finalGoal && av.goal && av.goal.dist < tol) {
    av.mode = 'hold'
    plan.override = false
    plan.vDesired = 0
    plan.kappa = 0
  }
  if (params.debugDraw !== false) {
    // status mast above the car: green drive, orange manoeuvre requested, white hold
    var c = av.mode === 'hold' ? '#ffffff' : av.needManeuver ? '#ff8800' : '#00ff66'
    api.visualizeLine([e.pos[0], e.pos[1] + 1.2, e.pos[2]], [e.pos[0], e.pos[1] + 4, e.pos[2]], c)
  }
  return {}
}

// AV stack · CONTROL / lateral (curvature tracking).
// steering = feed-forward(kappa_plan / kappaPerSteer) + P feedback on measured curvature,
// with a steering-rate limiter (comfort / actuator model).
// debug draw: white = commanded steering direction.
// params: kappaPerSteer, fbGain, steerRate
function transform(input, dt, params, state, api) {
  var av = input.av
  if (!av || !av.plan || !av.ego) return {}
  var e = av.ego
  var kps = params.kappaPerSteer || 0.12
  var fb = params.fbGain != null ? params.fbGain : 0.35
  var rate = params.steerRate != null ? params.steerRate : 4
  var kCmd = av.plan.kappa
  var steer = kCmd / kps
  if (Math.abs(e.speed) > 2 && av.mode !== 'reverse') {
    steer += (fb * (kCmd - e.kappa)) / kps
  }
  if (steer > 1) steer = 1
  if (steer < -1) steer = -1
  var prev = state.steer || 0
  var maxStep = rate * dt
  if (steer > prev + maxStep) steer = prev + maxStep
  if (steer < prev - maxStep) steer = prev - maxStep
  state.steer = steer
  // car2 treats exactly 0 as "no steering command" (wheel re-centres on its own)
  input.actions.steering_angle = Math.abs(steer) < 1e-4 ? 0 : steer
  av.cmdSteer = steer
  if (params.debugDraw !== false) {
    // white: commanded steering direction from the nose (4 m chord)
    var th = steer * kps * 4
    var nose = api.vec.offsetAlong(input.position, e.fwd, 2)
    var dir = [e.fwd[0] * Math.cos(th) + e.left[0] * Math.sin(th), 0, e.fwd[2] * Math.cos(th) + e.left[2] * Math.sin(th)]
    api.visualizeLine(nose, api.vec.offsetAlong(nose, dir, 4), '#ffffff')
  }
  return {}
}

// AV stack · CONTROL / longitudinal (speed PI with deadband feed-forward).
// The actuator has a static-friction deadband, so the controller adds `deadband` as feed-forward
// and PI-trims on top. Negative demand maps to the car's `brake` input (reverse thrust at standstill).
// params: kp, ki, deadband, maxThrottle, maxBrake, brakeGain
function transform(input, dt, params, state, api) {
  var av = input.av
  if (!av || !av.plan || !av.ego) return {}
  var e = av.ego
  var vDes = av.plan.vDesired || 0
  var kp = params.kp != null ? params.kp : 0.03
  var ki = params.ki != null ? params.ki : 0.02
  var db = params.deadband != null ? params.deadband : 0.36
  var maxThr = params.maxThrottle != null ? params.maxThrottle : 0.46
  var maxBrk = params.maxBrake != null ? params.maxBrake : 0.6
  var brakeGain = params.brakeGain != null ? params.brakeGain : 0.12
  // signed demand: positive = forward drive (throttle), negative = reverse drive (brake channel)
  var dir = vDes >= 0 ? 1 : -1
  var vAlong = e.speed * dir // speed in the demanded direction
  var vTarget = Math.abs(vDes)
  var err = vTarget - vAlong
  var thr = 0
  var brk = 0
  var drive = 0 // magnitude along the demanded direction
  var retard = 0 // magnitude opposing motion in the demanded direction
  if (vTarget < 0.05 && Math.abs(e.speed) < 0.3) {
    state.i = 0
  } else if (err > 0) {
    state.i = Math.min(0.1, (state.i || 0) + ki * err * dt)
    drive = Math.min(maxThr, db + kp * err + state.i)
  } else {
    state.i = Math.max(0, (state.i || 0) * 0.9)
    retard = Math.min(maxBrk, brakeGain * -err)
    if (vAlong < 0.3 && vTarget < 0.05) retard = 0
  }
  if (vTarget < 0.05 && Math.abs(e.speed) >= 0.3) {
    // demand zero but still rolling: brake against the current direction of travel
    var oppose = e.speed > 0 ? 1 : -1
    var b = Math.min(maxBrk, brakeGain * Math.abs(e.speed))
    if (oppose > 0) brk = b
    else thr = b
  } else if (dir > 0) {
    thr = drive
    brk = retard
  } else {
    brk = drive
    thr = retard
  }
  input.actions.throttle = thr
  input.actions.brake = brk
  av.cmd = { throttle: thr, brake: brk }
  return {}
}

// AV stack · SAFETY / autonomous emergency braking (independent monitor, own sensing).
// Runs after control and may only reduce throttle / add brake. Uses a smaller margin while the manoeuvre planner is driving (it already keeps swept clearance).
// debug draw: dark gold = AEB look-ahead, red = AEB triggered.
// params: aebDecel, aebMargin, aebHalfWidth
function transform(input, dt, params, state, api) {
  var av = input.av
  if (!av || !av.ego) return {}
  var e = av.ego
  if (e.speed < 0.8) {
    av.aeb = false
    return {}
  }
  var a = params.aebDecel || 7
  var margin = params.aebMargin != null ? params.aebMargin : 1.0
  if (av.mode === 'maneuver') margin = 0.2
  var hw = params.aebHalfWidth != null ? params.aebHalfWidth : 0.9
  var need = (e.speed * e.speed) / (2 * a) + margin
  var origin = api.vec.offsetAlong(input.position, e.fwd, 2.3)
  var hit = api.raycastSpread(origin, e.fwd, need + 1, hw, 5, { visualize: false })
  av.aeb = false
  var drawOn = params.debugDraw !== false
  if (drawOn) api.visualizeLine(origin, api.vec.offsetAlong(origin, e.fwd, need), '#b8860b')
  if (hit.hit && hit.distance < need) {
    if (drawOn) api.visualizeLine(origin, api.vec.offsetAlong(origin, e.fwd, hit.distance), '#ff0000')
    av.aeb = true
    input.actions.throttle = 0
    var b = Math.min(1, 0.3 + (need - hit.distance) / need)
    if (b > (input.actions.brake || 0)) input.actions.brake = b
    api.watch('av.aeb', hit.distance)
  }
  return {}
}
